window.CP_ITEMS=window.CP_ITEMS||{};window.CP_ITEMS["山水"]=[{"uid":"f865e685-cc9b-4edc-b254-6326223ef92c","title":"伤大理谢少卿","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["旧馆绝逢迎，新诗何处呈。","空留封禅草，已作岱宗行。","柳蠹风吹析，堦崩雪遶平。","无因重来此，剩哭两三声。"],"theme":"悼亡挽歌","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["山","雪"],"cats":{"抒情":["伤感","悼亡","感恩"],"山水":["泰山"]},"theme_conf":0.96},{"uid":"3d449437-09a5-462b-86e5-e1ff2fdfc832","title":"东楼","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["万里流沙道，西征过北门。","但添新战骨，不返旧征魂。","楼角临风迥，城阴带水昏。","传声看驿使，送节向河源。"],"theme":"送别","theme2":["羁旅思乡"],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":["楼"],"cats":{"抒情":["思乡"],"山水":["黄河"]},"theme_conf":0.577},{"uid":"b6bc3e4b-f9b7-4739-a06b-53d1dd2d940d","title":"送人归台州","author":"施肩吾","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["莫驱归骑且徘徊，更遣离情四五桮。","醉后不忧迷客路，遥看瀑布识天台。"],"theme":"送别","theme2":[],"style":"旷达","style2":[],"mood":"愁怨","mood2":[],"scene":["楼"],"cats":{"山水":["瀑布"]},"theme_conf":0.702},{"uid":"2aa4faf5-71fb-4721-a191-4bb415b7ee8a","title":"唐封泰山乐章 豫和六首 六","author":"张说","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["享帝享亲，维孝维圣。","缉熙懿德，敷扬成命。","华夷志同，笙镛礼盛。","明灵降止，感此诚敬。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"山水":["泰山"]},"theme_conf":1.0},{"uid":"e8f030b1-9e72-4243-92b3-3c4ec8028354","title":"渔父歌 二","author":"张志和","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["钓台渔父褐为裘，两两三三舴艋舟。","能纵櫂，惯乘流，长江白浪不曾忧。"],"theme":"山水田园","theme2":["亲情"],"style":"冲淡","style2":[],"mood":"愁怨","mood2":[],"scene":["江"],"cats":{"山水":["长江"],"人物":["父亲"]},"theme_conf":0.613},{"uid":"62492dd9-477c-4ce8-af80-cf9f9f895a3f","title":"自淇涉黄河途中作十三首 五","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["东入黄河水，茫茫泛纡直。","北望太行山，峨峨半天色。","山河相暎带，深浅未可测。","自昔有贤才，相逢不相识。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["江","山"],"cats":{"山水":["江河","黄河"]},"theme_conf":0.76},{"uid":"cpa864df177f8250","title":"暗香","author":"姜夔","dynasty":"宋","section":"宋词","form":"词","paragraphs":["旧时月色。","算几番照我，梅边吹笛。","唤起玉人，不管清寒与攀摘。","何逊而今渐老，都忘却、春风词笔。","但怪得、竹外疏花，香冷入瑶席。","江国。","正寂寂。","叹寄与路遥，夜雪初积。","翠尊易泣。","红萼无言耿相忆。","长记曾携手处，千树压、西湖寒碧。","又片片、吹尽也，几时见得。"],"theme":"爱情相思","theme2":["送别"],"style":"幽峭","style2":["绮丽","婉约"],"mood":"孤寂","mood2":["悲怆"],"scene":["花","月"],"cats":{"山水":["西湖"],"天气":["月亮"],"植物":["梅花"]},"theme_conf":0.604},{"uid":"d549304d-762c-49d7-a661-d008586a3ec1","title":"大觉高僧兰若","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["巫山不见庐山远，松林兰若秋风晚。","一老犹鸣日暮钟，诸僧尚乞斋时饭。","香炉峰色隐晴湖，种杏仙家近白榆。","飞锡去年啼邑子，献花何日许门徒。"],"theme":"佛道禅颂","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["山"],"cats":{"抒情":["思念"],"山水":["庐山"]},"theme_conf":0.93},{"uid":"ab76c0fc-144b-4884-a054-efec2987e260","title":"和谒孔子庙","author":"刘斌","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["性与虽天纵，主世乃无由。","何言泰山毁，空惊逝水流。","及门思往烈，入室想前修。","寂寞荒堦暮，摧残古木秋。","遗风暧如此，聊以慰蒸求。"],"theme":"咏史怀古","theme2":["悼亡挽歌"],"style":"冲淡","style2":["沉郁"],"mood":"孤寂","mood2":[],"scene":["山"],"cats":{"抒情":["孤独","悼亡","怀古"],"山水":["泰山"]},"theme_conf":0.501},{"uid":"bbe30e55-8238-495c-bcf9-8144fe363439","title":"自淇涉黄河途中作十三首 六","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["秋日登滑台，台高秋已暮。","独行既未惬，怀土怅无趣。","晋宋何萧条，羌胡散驰骛。","当时无战略，此地即边戍。","兵革徒自勤，山河孰云固。","乘闲喜临眺，感物伤游寓。","惆怅落日前，飘飖远帆处。","北风吹万里，南雁不知数。","归意方浩然，云沙更廻互。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"惆怅","mood2":["孤寂","欢愉"],"scene":["江","秋","舟"],"cats":{"抒情":["孤独"],"四季":["秋天"],"山水":["江河","黄河"],"人生":["战争"]},"theme_conf":1.0},{"uid":"1487452b-5f49-4f4f-9913-1f3ec1cddf95","title":"饯别王十一南游","author":"刘长卿","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["望君烟水阔，挥手泪沾巾。","飞鸟没何处，青山空向人。","长江一帆远，落日五湖春。","谁见汀洲上，相思愁白苹。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["冲淡"],"mood":"相思","mood2":["愁怨"],"scene":["江"],"cats":{"抒情":["离别","思念","伤感"],"山水":["长江"]},"theme_conf":0.768},{"uid":"ae2ca5e0-6550-4704-8c4f-41d44eb616ef","title":"舞曲歌辞 独漉歌","author":"王建","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["独独漉漉，鼠食猫肉。","乌日中，鹤露宿，黄河水直人心曲。"],"theme":"讽喻刺世","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["江"],"cats":{"抒情":["孤独"],"山水":["黄河"]},"theme_conf":0.9},{"uid":"0003f6ab-a650-4728-acf0-7d248dd3ca3c","title":"寄题江外草堂","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["我生性放诞，雅欲逃自然。","嗜酒爱风竹，卜居必林泉。","遭乱到蜀江，卧疴遣所便。","诛茅初一亩，广地方连延。","经营上元始，断手宝应年。","敢谋土木丽，自觉面势坚。","台亭随高下，敞豁当清川。","虽有会心侣，数能同钓船。","干戈未偃息，安得酣歌眠。","蛟龙无定窟，黄鹄摩苍天。","古来达士志，宁受外物牵。","顾惟鲁钝姿，岂识悔吝先。","偶携老妻去，惨澹凌风烟。","事迹无固必，幽贞媿双全。","尚念四小松，蔓草易拘缠。","霜骨不甚长，永为邻里怜。"],"theme":"山水田园","theme2":["送别","咏物"],"style":"冲淡","style2":["旷达","豪放"],"mood":"恬淡","mood2":[],"scene":["江","元宵"],"cats":{"山水":["江河"],"节日":["元宵节"]},"theme_conf":0.353},{"uid":"6bfd22e0-4623-4efc-9678-a4d436cde303","title":"江南弄","author":"芮挺章","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["春江可怜事，最在美人家。","鹦鹉能言鸟，芙蓉巧笑花。","地衔金作埒，水抱玉为沙。","薄晚青丝骑，长鞭赴狭斜。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["江南","江"],"cats":{"山水":["江河"],"人物":["女子"]},"theme_conf":0.65},{"uid":"8e8e6eed-cb19-49b2-979a-ec1d3a0e3729","title":"萧宅二三子赠答诗二十首 竹请客","author":"卢仝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["我本泰山阿，避地到南国。","主人欲移家，我亦要归北。","上客幸先归，愿托归飞翼。","唯将翛翛风，累路报恩德。"],"theme":"咏物","theme2":["羁旅思乡"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["山"],"cats":{"抒情":["思乡"],"山水":["泰山"],"植物":["竹子"]},"theme_conf":0.9},{"uid":"bb93206b-92a8-4440-aeb5-4cc3bbe596ea","title":"送僧方及南谒柳员外","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["昔事庐山远，精舍虎溪东。","朝阳照瀑水，楼阁虹霓中。","骋望羡游云，振衣若秋蓬。","旧房闭松月，远思吟江风。","古寺历头陀，奇峰扳祝融。","南登小桂岭，却望归塞鸿。","衣裓贮文章，自言学雕虫。","抢榆念陵厉，覆篑图穹崇。","远郡多暇日，有诗访禅宫。","石门耸峭绝，竹院含空蒙。","幽响滴岩溜，晴芳飘野丛。","海云悬飓母，山果属狙公。","忽忆吴兴郡，白苹正葱茏。","愿言挹风采，邈若窥华嵩。","桂水夏澜急，火山宵焰红。","三衣濡菌露，一锡飞烟空。","勿谓翻译徒，不为文雅雄。","古来赏音者，燋爨得孤桐。"],"theme":"送别","theme2":["哲理悟道","送别"],"style":"幽峭","style2":["冲淡"],"mood":"相思","mood2":["孤寂"],"scene":["山"],"cats":{"抒情":["思念","孤独"],"山水":["庐山"],"天气":["彩虹","太阳"],"人生":["哲理"],"植物":["柳树"]},"theme_conf":0.92},{"uid":"6ec03821-1ece-4cdc-97cb-c7b976ac47b1","title":"自淇涉黄河途中作十三首 二","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["清晨泛中流，羽族满汀渚。","黄鹄何处来，昂藏寡俦侣。","飞鸣无人见，饮啄岂得所。","云汉尔固知，胡为不轻举。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["江"],"cats":{"抒情":["孤独"],"山水":["黄河"]},"theme_conf":1.0},{"uid":"ef3c51b2-f0a5-4d9b-8ae3-2a24b342ddee","title":"新乐府 隋堤柳\t悯亡国也","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["隋堤柳，岁久年深尽衰朽。","风飘飘兮雨萧萧，三株两株汴河口。","老枝病叶愁杀人，曾经大业年中春。","大业年中炀天子，种柳成行夹流水。","西自黄河东至淮，绿阴一千三百里。","大业末年春暮月，柳色如烟絮如雪。","南幸江都恣佚游，应将此柳系龙舟。","紫髯郎将护锦缆，青娥御史直迷楼。","海内财力此时竭，舟中歌笑何日休。","上荒下困势不久，宗社之危如缀旒。","炀天子，自言福祚长无穷，岂知皇子封酅公。","龙舟未过彭城合，义旗已入长安宫。","萧墙祸生人事变，晏驾不得归秦中。","土坟数尺何处葬，吴公台下多悲风。","二百年来汴河路，沙草和烟朝复暮。","后王何以鉴前王，请看隋堤亡国树。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":["清新"],"mood":"欢愉","mood2":[],"scene":["江","端午","楼","舟","春"],"cats":{"抒情":["伤感","怀古"],"四季":["春天"],"山水":["黄河"],"节日":["端午节"],"植物":["柳树"]},"theme_conf":0.92},{"uid":"8bbd3aaa-c910-4c4a-89d5-bc04a6ec6ca7","title":"同樊润州游郡东山","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["北固多陈迹，东山复盛游。","铙声发大道，草色引行驺。","此地何时有，长江自古流。","频随公府步，南客寄徐州。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["江","山"],"cats":{"山水":["长江"]},"theme_conf":0.532},{"uid":"4b6c721e-3383-47a7-ab92-d04732ab8d61","title":"九曲词三首 三","author":"高适","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["铁骑横行铁岭头，西看逻逤取封侯。","青海只今将饮马，黄河不用更防秋。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["江","秋"],"cats":{"四季":["秋天"],"山水":["黄河"]},"theme_conf":1.0},{"uid":"ea3f7ed0-3704-4ff2-aa5e-1727b20e3a7c","title":"安公房问法","author":"张继","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["流年一日复一日，世事何时是了时。","试向东林问禅伯，遣将心地学琉璃。"],"theme":"佛道禅颂","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":[],"cats":{"山水":["庐山"],"人生":["哲理","时光"]},"theme_conf":0.96},{"uid":"280875c7-9ec4-4d0e-9022-ecf6b1d67705","title":"夜归孤山寺却寄卢郎中","author":"许浑","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["青山有志路犹赊，心在琴书自忆家。","醉别庾楼山色晓，夜归萧寺月光斜。","落帆露湿回塘柳，别院风惊满地花。","他日此身须报德，莫言空爱旧烟霞。"],"theme":"寄赠酬答","theme2":["哲理悟道"],"style":"沉郁","style2":["清新"],"mood":"孤寂","mood2":[],"scene":["夜","山","月"],"cats":{"抒情":["孤独"],"山水":["西湖"]},"theme_conf":0.86},{"uid":"632dc421-6fac-46f6-9e92-590d5adfb994","title":"题汉州西湖","author":"严公贶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["凤沼才难尽，余思凿西湖。","珍木罗修岸，冰光映坐隅。","琴台今寂寞，竹岛尚萦纡。","犹蕴济川志，芳名终不渝。"],"theme":"咏物","theme2":["山水田园"],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["江南","江"],"cats":{"抒情":["孤独"],"山水":["西湖"]},"theme_conf":0.62},{"uid":"e7b46a9e-9dd8-444c-baa2-645422ee243a","title":"早春钱塘湖晚眺","author":"张祜","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["落日下林坂，抚襟睇前踪。","轻澌流回浦，残雪明高峰。","仰视天宇旷，俯登云树重。","聊当问真界，昨夜西峦钟。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春","江南","江","雪"],"cats":{"四季":["春天"],"山水":["西湖"]},"theme_conf":1.0},{"uid":"785ea8b0-4589-4ea2-a01c-226a2556dbe5","title":"题玄武禅师屋壁","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["何年顾虎头，满壁画瀛州。","赤日石林气，青天江海流。","锡飞常近鹤，桮度不惊鸥。","似得庐山路，真随惠远游。"],"theme":"哲理悟道","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"山水":["庐山"],"人生":["哲理"]},"theme_conf":0.768},{"uid":"22c07619-9423-4f39-be66-e5380527651b","title":"郊庙歌辞 封泰山乐章 太和","author":"张说","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["孝敬中发，和容外彰。","腾华照宇，如升太阳。","贞璧就奠，玄灵垂光。","礼乐具举，济济洋洋。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"山水":["泰山"]},"theme_conf":1.0},{"uid":"4ac5a760-055d-4c66-bf4c-9baf38b78e2c","title":"送庐山人归林虑山","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["无论行远近，归向旧烟林。","寥落人家少，青冥鸟道深。","白云长满目，芳草自知心。"],"theme":"送别","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["山"],"cats":{"山水":["庐山"]},"theme_conf":0.452},{"uid":"b15a6f1f-1730-49e2-8f50-a0a5f7e51e26","title":"松滋江北阻风","author":"阎宽","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["江风久未歇，山雨复相仍。","巨浪天涯起，余寒川上凝。","忧人劳夕惕，乡事惫晨兴。","远听知音骇，诚哉不可陵。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["江"],"cats":{"抒情":["友情","思乡"],"山水":["江河"],"天气":["写风"]},"theme_conf":0.534},{"uid":"306c2503-eff5-418b-873e-c72596a676bd","title":"杂曲歌辞 春江曲","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["春江无云潮水平，蒲心出水凫雏鸣。","长干夫壻爱远行，自染春衣缝已成。","妾身生长金陵侧，去年随夫住江北。","春来未到父母家，舟小风多渡不得。","欲辞舅姑先问人，私向江头祭水神。"],"theme":"闺情宫怨","theme2":["亲情","山水田园"],"style":"悲慨","style2":[],"mood":"惆怅","mood2":[],"scene":["江","春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"山水":["江河"]},"theme_conf":0.85},{"uid":"0e4aa75a-c9d0-42d6-b470-3c933525d99d","title":"咏怀二首 一","author":"李贺","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["长卿怀茂陵，绿草垂石井。","弹琴看文君，春风吹鬓影。","梁王与武帝，弃之如断梗。","惟留一简书，金泥泰山顶。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["山"],"cats":{"山水":["泰山"]},"theme_conf":1.0},{"uid":"b47c9575-fe60-44e4-92f7-94386b4d512f","title":"春和杜相公移入长兴宅奉呈诸宰执","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["欲向幽偏适，还从绝地移。","秦官鼎食贵，尧世土阶卑。","戟户槐阴满，书窗竹叶垂。","才分午夜漏，遥隔万年枝。","北阙深恩在，东林远梦知。","日斜门掩暎，山远树参差。","论道齐鸳翼，题诗忆凤池。","从公亦何幸，长与珮声随。"],"theme":"应制干谒","theme2":["山水田园"],"style":"绮丽","style2":[],"mood":"相思","mood2":["欢愉"],"scene":["春","夜"],"cats":{"抒情":["思念"],"四季":["春天"],"山水":["庐山"]},"theme_conf":0.95},{"uid":"d9dd3520-9aab-4b1b-bd57-810f29391667","title":"江州重别薛六柳八二员外","author":"刘长卿","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["生涯岂料承优诏，世事空知学醉歌。","江上月明胡鴈过，淮南木落楚山多。","寄身且喜沧洲近，顾影无如白发何。","今日龙钟人共弃，媿君犹遣慎风波。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":["江"],"cats":{"抒情":["离别"],"山水":["江河"],"植物":["柳树"]},"theme_conf":0.863},{"uid":"7e30c468-9d80-4b8c-9a87-1276b583687a","title":"夜闻江南人家赛神因题即事","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["南方淫祀古风俗，楚妪解唱迎神曲。","鎗鎗铜鼓芦叶深，寂寂琼筵江水绿。","雨过风清洲渚闲，椒浆醉尽迎神还。","帝女凌空下湘岸，番君隔浦向尧山。","月隐回塘犹自舞，一门依倚神之祜。","韩康灵药不复求，扁鹊医方曾莫覩。","逐客临江空自悲，月明流水无已时。","听此迎神送神曲，携觞欲吊屈原祠。"],"theme":"节令风俗","theme2":["送别","羁旅思乡","闲适隐逸"],"style":"冲淡","style2":["清新"],"mood":"孤寂","mood2":["悲怆"],"scene":["江","江南"],"cats":{"抒情":["思乡","伤感"],"山水":["江河"],"节日":["端午节"]},"theme_conf":0.85},{"uid":"cpb21db1402576f8","title":"西河","author":"周邦彦","dynasty":"宋","section":"宋词","form":"词","paragraphs":["佳丽地。","南朝盛事谁记。","山围故国绕清江，髻鬟对起。","怒涛寂寞打孤城，风樯遥度天际。","断崖树，犹倒倚。","莫愁艇子曾系。","空馀旧迹郁苍苍，雾沈半垒。","夜深月过女墙来，赏心东望淮水。","酒旗戏鼓甚处市。","想依稀、王谢邻里。","燕子不知何世。","入寻常、巷陌人家，相对如说兴亡，斜阳里。"],"theme":"咏史怀古","theme2":[],"style":"冲淡","style2":["沉郁","清新"],"mood":"孤寂","mood2":[],"scene":["酒","夜","月"],"cats":{"抒情":["孤独","怀古"],"山水":["江河"]},"theme_conf":0.741},{"uid":"0bed9b02-991e-4e28-b631-86640147a712","title":"宿建德江","author":"孟浩然","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["移舟泊烟渚，日暮客愁新。","野旷天低树，江清月近人。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["清新"],"mood":"愁怨","mood2":[],"scene":["江","月"],"cats":{"抒情":["思乡","伤感"],"山水":["江河"]},"theme_conf":0.647},{"uid":"e5e5f969-ddac-4491-9cfe-d77742e1416d","title":"将进酒","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["君不见黄河之水天上来，奔流到海不复回。","君不见高堂明镜悲白发，朝如青丝暮成雪。","人生得意须尽欢，莫使金樽空对月。","天生我材必有用，千金散尽还复来。","烹羊宰牛且为乐，会须一饮三百杯。","岑夫子，丹丘生，将进酒，君莫停。","与君歌一曲，请君为我侧耳听。","钟鼓馔玉不足贵，但愿长醉不愿醒。","古来圣贤皆寂寞，惟有饮者留其名。","陈王昔时宴平乐，斗酒十千恣讙谑。","主人何为言少钱，径须沽取对君酌。","五花马，千金裘，呼儿将出换美酒，与尔同销万古愁。"],"theme":"咏怀抒感","theme2":["咏物","哲理悟道"],"style":"豪放","style2":[],"mood":"欢愉","mood2":["孤寂"],"scene":["酒"],"cats":{"抒情":["伤感","孤独"],"山水":["黄河"],"食物":["写酒"]},"theme_conf":0.9},{"uid":"af5c3f87-a819-4c5a-9960-4881d6d03273","title":"达奚中丞东斋壁画山水各赋一物得树杪悬泉送长安赵元阳少府","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["素壁画飞泉，从云落树颠。","练垂疑叶响，云幷觉枝偏。","利物得双劒，为儒当一贤。","应思洒尘陌，调膳亦芳鲜。"],"theme":"题画咏艺","theme2":["题画咏艺","送别"],"style":"旷达","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"山水":["瀑布"]},"theme_conf":0.85},{"uid":"0d699470-bc8e-49d9-85e5-b1987b01c2dd","title":"江汉","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["江汉思归客，乾坤一腐儒。","片云天共远，永夜月同孤。","落日心犹壮，秋风病欲疎。","古来存老马，不必取长途。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["慷慨"],"scene":["江"],"cats":{"抒情":["思乡","孤独"],"山水":["江河","长江"]},"theme_conf":1.0},{"uid":"4760fc44-7062-447a-ad4f-579453cc556e","title":"句","author":"幸夤逊","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["苦教作镇居中国，争得泥金在泰山。","才闻暖律先偷眼，既待和风始展眉。","蒙君知重惠琼实，薄起金刀钉玉深。","嚼处春冰敲齿冷，咽时雪液沃心寒。","深妆玉瓦平无垅，乱拂芦花细有声。","日回禽影穿疎木，风递猨声入小楼。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["婉约","幽峭"],"mood":"愁怨","mood2":[],"scene":["山","雪","冬"],"cats":{"抒情":["闺怨"],"山水":["泰山"]},"theme_conf":1.0},{"uid":"7f92251f-8521-4f44-ac7f-2cb17365e348","title":"同皇甫冉赴官留别灵一上人","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["法许庐山远，诗传休上人。","独归双树宿，静与百花亲。","对物虽留兴，观空已悟身。","能令折腰客，遥赏竹房春。"],"theme":"送别","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["欢愉","恬淡"],"scene":["山"],"cats":{"抒情":["离别","孤独"],"山水":["庐山"]},"theme_conf":0.553},{"uid":"c23fcb9d-ed9e-4289-b0bb-c54e2b39ca6e","title":"寄庐山真上人","author":"李端","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["高僧无迹本难寻，更得禅行去转深。","青草湖中看五老，白云山上宿双林。","月明潭色澄空性，夜静猨声证道心。","更[说谢]公南座好，烟萝到地几重阴。"],"theme":"寄赠酬答","theme2":["送别","山水田园"],"style":"冲淡","style2":["清新"],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"山水":["庐山"]},"theme_conf":0.76},{"uid":"1d7ec3cb-95db-45a4-9cac-1d00de533802","title":"九曲词三首 一","author":"高适","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["许国从来彻庙堂，连年不为在疆塲。","将军天上封侯印，御史台中异姓王。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":[],"cats":{"山水":["黄河"]},"theme_conf":1.0},{"uid":"7af5f435-0357-4ff6-ab62-97417d87a31a","title":"相和歌辞 日出行","author":"李贺","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["白日下崐崘，发光如舒丝。","徒照葵藿心，不照游子悲。","折折黄河曲，日从中央转。","旸谷耳曾闻，若木眼不见。","奈何铄石，胡为销人。","羿弯弓属矢那不中，足令久不得奔，讵教晨光夕昏。"],"theme":"边塞征战","theme2":["亲情"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["惆怅"],"scene":["江","夏"],"cats":{"抒情":["伤感"],"山水":["黄河"],"天气":["太阳"]},"theme_conf":0.6},{"uid":"53e02f22-5213-4ef0-8258-451dfe9d5052","title":"江州赴忠州至江陵已来舟中示舍弟五十韵","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["昔作咸秦客，常思江海行。","今来仍尽室，此去又专城。","典午犹为幸，分忧固是荣。","箳篂州乘送，艛艓驿船迎。","共载皆妻子，同游即弟兄。","宁辞浪迹远，且贵赏心幷。","云展帆高挂，飙驰櫂迅征。","溯流从汉浦，循路转荆衡。","山逐时移色，江随地改名。","风光近东早，水木向南清。","夏口烟孤起，湘川雨半晴。","日煎红浪沸，月射白砂明。","北渚寒留雁，南枝暖待莺。","骈朱桃露萼，点翠柳含萌。","亥市鱼盐聚，神林鼓笛鸣。","壶浆椒叶气，歌曲竹枝声。","系缆怜沙静，垂纶爱岸平。","水飡红粒稻，野茹紫花菁。","瓯泛茶如乳，台黏酒似饧。","脍长抽锦缕，藕脆削琼英。","容易来千里，斯须进一程。","未曾劳气力，渐觉有心情。","卧稳添春睡，行迟带酒酲。","忽愁牵世网，便欲濯尘缨。","早接文场战，曾争翰苑盟。","掉头称俊造，翘足取公卿。","且昧随时义，徒输报国诚。","众排恩易失，偏压势先倾。","虎尾忧危切，鸿毛性命轻。","烛蛾谁救活，蚕茧自缠萦。","歛手辞双阙，回眸望两京。","长沙抛贾谊，漳浦卧刘桢。","𫛸鴂鸣还歇，蟾蜍破又盈。","年光同激箭，乡思极摇旌。","潦倒亲知笑，衰羸旧识惊。","乌头因感白，鱼尾为劳頳。","劒学将何用，丹烧竟不成。","孤舟萍一叶，双鬓雪千茎。","老见人情尽，闲思物理精。","如汤探冷热，似博鬬输赢。","险路应须避，迷途莫共争。","此心知止足，何物要经营。","玉向泥中洁，松经雪后贞。","无妨隐朝市，不必谢寰瀛。","但在前非悟，期无后患婴。","多知非景福，少语是元亨。","晦即全身药，明为伐性兵。","昏昏随世俗，蠢蠢学黎甿。","鸟以能言{构木=糸}，龟缘入梦烹。","知之一何晚，犹足保余生。"],"theme":"亲情","theme2":["山水田园","闲适隐逸"],"style":"沉郁","style2":["绮丽","幽峭"],"mood":"愁怨","mood2":["慷慨","恬淡"],"scene":["舟","江"],"cats":{"抒情":["伤感","爱国"],"山水":["江河"],"人生":["战争"]},"theme_conf":0.85},{"uid":"b3b9d6ef-b19c-4429-b799-db527e8907a4","title":"陪王汉州留杜绵州泛房公西湖","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["旧相恩追后，春池赏不稀。","阙庭分未到，舟楫有光辉。","豉化莼丝熟，刀鸣[鲙]缕飞。","使君双皂盖，滩浅正相依。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["江南","园林","江"],"cats":{"山水":["西湖"]},"theme_conf":0.65},{"uid":"1e1e7436-6f97-47ee-8d91-e540fe2b1edc","title":"相和歌辞 江南曲","author":"于鹄","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["偶向江边采白苹，还随女伴赛江神。","众中不敢分明语，暗掷金钱卜远人。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["江南","江"],"cats":{"抒情":["闺怨"],"山水":["江河"]},"theme_conf":1.0},{"uid":"df4bd05c-a0a4-4c19-8e8d-ada2db3ccbf2","title":"临邑舍弟书至苦雨黄河泛溢隄防之患簿领所忧因寄此诗用宽其意","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["二仪积风雨，百谷漏波涛。","闻道洪何坼，遥连沧海高。","职思忧悄悄，郡国诉嗷嗷。","舍弟卑栖邑，防川领簿曹。","尺书前日至，版筑不时操。","难假鼋鼍力，空瞻乌鹊毛。","燕南吹畎亩，济上没蓬蒿。","螺蚌满近郭，蛟螭乘九臯。","徐关深水府，碣石小秋毫。","白屋留孤树，清天矢万艘。","吾衰同泛梗，利涉想蟠桃。","倚赖天涯钓，犹能掣巨鼇。"],"theme":"山水田园","theme2":["送别"],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["雨","江"],"cats":{"山水":["黄河"],"天气":["写雨"]},"theme_conf":0.53},{"uid":"63950163-6a10-4e74-af8a-09886e4ef2a8","title":"登鹳雀楼","author":"王之涣","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["白日依山尽，黄河入海流。","欲穷千里目，更上一层楼。"],"theme":"山水田园","theme2":["哲理悟道","咏史怀古"],"style":"冲淡","style2":[],"mood":"慷慨","mood2":[],"scene":["楼"],"cats":{"抒情":["怀古"],"山水":["黄河"]},"theme_conf":0.375},{"uid":"c222b6d5-2eb5-4603-84ed-b5afef260fae","title":"河口逢江州朱道士因听琴","author":"卢纶","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["庐山道士夜携琴，映月相逢辨语音。","引坐霜中弹一弄，满船商客有归心。"],"theme":"题画咏艺","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["山","江"],"cats":{"抒情":["思乡"],"山水":["庐山","江河"]},"theme_conf":0.56},{"uid":"2693b5ba-1e9a-4d8b-a415-dfc484c9efa9","title":"正乐府十篇 农父谣","author":"皮日休","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["农父冤辛苦，向我述其情。","难将一人农，可备十人征。","如何江淮粟，挽漕输咸京。","黄河水如电，一半沈与倾。","均输利其事，职司安敢评。","三川岂不农，三辅岂不耕。","奚不车其粟，用以供天兵。","美哉农父言，何计达王程。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["江"],"cats":{"山水":["黄河"],"人物":["父亲"]},"theme_conf":0.533},{"uid":"dda856a1-8f74-47cf-bf5a-978a277d670c","title":"入庐山仰望瀑布水","author":"张九龄","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["绝顶有悬泉，喧喧出烟杪。","不知几时岁，但见无昏晓。","闪闪青崖落，鲜鲜白日皎。","洒流湿行云，溅沫惊飞鸟。","雷吼何喷薄，箭驰入窈窕。","昔闻山下蒙，今乃林峦表。","物情有诡激，坤元曷纷矫。","默然置此去，变化谁能了。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"山水":["庐山","瀑布"]},"theme_conf":1.0},{"uid":"cp6327af1ef41d9d","title":"菩萨蛮","author":"辛弃疾","dynasty":"宋","section":"宋词","form":"词","paragraphs":["郁孤台下清江水。","中间多少行人泪。","西北是长安。","可怜无数山。","青山遮不住。","毕竟江流去。","江晚正愁予。","山深闻鹧鸪。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["江","山"],"cats":{"抒情":["伤感","怀古"],"山水":["江河"]},"theme_conf":0.84},{"uid":"30a03a87-348d-477a-9f49-962ce991f8a8","title":"詶皇甫侍御望天灊山见示之作","author":"独孤及","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["早岁慕五岳，尝为尘机碍。","孰知天柱峰，今与郡斋对。","隐嶙抱元气，氤氲含青霭。","云崖媚远空，石壁寒古塞。","汉皇南游日，望秩此昭配。","法驾到谷口，礼容振荒外。","焚柴百神趋，执玉万方会。","天旋物顺动，德布泽霶霈。","讲武威已耀，学仙功未艾。","黄金竟何成，洪业遽沦昧。","度世若一瞬，昨朝已千载。","如今封禅坛，唯见云雨晦。","长望哀往古，劳生惭大块。","清晖幸相娱，幽独知所赖。","寒城春方正，初日明可爱。","万殊喜阳和，余亦荷时泰。","山色日夜绿，下有清浅濑。","愧作拳偻人，沈迷簿书内。","登临叹拘限，出处悲老大。","况听郢中曲，复识湘南态。","思免物累牵，敢令道机退。","瞒然诵佳句，持此秋兰佩。"],"theme":"山水田园","theme2":["应制干谒"],"style":"清新","style2":["冲淡","悲慨"],"mood":"悲怆","mood2":["孤寂","相思"],"scene":["山"],"cats":{"抒情":["伤感","孤独"],"山水":["泰山"]},"theme_conf":0.359},{"uid":"faaf019b-5e60-4094-a7a6-754762ed30df","title":"重忆山居六首 泰山石","author":"李德裕","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["鸡鸣日观望，远与扶桑对。","沧海似镕金，众山如点黛。","遥知碧峰首，独立烟岚内。","此石依五松，苍苍几千载。"],"theme":"山水田园","theme2":[],"style":"幽峭","style2":["雄浑"],"mood":"相思","mood2":[],"scene":["山"],"cats":{"抒情":["思念"],"山水":["泰山"]},"theme_conf":1.0},{"uid":"793368a9-a932-42cc-bf9c-e959f80b45eb","title":"京口怀古","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["大江横万里，古渡渺千秋。","浩浩波声险，苍苍天色愁。","三方归汉鼎，一水限吴州。","霸国今何在，清泉长自流。"],"theme":"咏史怀古","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":[],"scene":["秋","江","江南"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"],"山水":["长江"]},"theme_conf":0.693},{"uid":"fdc07d9f-95b8-45f7-b1b3-9d272b3416a4","title":"秋日登吴公台上寺远眺寺即陈将吴明彻战场","author":"刘长卿","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["古台摇落后，秋日望乡心。","野寺人来少，云峰水隔深。","夕阳依旧垒，寒磬满空林。","惆怅南朝事，长江独至今。"],"theme":"咏史怀古","theme2":["哲理悟道","边塞征战","羁旅思乡"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["惆怅"],"scene":["秋","江"],"cats":{"抒情":["思乡","孤独","怀古"],"四季":["秋天"],"山水":["长江"],"天气":["太阳"],"人生":["战争"]},"theme_conf":0.242},{"uid":"18a2aaed-39a3-4ec2-a730-4479ec0b94ec","title":"孤山寺遇雨","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["拂波云色重，洒叶雨声繁。","水鹭双飞起，风荷一向翻。","空蒙连北岸，萧飒入东轩。","或拟湖中宿，留船在寺门。"],"theme":"哲理悟道","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["雨","山"],"cats":{"抒情":["孤独"],"山水":["西湖"],"天气":["写雨"]},"theme_conf":0.564},{"uid":"00378596-0b01-448f-bb44-617317621bfe","title":"中和初童谣","author":"不详","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["黄巢走，泰山东，死在翁家翁。"],"theme":"讽喻刺世","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["山"],"cats":{"山水":["泰山"],"人物":["儿童"]},"theme_conf":0.82},{"uid":"cp414766c933671c","title":"高阳台","author":"周密","dynasty":"宋","section":"宋词","form":"词","paragraphs":["照野旌旗，朝天车马，平沙万里天低。","宝带金章，尊前茸帽风。","秦关汴水经行地，想登临、都付新诗。","纵英游，叠鼓清笳，骏马名姬。","酒酣应对燕山雪，正冰河月冻，晓陇云飞。","投老残年，江南谁念方回。","东风渐绿西湖柳，雁已还、人未南归。","最关情，折尽梅花，难寄相思。"],"theme":"送别","theme2":["爱情相思","民生疾苦","送别"],"style":"清新","style2":["豪放"],"mood":"相思","mood2":[],"scene":["江南","冬","鸟","江"],"cats":{"抒情":["爱情","思念"],"山水":["西湖"]},"theme_conf":0.92},{"uid":"a8be14f6-49ea-4e59-ad37-30bcf16e17a6","title":"忆友怀野寺旧居","author":"李端","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["自嫌野性共人疎，忆向西林更结庐。","寄谢山阴许都讲，昨来频得远公书。"],"theme":"哲理悟道","theme2":["闲适隐逸","送别"],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["山"],"cats":{"抒情":["友情","思念"],"山水":["庐山"]},"theme_conf":0.393},{"uid":"66e31443-c3ec-4c2a-8c39-bdb2d589aa29","title":"寄李十员外","author":"王仲舒","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["百丈悬泉旧卧龙，欲将肝胆佐时雍。","惟愁又入烟霞去，知在庐峰第几重。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["山"],"cats":{"抒情":["伤感"],"山水":["瀑布"]},"theme_conf":0.95},{"uid":"40a92675-3a77-4ce1-9242-17eb287a246a","title":"渡江秋怨二首 二","author":"权德舆","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["渡秋江兮渺然，望秋月兮婵娟。","色如练，万里徧，我有所思兮不得见。","不得见兮露寒水深，耿遥夜兮伤心。"],"theme":"闺情宫怨","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":[],"scene":["秋","江"],"cats":{"抒情":["伤感","闺怨"],"四季":["秋天"],"山水":["江河"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":1.0},{"uid":"a2c48eae-6285-411b-af3d-bb24b2520d4e","title":"越王楼歌","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["緜州州府何磊落，显庆年中越王作。","孤城西北起高楼，碧瓦朱甍照城郭。","楼下长江百丈清，山头落日半轮明。","君王旧迹今人赏，转见千秋万古情。"],"theme":"咏史怀古","theme2":[],"style":"雄浑","style2":[],"mood":"孤寂","mood2":[],"scene":["江","楼","江南"],"cats":{"抒情":["孤独","怀古"],"山水":["长江"]},"theme_conf":0.88},{"uid":"19387623-b6c7-4a43-90c0-6c2208eab545","title":"和太原张相公山亭怀古","author":"高铢","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["鬬石类岩𪩘，飞流泻潺湲。","远壑簷宇际，孤峦雉堞间。","何必到海岳，境幽机自闲。","兹焉得高趣，高步谢东山。"],"theme":"咏史怀古","theme2":[],"style":"旷达","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["山"],"cats":{"抒情":["孤独","怀古"],"山水":["瀑布"]},"theme_conf":0.483},{"uid":"6767b044-44d9-46ee-b87b-33bfcb381ba0","title":"哭遂州萧侍郎二十四韵","author":"李商隐","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["遥作时多难，先令祸有源。","初惊逐客议，旋骇党人冤。","密侍荣方入，司刑望愈尊。","皆因优诏用，实有谏书存。","苦雾三辰没，穷阴四塞昏。","虎威狐更假，隼击鸟逾喧。","徒欲心存阙，终遭耳属垣。","遗音和蜀魄，易箦对巴猿。","有女悲初寡，无男泣过门。","朝争屈原草，庙馁莫敖魂。","迥阁伤神峻，长江极望翻。","青云宁寄意，白骨始沾恩。","早岁思东合，为邦属故园。","登舟惭郭泰，解榻愧陈蕃。","分以忘年契，情犹锡类敦。","公先真帝子，我系本王孙。","啸傲张高盖，从容接短辕。","秋吟小山桂，春醉后堂萱。","自叹离通籍，何尝忘呌阍。","不成穿圹入，终拟上书论。","多士还鱼贯，云谁正骏奔。","暂能诛儵忽，长与问乾坤。","蚁漏三泉路，螀啼百草根。","始知同泰讲，徼福是虚言。"],"theme":"悼亡挽歌","theme2":[],"style":"悲慨","style2":["沉郁"],"mood":"悲怆","mood2":[],"scene":["江"],"cats":{"抒情":["思乡","伤感","悼亡"],"山水":["长江"],"节日":["端午节"]},"theme_conf":0.96},{"uid":"ae6937be-51cb-4b1f-b735-cfa0644fd547","title":"相和歌辞 江南曲八首 五","author":"刘希夷","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["舣舟乘潮去，风帆振草凉。","潮平见楚甸，天际望维扬。","洄溯经千里，烟波接两乡。","云明江屿出，日照海流长。","此中逢岁晏，浦树落花芳。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["江","江南"],"cats":{"抒情":["思乡"],"山水":["江河"]},"theme_conf":1.0},{"uid":"889929d5-2846-4b0b-a3ad-1572ec48dfa4","title":"仲夏江阴官舍寄裴明府","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["万室边江次，孤城对海安。","朝霞晴作雨，湿气晚生寒。","苔色侵衣桁，潮痕上井栏。","题诗招茂宰，思尔欲辞官。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["江","夏"],"cats":{"抒情":["孤独"],"四季":["夏天"],"山水":["江河"]},"theme_conf":0.97},{"uid":"cp63eba452c87667","title":"风入松","author":"俞国宝","dynasty":"宋","section":"宋词","form":"词","paragraphs":["一春长费买花钱。","日日醉花边。","玉骢惯识西湖路，骄嘶过、沽酒垆前。","红杏香中箫鼓，绿杨影里秋千。","暖风十里丽人天。","花压髻云偏。","画船载取春归去，馀情寄、湖水湖烟。","明日重扶残醉，来寻陌上花钿。"],"theme":"山水田园","theme2":["送别","闲适隐逸"],"style":"豪放","style2":["绮丽"],"mood":"恬淡","mood2":[],"scene":["酒","花","春","江南"],"cats":{"四季":["春天"],"山水":["西湖"],"天气":["写风"],"人物":["女子"]},"theme_conf":0.393},{"uid":"3ca0e586-2804-4c73-9190-1ccc18267e00","title":"送王府张参军附学及第东归","author":"韩翃","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["邻家不识鬬鸡翁，闭户能齐隐者风。","顾步曾为小山客，成名因事大江公。","一身千里寒芜上，单马重裘腊月中。","寂寂故园行见在，暮天残雪洛城东。"],"theme":"送别","theme2":["羁旅思乡","边塞征战"],"style":"沉郁","style2":["冲淡"],"mood":"孤寂","mood2":[],"scene":["雪","月","山","江","园林"],"cats":{"抒情":["思乡"],"山水":["长江"]},"theme_conf":0.366},{"uid":"80e7683d-5fdb-4cb6-96a0-c6fe3caac9fd","title":"和武相公中秋锦楼玩月 二","author":"崔备","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["四时皆有月，一夜独当秋。","照耀初含露，裴回正满楼。","遥连雪山净，逈入锦江流。","愿以清光末，年年许从游。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":["清新"],"mood":"孤寂","mood2":[],"scene":["中秋","秋","月","楼"],"cats":{"抒情":["孤独"],"四季":["秋天"],"山水":["江河"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.86},{"uid":"f800050a-d7a0-4f12-a614-17fe23df8f41","title":"送杨氏女","author":"韦应物","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["永日方戚戚，出门复悠悠。","女子今有行，大江溯轻舟。","尔辈况无恃，抚念益慈柔。","幼为长所育，两别泣不休。","对此结中肠，义往难复留。","自小阙内训，事姑贻我忧。","赖兹托令门，仁恤庶无尤。","贫俭诚所尚，资从岂待周。","孝恭遵妇道，容止顺其猷。","别离在今晨，见尔当何秋。","居闲始自遣，临感忽难收。","归来视幼女，零泪缘缨流。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["舟","秋"],"cats":{"抒情":["离别","伤感"],"四季":["秋天"],"山水":["长江"]},"theme_conf":1.0},{"uid":"45e93c66-046f-44aa-9752-7e4246ad6c43","title":"自淇涉黄河途中作十三首 八","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["兹川方悠邈，云沙无前后。","古堰对河壖，长林出淇口。","独行非吾意，东向日已久。","忧来谁得知，且酌尊中酒。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["愁怨"],"scene":["酒","江"],"cats":{"抒情":["孤独"],"山水":["江河","黄河"]},"theme_conf":0.65},{"uid":"91019fe2-b58e-4320-a986-6a323847e944","title":"相和歌辞 春江花月夜","author":"张若虚","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["春江潮水连海平，海上明月共潮生。","滟滟随波千万里，何处春江无月明？","江流宛转遶芳甸，月照花林皆似霰。","空里流霜不觉飞，汀上白沙看不见。","江天一色无纤尘，皎皎空中孤月轮。","江畔何人初见月？江月何年初照人？","人生代代无穷已，江月年年望相似。","不知江月待何人，但见长江送流水。","白云一片去悠悠，青枫浦上不胜愁。","谁家今夜扁舟子，何处相思明月楼？","可怜楼上月裴回，应照离人妆镜台。","玉户帘中卷不去，捣衣砧上拂还来。","此时相望不相闻，愿逐月华流照君。","鸿雁长飞光不度，鱼龙潜跃水成文。","昨夜闲潭梦落花，可怜春半不还家。","江水流春去欲尽，江潭落月复西斜。","斜月沈沈藏海雾，碣石潇湘无限路。","不知乘月几人归，落月摇情满江树。"],"theme":"爱情相思","theme2":["送别","羁旅思乡"],"style":"豪放","style2":["沉郁"],"mood":"相思","mood2":[],"scene":["江","月","春"],"cats":{"抒情":["爱情","思念","思乡"],"四季":["春天"],"山水":["江河","长江"],"天气":["月亮"]},"theme_conf":0.75},{"uid":"c824482e-922d-4bcd-9a6c-63b21b20b56d","title":"瀑布寺贞上人院","author":"郑巢","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["林疎多暮蝉，师去宿山烟。","古壁灯熏画，秋琴雨润弦。","竹间窥远鹤，岩上取寒泉。","西岳沙房在，归期更几年。"],"theme":"山水田园","theme2":["哲理悟道"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山","园林","秋","夜","雨"],"cats":{"四季":["秋天"],"山水":["瀑布"]},"theme_conf":0.548},{"uid":"cp0f289616020e5f","title":"念奴娇","author":"辛弃疾","dynasty":"宋","section":"宋词","form":"词","paragraphs":["野棠花落，又匆匆、过了青明时节。","地东风欺客梦，一夜云屏寒怯。","曲岸持觞，垂杨系马，此地曾轻别。","楼空人去，旧游飞燕能说。","闻道绮陌东头，行人长见，帘底纤纤月。","旧恨春江流未断，新恨云山千叠。","料得明朝，尊前重见，镜里花难折。","也应惊问，近来多少华发。"],"theme":"送别","theme2":["羁旅思乡"],"style":"婉约","style2":["清新","沉郁"],"mood":"相思","mood2":["愁怨","孤寂"],"scene":["春","酒"],"cats":{"抒情":["思乡"],"四季":["春天"],"山水":["江河"]},"theme_conf":0.531},{"uid":"d827bbc7-2b82-4437-b81b-5e174dcdc134","title":"石上阁","author":"无名氏","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["水石引我去，南湖复东壑。","不厌随竹阴，来登石上阁。","磴道通石门，欹崖断如凿。","飞梁架峰头，夭矫虹霓若。","下视竹木杪，仰见悬泉落。","水声兼松吹，音响参众乐。","时时为雾雨，飘洒湿帘箔。","吾欲弃簪缨，于兹守寂寞。"],"theme":"山水田园","theme2":[],"style":"幽峭","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["楼","山"],"cats":{"抒情":["孤独"],"山水":["瀑布"],"天气":["彩虹"]},"theme_conf":0.75},{"uid":"34f06c40-fce8-496a-b80d-2a5f2fa28ec3","title":"放言五首 五","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["泰山不要欺毫末，颜子无心羡老彭。","松树千年终是朽，槿花一日自为荣。","何须恋世常忧死，亦莫嫌身漫厌生。","生去死来都是幻，幻人哀乐系何情。"],"theme":"哲理悟道","theme2":[],"style":"旷达","style2":[],"mood":"悲怆","mood2":[],"scene":["山"],"cats":{"山水":["泰山"]},"theme_conf":1.0},{"uid":"f2413b7a-cfda-4d88-8c24-6684aa4bcf8a","title":"七月三日亭午已后较热退晚加小凉稳睡有诗因论壮年乐事戏呈元二十一曹长","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["今兹商用事，余热亦已末。","衰年旅炎方，生意从此活。","亭午减汗流，北邻耐人聒。","晚风爽乌匼，筋力苏摧折。","闭目逾十旬，大江不止渴。","退藏恨雨师，健步闻旱魃。","园蔬抱金玉，无以供采掇。","密云虽聚散，徂暑终衰歇。","前圣眘焚巫，武王亲救暍。","阴阳相主客，时序递回斡。","洒落唯清秋，昏霾一空阔。","萧萧紫塞雁，南向欲行列。","歘思红颜日，霜露冻阶闼。","胡马挟雕弓，鸣弦不虚发。","长鈚逐狡兔，突羽当满月。","惆怅白头吟，萧条游侠窟。","临轩望山阁，缥缈安可越。","高人炼丹砂，未念将朽骨。","少壮迹颇疎，欢乐曾倏忽。","杖藜风尘际，老丑难翦拂。","吾子得神仙，本是池中物。","贱夫美一睡，烦促婴词笔。"],"theme":"边塞征战","theme2":["羁旅思乡"],"style":"绮丽","style2":["沉郁"],"mood":"欢愉","mood2":["慷慨"],"scene":["楼","月","夏"],"cats":{"抒情":["思乡"],"四季":["夏天","秋天"],"山水":["长江"],"天气":["太阳","月亮"],"人生":["青春"],"生活":["边塞"]},"theme_conf":0.448},{"uid":"bee2baa5-b40f-4740-a10e-5633dc1250d8","title":"听夜雨寄卢纶","author":"李端","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["暮雨萧条过凤城，霏霏飒飒重还轻。","闻君此夜东林宿，听得荷池几番声。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["雨","夜"],"cats":{"山水":["庐山"],"天气":["写雨"]},"theme_conf":0.95},{"uid":"19340af6-e25d-41c8-90fc-b465d9be1134","title":"登楼","author":"朱斌","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["白日依山尽，黄河入海流。","欲穷千里目，更上一层楼。"],"theme":"山水田园","theme2":["哲理悟道","咏史怀古"],"style":"冲淡","style2":[],"mood":"慷慨","mood2":[],"scene":["楼"],"cats":{"抒情":["怀古"],"山水":["黄河"]},"theme_conf":0.375},{"uid":"6533dc36-cc73-4798-b24a-fbff04fc2a85","title":"渡中江望石城泣下","author":"后主煜","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["江南江北旧家乡，三十年来梦一场。","吴苑宫闱今冷落，广陵台殿已荒凉。","云笼远岫愁千片，雨打归舟泪万行。","兄弟四人三百口，不堪闲坐细思量。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["婉约","幽峭"],"mood":"愁怨","mood2":["悲怆"],"scene":["江","江南"],"cats":{"抒情":["思乡","伤感"],"山水":["江河"]},"theme_conf":0.532},{"uid":"4f866479-db88-497f-b2b6-29dcb0ec2a63","title":"杂曲歌辞 远别离","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["莲叶团团杏花拆，长江鲤鱼鳍鬣赤。","念君少年弃亲戚，千里万里独为客。","谁言远别心不易，天星坠地能为石。","几时断得城南陌，勿使居人有行役。"],"theme":"送别","theme2":[],"style":"豪放","style2":["冲淡"],"mood":"孤寂","mood2":[],"scene":["江"],"cats":{"抒情":["离别","孤独"],"山水":["长江"]},"theme_conf":0.826},{"uid":"02880a43-5d89-4b2b-b2a9-f99228969262","title":"西陵口观海","author":"薛据","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["长江漫汤汤，近海势弥广。","在昔胚浑凝，融为百川泱。","地形失端倪，天色𪷽滉漾。","东南际万里，极目远无象。","山影乍浮沈，潮波忽来往。","孤帆或不见，櫂歌犹想像。","日暮长风起，客心空振荡。","浦口霞未收，潭心月初上。","林屿几邅回，亭臯时偃仰。","岁晏访蓬瀛，真游非外奖。"],"theme":"咏史怀古","theme2":["送别","羁旅思乡"],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["江"],"cats":{"抒情":["思乡","孤独","怀古"],"山水":["长江"]},"theme_conf":0.357},{"uid":"cpdb72a46d948baf","title":"天门谣","author":"贺铸","dynasty":"宋","section":"宋词","form":"词","paragraphs":["牛渚天门险。","限南北、七雄豪占。","清雾敛。","与闲人登览。","待月上潮平波滟滟。","塞管轻吹新《阿滥》。","风满槛。","历历数、西州更点。"],"theme":"边塞征战","theme2":["闲适隐逸"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["江","塞外","月"],"cats":{"山水":["泰山"],"生活":["边塞"]},"theme_conf":0.565},{"uid":"9e10394a-b2cf-4f84-a07c-2b1103966824","title":"秋野五首 五","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["身许麒膦画，年衰鸳鹭群。","大江秋易盛，空峡夜多闻。","径隐千重石，帆留一片云。","儿童解蛮语，不必作参军。"],"theme":"咏怀抒感","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"山水":["长江"],"人物":["儿童"]},"theme_conf":0.72},{"uid":"5ceea715-909e-454c-ad89-5cda63cc119d","title":"送汤中丞和蕃","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["继好中司出，天心外国知。","已传尧雨露，更说汉威仪。","陇上应回首，河源复载驰。","孤峰问徒御，空碛见旌麾。","春草乡愁起，边城旅梦移。","莫嗟行远地，此去荅恩私。"],"theme":"送别","theme2":["羁旅思乡"],"style":"沉郁","style2":["冲淡"],"mood":"孤寂","mood2":["愁怨"],"scene":["春","雨","山"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["春天"],"山水":["黄河"]},"theme_conf":0.448},{"uid":"dfb61907-f39f-4797-8ee8-4086c79317a9","title":"伤进士谢庭皓","author":"徐夤","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["献书犹未达明君，何事先游岱岳云。","惟有春风护冤魄，与生青草盖孤坟。"],"theme":"悼亡挽歌","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["园林","春"],"cats":{"抒情":["伤感","孤独","悼亡","感恩"],"四季":["春天"],"山水":["泰山"]},"theme_conf":0.98},{"uid":"8c6eb64a-78b1-4b36-93a8-5d96cd7651d9","title":"詶裴补阙吴寺见寻","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["东林初结构，已有晚钟声。","窻户背流水，房廊半架城。","远山重叠见，芳草浅深生。","每与君携手，多烦长老迎。"],"theme":"哲理悟道","theme2":["送别"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["江南"],"cats":{"山水":["庐山"]},"theme_conf":0.644},{"uid":"5d8ad939-d581-4971-83b3-160b1486a2b5","title":"寄题余杭郡楼兼呈裴使君","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["官历二十政，宦游三十秋。","江山与风月，最忆是杭州。","北郭沙堤尾，西湖石岸头。","绿觞春送客，红烛夜回舟。","不敢言遗爱，空知念旧游。","凭君吟此句，题向望涛楼。"],"theme":"寄赠酬答","theme2":[],"style":"雄浑","style2":[],"mood":"相思","mood2":[],"scene":["楼","江"],"cats":{"抒情":["思念"],"山水":["西湖"]},"theme_conf":0.9},{"uid":"2ec75ddb-6cce-4775-b934-7a7995bc9a04","title":"送柳八员外赴江西","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["岐路穷无极，长江九派分。","行人随旅雁，楚树入湘云。","久在征南役，何殊蓟北勋。","离心不可问，岁暮雪纷纷。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["江"],"cats":{"山水":["江河","长江"],"植物":["柳树"]},"theme_conf":0.622},{"uid":"d30b4748-72eb-4f1d-b8de-99126216c38c","title":"梅雨","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["南京西浦道，四月熟黄梅。","湛湛长江去，冥冥细雨来。","茅茨疎易湿，云雾密难开。","竟日蛟龙喜，盘涡与岸回。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["雨","江"],"cats":{"山水":["长江"],"天气":["写雨"],"植物":["梅花"]},"theme_conf":1.0},{"uid":"e6bf25ce-19e9-4316-bd35-cdc6bb050c61","title":"奉酬卢给事云夫四兄曲江荷花行见寄幷呈上钱七兄阁老张十八助教","author":"韩愈","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["曲江千顷秋波净，平铺红云盖明镜。","大明宫中给事归，走马来看立不正。","遗我明珠九十六，寒光映骨睡骊目。","我今官闲得婆娑，问言何处芙蓉多。","撑舟昆明度云锦，脚敲两舷呌吴歌。","太白山高三百里，负雪崔嵬插花里。","玉山前却不复来，曲江汀滢水平杯。","我时相思不觉一回首，天门九扇相当开。","上界真人足官府，岂如散仙鞭笞鸾凤终日相追陪。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["江","花","山"],"cats":{"抒情":["思念"],"山水":["江河"],"天气":["写云"],"植物":["荷花"]},"theme_conf":0.95},{"uid":"03b8aaf4-9827-470b-ab77-9666b6e11f4c","title":"送归中丞使新罗","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["诏使殊方远，朝仪旧典行。","浮天无尽处，望日计前程。","暂喜孤山出，长愁积水平。","野风飘叠鼓，海雨湿危旌。","异俗知文教，通儒有令名。","还将大戴礼，方外授诸生。"],"theme":"送别","theme2":["应制干谒"],"style":"沉郁","style2":["绮丽","豪放"],"mood":"愁怨","mood2":["欢愉","孤寂"],"scene":["雨","山"],"cats":{"抒情":["伤感","孤独"],"山水":["西湖"]},"theme_conf":0.579},{"uid":"8dfd661e-00e1-4cef-b3bc-923559cf6c66","title":"汴河览古","author":"徐凝","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["炀帝龙舟向此行，三千宫女采桡轻。","渡河不似如今唱，为是杨家怨思声。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["端午","舟"],"cats":{"抒情":["闺怨"],"山水":["江河"],"节日":["端午节"]},"theme_conf":1.0},{"uid":"bf5f4147-1e1c-4bb6-84ab-0e6a6a402325","title":"相和歌辞 公无渡河","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["黄河西来决崐崘，咆吼万里触龙门。","波滔天，尧咨嗟。","大禹理百川，儿啼不窥家。","杀湍湮洪水，九州始蚕麻。","其害乃去，茫然风沙。","被发之叟狂而痴，清晨径流欲奚为。","旁人不惜妻止之，公无渡河苦渡之。","虎可搏，河难凭。","公果溺死流海湄，有长鲸白齿若雪山。","公乎公乎，挂骨于其间，箜篌所悲竟不还。"],"theme":"民生疾苦","theme2":["题画咏艺","山水田园"],"style":"豪放","style2":[],"mood":"悲怆","mood2":[],"scene":["江","雪"],"cats":{"抒情":["伤感"],"山水":["江河","黄河"]},"theme_conf":0.37},{"uid":"cp64b47d95c7e13e","title":"青玉案","author":"苏轼","dynasty":"宋","section":"宋词","form":"词","paragraphs":["三年枕上吴中路。","遣黄耳、随君去。","若到松江呼小渡。","莫惊鸥鹭，四桥尽是，老子经行处。","辋川图上看春暮。","常记高人右丞句。","作个归期天已许。","春衫犹是，小蛮针线，曾湿西湖雨。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":["沉郁"],"mood":"恬淡","mood2":[],"scene":["江南","江","春"],"cats":{"四季":["春天"],"山水":["西湖"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"1dcde895-c371-410d-b870-0ee3f99b0c86","title":"江行无题一百首 六十九","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["咫尺愁风雨，匡庐不可登。","秖疑云雾窟，犹有六朝僧。"],"theme":"咏史怀古","theme2":["哲理悟道"],"style":"悲慨","style2":[],"mood":"愁怨","mood2":[],"scene":["雨","江","山"],"cats":{"抒情":["伤感","怀古"],"山水":["庐山"]},"theme_conf":0.56},{"uid":"da0befbd-3655-4d16-8413-0d699c88e75c","title":"雨二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["空山中宵阴，微冷先枕席。","回风起清曙，万象萋已碧。","落落出岫云，浑浑倚天石。","日假何道行，雨含长江白。","连樯荆州船，有士荷矛戟。","南防草镇惨，沾湿赴远役。","群盗下辟山，总戎备强敌。","水深云光廓，鸣橹各有适。","渔艇息悠悠，夷歌负樵客。","留滞一老翁，书时记朝夕。"],"theme":"山水田园","theme2":[],"style":"婉约","style2":["清新","幽峭"],"mood":"恬淡","mood2":[],"scene":["江","雨","山","舟"],"cats":{"山水":["长江"],"天气":["写雨"]},"theme_conf":0.675},{"uid":"ebb316eb-28f4-4a18-9eb2-07ccf943a7eb","title":"送少微上人东南游","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["石梁人不到，独往更迢迢。","乞食山家少，寻钟野寺遥。","松门风自扫，瀑布雪难消。","秋夜闻清梵，余音逐海潮。"],"theme":"送别","theme2":["哲理悟道"],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["夜","雪","秋","山","江"],"cats":{"抒情":["孤独"],"四季":["秋天"],"山水":["瀑布"]},"theme_conf":0.511},{"uid":"3b52ca46-63f4-441a-97cc-dd5d1b722a47","title":"琴曲歌辞  幽居弄","author":"顾况","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["苔衣生，花露滴，月入西林荡东壁。","扣商占角两三声，洞户谿窗一冥寂。","独去沧洲无四邻，身婴世网此何身？","关情命曲寄惆怅，久别江南山里人。"],"theme":"闲适隐逸","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["惆怅"],"scene":["江","江南","月"],"cats":{"抒情":["孤独"],"山水":["庐山"]},"theme_conf":0.62},{"uid":"dddc5861-5ad3-438a-999e-f068b10fc886","title":"夜别韦司士得城字","author":"高适","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["高馆张灯酒复清，夜钟残月雁归声。","只言啼鸟堪求侣，无那春风欲送行。","黄河曲里沙为岸，白马津边柳向城。","莫怨他乡暂离别，知君到处有逢迎。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["夜","酒"],"cats":{"抒情":["离别"],"山水":["黄河"]},"theme_conf":0.713},{"uid":"cp4a62a14d478e1a","title":"临江仙","author":"苏轼","dynasty":"宋","section":"宋词","form":"词","paragraphs":["夜饮东坡醒复醉，归来仿佛三更。","家童鼻息已雷鸣。","敲门都不应，倚杖听江声。","长恨此身非我有，何时忘却营营。","夜阑风静縠纹平。","小舟从此逝，江海寄馀生。"],"theme":"闲适隐逸","theme2":["哲理悟道","送别","悼亡挽歌"],"style":"婉约","style2":["豪放","沉郁"],"mood":"愁怨","mood2":["恬淡"],"scene":["夜","江"],"cats":{"抒情":["悼亡"],"山水":["江河"]},"theme_conf":0.85},{"uid":"18134617-3a61-4d5a-a0c2-3d80b54099f6","title":"步出武陵东亭临江寓望","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["鹰至感风候，霜余变林麓。","孤颿带日来，寒江转沙曲。","戍摇旗影动，津晚橹声促。","月上彩霞收，渔歌远相续。"],"theme":"山水田园","theme2":["咏史怀古","边塞征战"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["江"],"cats":{"抒情":["孤独","怀古"],"山水":["江河"],"植物":["桃花"]},"theme_conf":0.425},{"uid":"601d90fb-3589-44f1-9a25-9e16af2102c3","title":"陪李七司马皂江上观造竹桥即日成往来之人免冬寒入水聊题短作简李公二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["把烛成桥夜，回舟坐客时。","天高云去尽，江迥月来迟。","衰谢多扶病，招邀屡有期。","异方乘此兴，乐罢不无悲。"],"theme":"山水田园","theme2":[],"style":"悲慨","style2":["幽峭","沉郁"],"mood":"欢愉","mood2":["悲怆"],"scene":["江","冬"],"cats":{"抒情":["伤感"],"四季":["冬天"],"山水":["江河"],"生活":["写桥"],"动物":["写马"],"植物":["竹子"]},"theme_conf":1.0},{"uid":"bcf88d70-488c-40a7-b7bf-febc7ab7c797","title":"同王员外雨后登开元寺南楼因寄西岩警上人","author":"卢纶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["过雨开楼看晚虹，白云相逐水相通。","寒蝉噪暮野无日，古树伤秋天有风。","数穗远烟凝垅上，一枝繁果忆山中。","何言暂别东林友，惆怅人间事不同。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":["相思"],"scene":["雨","楼","山","秋"],"cats":{"抒情":["思念"],"四季":["秋天"],"山水":["庐山"],"天气":["写雨"]},"theme_conf":0.87},{"uid":"f0d11fd0-26d2-4608-aeb0-dc841b80470b","title":"瀑布","author":"章孝标","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["秋河溢长空，天洒万丈布。","深雷隐云壑，孤电挂岩树。","沧溟晓喷寒，碧落晴荡素。","非趋下流急，势使不得住。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":["清新"],"mood":"孤寂","mood2":[],"scene":["山","秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"山水":["瀑布"]},"theme_conf":1.0},{"uid":"b14af996-a066-4cff-8903-35e2d658155a","title":"送许八拾遗归江宁觐省甫昔时尝客游此县于许生处乞瓦棺寺维摩图样志诸篇末","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["诏许辞中禁，慈颜赴北堂。","圣朝新孝理，祖席倍辉光。","内帛擎偏重，宫衣著更香。","淮阴清夜驿，京口渡江航。","春隔鸡人昼，秋期燕子凉。","赐书夸父老，寿酒乐城隍。","看画曾饥渴，追踪恨淼茫。","虎头金粟影，神妙独难忘。"],"theme":"送别","theme2":["羁旅思乡","送别"],"style":"清新","style2":["沉郁"],"mood":"愁怨","mood2":["孤寂","欢愉"],"scene":["江","夜"],"cats":{"抒情":["思乡","孤独"],"山水":["江河"],"人生":["梦想"]},"theme_conf":0.94},{"uid":"8e18183e-5a58-4805-b672-1726969d6526","title":"早寒江上有怀","author":"孟浩然","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["木落雁南度，北风江上寒。","我家襄水上，遥隔楚云端。","乡泪客中尽，孤帆天际看。","迷津欲有问，平海夕漫漫。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["幽峭","婉约"],"mood":"孤寂","mood2":[],"scene":["江"],"cats":{"抒情":["思乡","孤独"],"山水":["江河"]},"theme_conf":0.677},{"uid":"a4d718ee-c020-42b4-97df-499cd0076f7b","title":"登高","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["风急天高猨啸哀，渚清沙白鸟飞回。","无边落木萧萧下，不尽长江衮衮来。","万里悲秋常作客，百年多病独登台。","艰难苦恨繁霜鬓，潦倒新停浊酒桮。"],"theme":"民生疾苦","theme2":["咏史怀古"],"style":"悲慨","style2":["沉郁"],"mood":"悲怆","mood2":["愁怨"],"scene":["江","秋","重阳"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"],"山水":["长江"],"节日":["重阳节"]},"theme_conf":0.52},{"uid":"6b4fc113-fbd5-44ef-9815-8a084b6f7a0b","title":"陈使君山庄","author":"牟融","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["新卜幽居地自偏，士林争羡使君贤。","数椽潇洒临溪屋，十亩膏腴附郭田。","流水断桥芳草路，淡烟疎雨落花天。","秋成准拟重来此，沈醉何妨一榻眠。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"清新","style2":["旷达"],"mood":"恬淡","mood2":[],"scene":["山","花","秋","雨"],"cats":{"四季":["秋天"],"山水":["西湖"],"生活":["写桥"]},"theme_conf":0.444},{"uid":"164c262f-0c01-4baa-b366-adeb077fa1ea","title":"水会渡","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["山行有常程，中夜尚未安。","微月没已久，崖倾路何难。","大江动我前，汹若溟渤宽。","篙师暗理楫，歌笑轻波澜。","霜浓木石滑，风急手足寒。","入舟已千忧，陟𪩘仍万盘。","迥眺积水外，始知众星干。","远游令人瘦，衰疾慙加餐。"],"theme":"山水田园","theme2":["亲情"],"style":"幽峭","style2":["婉约"],"mood":"欢愉","mood2":["愁怨"],"scene":["舟","夜","月"],"cats":{"山水":["长江"]},"theme_conf":0.551},{"uid":"683085c0-248c-4545-998b-a04be7b8fd48","title":"江边星月二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["骤雨清秋夜，金波耿玉绳。","天河元自白，江浦向来澄。","映物连珠断，缘空一镜升。","余光隐更漏，况乃露华凝。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":["清新"],"mood":"恬淡","mood2":[],"scene":["江","夜","月"],"cats":{"山水":["江河"],"天气":["写雨","月亮","星星"]},"theme_conf":0.65},{"uid":"b7004472-180b-418e-97e3-b8f7bbd9ccf3","title":"郊庙歌辞 封泰山乐章 凯安","author":"张说","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["烈祖顺三灵，文宗威四海。","黄钺诛群盗，朱旗扫多罪。","戢兵天下安，约法人心改。","大哉干羽意，长见风云在。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":[],"mood":"恬淡","mood2":["欢愉"],"scene":["山"],"cats":{"山水":["泰山"]},"theme_conf":1.0},{"uid":"8e1b1d18-0810-4f49-a7d3-8a6332a51183","title":"郊庙歌辞 封泰山乐章 豫和 五","author":"张说","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["天道无亲，至诚与邻。","山川遍礼，宫征维新。","玉帛非盛，聪明会真。","正斯一德，通乎百神。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"山水":["泰山"]},"theme_conf":1.0},{"uid":"1689d325-7e76-4865-862b-6fe65ca9432f","title":"晚次荆江","author":"戎昱","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["孤舟大江水，水涉无昏曙。","雨暗迷津时，云生望乡处。","渔翁闲自乐，樵客纷多虑。","秋色湖上山，归心日边树。","徒称竹箭美，未得枫林趣。","向夕垂钓还，吾从落潮去。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["恬淡","欢愉"],"scene":["江"],"cats":{"抒情":["思乡","孤独"],"山水":["江河","长江"]},"theme_conf":0.505},{"uid":"c611bf84-57f9-44ee-ac22-d7a270a21190","title":"送马将军奏事毕归滑州使幕","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["吴门别后蹈沧州，帝里相逢俱白头。","自叹马卿常带病，还嗟李广未封侯。","棠梨宫里瞻龙衮，细柳营前著豹裘。","想到滑台桑叶落，黄河东注荻花秋。"],"theme":"边塞征战","theme2":["送别"],"style":"沉郁","style2":[],"mood":"慷慨","mood2":[],"scene":["江","秋","江南"],"cats":{"四季":["秋天"],"山水":["黄河"],"动物":["写马"]},"theme_conf":0.574},{"uid":"b9811b91-7522-46d2-ae55-63d63968adca","title":"自淇涉黄河途中作十三首 十二","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["朝景入平川，川长复垂柳。","遥看魏公墓，突兀前山后。","忆昔大业时，群雄角奔走。","伊人何电迈，独立风尘首。","传檄举敖仓，拥兵屯洛口。","连营一百万，六合如可有。","方项终比肩，乱隋将假手。","力争固难恃，骄战曷能久。","若使学萧曹，功名当不朽。"],"theme":"边塞征战","theme2":["悼亡挽歌"],"style":"豪放","style2":[],"mood":"孤寂","mood2":["慷慨"],"scene":["江"],"cats":{"抒情":["孤独","悼亡"],"山水":["黄河"],"人生":["战争"]},"theme_conf":0.552},{"uid":"cp60a401fbbbc431","title":"莺啼序","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["残寒正欺病酒，掩沈香绣户。","燕来晚、飞入西城，似说春事迟暮。","画船载、清明过却，晴烟冉冉吴宫树。","念羁情游荡，随风化为轻絮。","十载西湖，傍柳系马，趁娇尘软雾。","溯红渐、招入仙溪，锦儿偷寄幽素。","倚银屏、春宽梦窄，断红湿、歌纨金缕。","暝堤空，轻把斜阳，总还鸥鹭。","幽兰旋老，杜若还生，水乡尚寄旅。","别后访、六桥无信，事往花委，瘗玉埋香，几番风雨。","长波妒盼，遥山羞黛，渔灯分影春江宿，记当时、短楫桃根渡。","青楼彷佛，临分败壁题诗，泪墨惨澹尘土。","危亭望极，草色天涯，吹鬓侵半苎。","暗点检、离痕欢唾，尚染鲛绡，凤迷归，破鸾慵舞。","殷勤待写，书中长恨，蓝霞辽海沈过雁，漫相思、弹入哀筝柱。","伤心千里江南，怨曲重招，断魂在否。"],"theme":"悼亡挽歌","theme2":["送别"],"style":"沉郁","style2":["绮丽","婉约"],"mood":"相思","mood2":["愁怨"],"scene":["江南","鸟","春"],"cats":{"抒情":["离别","思念","伤感","悼亡"],"四季":["春天"],"山水":["西湖"],"生活":["写桥"],"节日":["清明节"],"动物":["写鸟"]},"theme_conf":0.93},{"uid":"53765d53-3bc1-4ed5-8fc4-452473913b3b","title":"寄朱锡珪","author":"贾岛","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["远泊与谁同，来从古木中。","长江人钓月，旷野火烧风。","梦泽吞楚大，闽山阨海丛。","此时樯底水，涛起屈原通。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["江"],"cats":{"山水":["长江"],"节日":["端午节"]},"theme_conf":0.82},{"uid":"17774136-42b0-4654-9f76-ba85f51636bd","title":"送僧往湖南","author":"刘商","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["闲出东林日影斜，稻苗深浅映袈裟。","船到南湖风浪静，可怜秋水照莲花。"],"theme":"送别","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["江"],"cats":{"山水":["庐山"]},"theme_conf":0.419},{"uid":"2d99b5dd-863a-4b50-ad3d-fe5c9ea8a8d9","title":"送元处士游天台","author":"朱庆余","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["青冥路口绝人行，独与僧期上赤城。","树列烟岚春更好，溪藏冰雪夜偏明。","空山雉雊禾苗短，野馆风来竹气清。","若过石桥看瀑布，不妨高处便题名。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["夜","冬","楼","雪","春","山"],"cats":{"抒情":["孤独"],"四季":["春天"],"山水":["瀑布"],"天气":["写雪"],"生活":["写桥"]},"theme_conf":0.458},{"uid":"260cc902-f037-49ce-8380-2d7ce420cdb2","title":"海阳十咏 棼丝瀑","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["飞流透嵌隙，喷洒如丝棼。","含晕迎初旭，翻光破夕曛。","余波遶石去，碎响隔溪闻。","却望琼沙际，逶迤见脉分。"],"theme":"咏物","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":[],"cats":{"山水":["瀑布"]},"theme_conf":0.738},{"uid":"8721c066-db42-44da-be87-a1a76680992b","title":"别尹炼师","author":"李群玉","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["吾家五千言，至道悬日月。","若非函谷令，谁注流沙说。","多君飞升志，机悟独超拔。","学道玉笥山，烧丹白云穴。","南穷衡疑秀，采药历幽绝。","夜卧瀑布风，朝行碧岩雪。","洞宫四百日，玉籍恣探阅。","徒以菌蟪姿，缅攀修真诀。","尘笼罩浮世，遐思空飞越。","一罢棋酒欢，离情满寥泬。","愿骑紫盖鹤，早向黄金阙。","城市不可留，尘埃秽仙骨。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["山","雪","酒"],"cats":{"抒情":["离别","孤独"],"山水":["瀑布"]},"theme_conf":0.576},{"uid":"0dc28dbc-d080-47fc-b44a-229e310c187a","title":"相和歌辞 襄阳乐","author":"张祜","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["大堤花月夜，长江春水流。","东风正上信，春夜特来游。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["江","春"],"cats":{"四季":["春天"],"山水":["长江"]},"theme_conf":0.8},{"uid":"14d67e42-0340-4c29-8fd4-0beddfe1dc2a","title":"湖上醉中代诸妓寄严郎中","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["笙歌杯酒正欢娱，忽忆仙郎望帝都。","借问连宵直南省，何如尽日醉西湖。","蛾眉别久心知否，鸡舌含多口厌无。","还有些些惆怅事，春来山路见蘼芜。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":[],"mood":"惆怅","mood2":["相思","欢愉"],"scene":["酒"],"cats":{"抒情":["思念"],"山水":["西湖"],"食物":["写酒"]},"theme_conf":0.88},{"uid":"5a5a657c-624e-44c1-8abd-4318953d1c56","title":"送臯法师","author":"司空曙","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["江草知寒柳半衰，行吟怨别独迟迟。","何人讲席投如意，唯有东林远法师。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":["愁怨"],"scene":["江"],"cats":{"抒情":["孤独"],"山水":["庐山"],"人物":["老师"]},"theme_conf":1.0},{"uid":"80beb8cc-8338-44d4-8b96-7f9d32133c97","title":"西塞山怀古","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["西晋楼船下益州，金陵王气黯然收。","千寻铁锁沈江底，一片降旛出石头。","人世几回伤往事，山形依旧枕江流。","今逢四海为家日，故垒萧萧芦荻秋。"],"theme":"咏史怀古","theme2":[],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":["山","塞外"],"cats":{"抒情":["怀古"],"山水":["江河"],"生活":["边塞"]},"theme_conf":0.672},{"uid":"79b4be2b-65d5-412f-82ed-48d8b804fabc","title":"瀑布联句","author":"宣宗皇帝","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["千岩万壑不辞劳，远看方知出处高。","溪涧岂能留得住，终归大海作波涛。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"山水":["瀑布"]},"theme_conf":1.0},{"uid":"26a4d4f1-b9bb-42c4-8201-8b84b88c5531","title":"江梅","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["梅蘂腊前破，梅花年后多。","绝知春意好，最奈客愁何。","雪树元同色，江风亦自波。","故园不可见，巫岫郁嵯峨。"],"theme":"羁旅思乡","theme2":["咏物"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["江","冬"],"cats":{"抒情":["思乡","伤感"],"山水":["江河"],"植物":["梅花"]},"theme_conf":0.638},{"uid":"cea51298-9d8e-468f-a075-8e843c97e018","title":"自淇涉黄河途中作十三首 十","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["茫茫浊河注，怀古临河滨。","禹功本豁达，汉迹方因循。","坎德昔滂沱，冯夷胡不仁。","激潏陵堤防，东郡多悲辛。","天子忽惊悼，从官皆负薪。","畚筑岂无谋，祈祷如有神。","宣房今安在，高岸空嶙峋。"],"theme":"咏史怀古","theme2":["悼亡挽歌"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["江"],"cats":{"抒情":["伤感","悼亡","怀古"],"山水":["江河","黄河"]},"theme_conf":0.46},{"uid":"3701a25a-98c8-4ff3-bfa5-1118d77f8800","title":"答窦援遗卧病见寄","author":"包佶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["今春扶病移沧海，几度承恩对白花。","送客屡闻帘外鹊，销愁已辨酒中虵。","瓶开枸杞悬泉水，鼎炼芙蓉伏火砂。","误入尘埃牵吏役，羞将簿领到君家。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["春","酒","江"],"cats":{"抒情":["伤感"],"四季":["春天"],"山水":["瀑布"]},"theme_conf":0.95},{"uid":"4bea25d5-1cef-483d-923d-bc9c50c7bbe5","title":"题孤山寺山石榴花示诸僧众","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["山榴花似结红巾，容艳新妍占断春。","色相故关行道地，香尘拟触坐禅人。","瞿昙弟子君知否，恐是天魔女化身。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"孤寂","mood2":[],"scene":["花","山"],"cats":{"抒情":["孤独"],"山水":["西湖"]},"theme_conf":0.76},{"uid":"b5afe65e-41f6-4c7a-8bc7-ff3f024937cb","title":"九日曲江","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["缀席茱萸好，浮舟菡萏衰。","季秋时欲半，九日意兼悲。","江水清源曲，荆门此路疑。","晚来高兴尽，摇荡菊花期。"],"theme":"节令风俗","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["重阳"],"cats":{"抒情":["伤感"],"山水":["江河"],"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.88},{"uid":"0db42110-bda6-490a-b3e0-61a5dfffad79","title":"江陵节度阳城郡王新楼成王请严侍御判官赋七字句同作","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["楼上炎天冰雪生，高飞燕雀贺新成。","碧窗宿雾蒙蒙湿，朱栱浮云细细轻。","杖钺褰帷瞻具美，投壶散帙有余清。","自公多暇延参佐，江汉风流万古情。"],"theme":"咏史怀古","theme2":[],"style":"清新","style2":["婉约"],"mood":"惆怅","mood2":[],"scene":["楼","江"],"cats":{"抒情":["怀古"],"山水":["江河"],"天气":["写雪"]},"theme_conf":1.0},{"uid":"eb8ca915-d8a4-4468-bfb3-2a657e5551d4","title":"闻瀑布冰折","author":"马戴","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["万仞冰峭折，寒声投白云。","光摇山月堕，我向石床闻。"],"theme":"山水田园","theme2":[],"style":"幽峭","style2":[],"mood":"惆怅","mood2":[],"scene":["冬"],"cats":{"山水":["瀑布"]},"theme_conf":0.84},{"uid":"9fcb6791-4b0f-4a32-84f9-fbebc30dd9c5","title":"问正上人疾","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["医王犹有疾，妙理竞难穷。","饵药应随病，观身转悟空。","地闲花欲雨，窗冷竹生风。","几日东林去，门人待远公。"],"theme":"哲理悟道","theme2":["山水田园","闲适隐逸"],"style":"冲淡","style2":["沉郁"],"mood":"恬淡","mood2":[],"scene":["雨"],"cats":{"山水":["庐山"],"人生":["哲理"]},"theme_conf":0.377},{"uid":"d7890db1-28cc-4cc4-b81a-90b6f9d68568","title":"酬乐天早春闲游西湖颇多野趣恨不得与微之同赏因思在越官重事殷镜湖之游或恐未暇因成十八韵见寄乐天前篇到时适会予亦宴镜湖南亭因述目前所睹以成酬荅末章亦示暇诚则势使之然亦欲粗为恬养之赠耳","author":"元稹","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["雁思欲回宾，风声乍变新。","各携红粉伎，俱伴紫垣人。","水面波疑縠，山腰虹似巾。","柳条黄大带，茭葑绿文茵。","雪尽才通屐，汀寒未有苹。","向阳偏晒羽，依岸小游鳞。","浦屿崎岖到，林园次第巡。","墨池怜嗜学，丹井羡登真。","雅叹游方盛，聊非意所亲。","白头辞北阙，沧海是东邻。","问俗烦江界，搜畋想渭津。","故交音讯少，归梦往来频。","独喜同门旧，皆为列郡臣。","三刀连地轴，一苇碍车轮。","尚阻青天雾，空瞻白玉尘。","龙因雕字识，犬为送书驯。","胜事无穷境，流年有限身。","嬾将闲气力，争鬬野塘春。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":["绮丽","豪放"],"mood":"欢愉","mood2":["恬淡"],"scene":["江","江南","春"],"cats":{"四季":["春天"],"山水":["西湖"],"人生":["时光"]},"theme_conf":0.9},{"uid":"cp0c23cd9569bd5c","title":"渡江云","author":"张炎","dynasty":"宋","section":"宋词","form":"词","paragraphs":["山空天入海，倚楼望极，风急暮潮初。","一帘鸠外雨，几处闲田，隔水动春锄。","新烟禁柳，想如今、绿到西湖。","犹记得、当年深隐，门掩两三株。","愁余。","荒洲古溆，断梗疏萍，更漂流何处。","空自觉、围羞带减，影怯灯孤。","常疑即见桃花面，甚近来、翻笑无书。","书纵远，如何也都无。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["冲淡","清新"],"mood":"孤寂","mood2":["愁怨"],"scene":["江"],"cats":{"抒情":["思乡","伤感","孤独"],"山水":["西湖"]},"theme_conf":0.95},{"uid":"a64899a4-3471-40d4-a63a-336d1b9145c0","title":"自蜀奉册命往朔方途中呈韦左相文部房尚书门下崔侍郎","author":"贾至","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["胡羯乱中夏，銮舆忽南巡。","衣冠陷戎寇，狼狈随风尘。","豳公秉大节，临难不顾身。","激昂白刃前，溅血下沾巾。","尚书抱忠义，历险披荆榛。","扈从出剑门，登翼岷江滨。","时望挹侍郎，公才标缙绅。","亭亭昆山玉，皎皎无缁磷。","顾惟乏经济，扞牧陪从臣。","永愿雪会稽，仗剑清咸秦。","太皇时内禅，神器付嗣君。","新命集旧邦，至德被远人。","捧册自南服，奉诏趋北军。","觐谒心载驰，违离难重陈。","策马出蜀山，畏途上缘云。","饮啄丛箐间，栖息虎豹群。","崎岖凌危栈，惴栗惊心神。","峭壁上嵚岑，大江下沄沄。","皇风扇八极，异类怀深仁。","元凶诱黠虏，肘腋生妖氛。","明主信英武，威声赫四邻。","誓师自朔方，旗帜何缤纷。","铁骑照白日，旄头拂秋旻。","将来荡沧溟，宁止蹴昆仑。","古来有屯难，否泰长相因。","夏康缵禹绩，代祖复汉勋。","于役各勤王，驱驰拱紫宸。","岂惟太公望，往昔逢周文。","谁谓三杰才，功业独殊伦。","感此慰行迈，无为歌苦辛。"],"theme":"应制干谒","theme2":["边塞征战"],"style":"幽峭","style2":["豪放"],"mood":"慷慨","mood2":[],"scene":["夏","雪"],"cats":{"四季":["夏天"],"山水":["长江"]},"theme_conf":0.76},{"uid":"46bf764a-2ccb-479c-991b-e83fc8966b16","title":"题汉州西湖","author":"严公弼","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["西湖创置自房公，心匠纵横造化同。","见说凤池推独步，高名何事滞川中。"],"theme":"咏物","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["江南","江"],"cats":{"抒情":["孤独"],"山水":["西湖"]},"theme_conf":1.0},{"uid":"08d0e076-ff46-4c75-b7d2-60a94290dfb6","title":"千叶桃花","author":"杨凭","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["千叶桃花胜百花，孤荣春晚驻年华。","若教避俗秦人见，知向河源旧侣夸。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["花"],"cats":{"抒情":["孤独"],"山水":["黄河"],"植物":["桃花","叶子"]},"theme_conf":1.0},{"uid":"b08883e7-d43b-45fd-9c1d-b770b8e8bbdf","title":"奉使过石门观瀑","author":"丘丹","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["溪上望悬泉，耿耿云中见。","披榛上岩岫，峭壁正东面。","千仞泻联珠，一潭喷飞霰。","嵯𤄓满山响，坐觉炎氛变。","照日类虹霓，从风似绡练。","灵奇既天造，惜处穷海甸。","吾祖昔登临，谢公亦游衍。","王程惧淹泊，下磴空延眷。","千里雷尚闻，峦回树葱蒨。","此来共贱役，探讨愧前彦。","永欲洗尘缨，终当惬此愿。"],"theme":"山水田园","theme2":["咏史怀古","民生疾苦"],"style":"幽峭","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"抒情":["怀古"],"山水":["瀑布"],"天气":["彩虹"]},"theme_conf":0.44},{"uid":"b2c3957f-77eb-42bc-a2ae-0337b317a053","title":"题慈仁寺竹院","author":"韩翃","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["千峰对古寺，何异到西林。","幽罄蝉声下，闲窗竹翠阴。","诗人谢客兴，法侣远公心。","寂寂炉烟里，香花欲暮深。"],"theme":"佛道禅颂","theme2":["山水田园","闲适隐逸"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["园林","花"],"cats":{"山水":["庐山"],"植物":["竹子"]},"theme_conf":0.8},{"uid":"d2dac645-ea92-432b-bc76-6656f5515a94","title":"送秘书谢监赴江西使幕","author":"韩翃","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["谢监忆山程，辞家万里行。","寒衣傍楚色，孤枕宿潮声。","小寇不足问，新诗应渐清。","府公相待日，引斾出江城。"],"theme":"送别","theme2":[],"style":"清新","style2":["豪放"],"mood":"孤寂","mood2":["相思"],"scene":["江"],"cats":{"抒情":["思念","孤独","感恩"],"山水":["江河"]},"theme_conf":1.0},{"uid":"160c5168-d55c-4a4c-ba73-ae1596f4b900","title":"杂曲歌辞 行路难三首 三","author":"顾况","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见少年头上如云发，少壮如云老如雪。","岂知灌顶有醍醐，能使清凉头不热。","吕梁之水挂飞流，鼋鼍蛟蜃不敢游。","少年恃险若平地，独倚长劒凌清秋。","行路难，行路难，昔少年，今已老。","前朝竹帛事皆空，日暮牛羊古城草。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["慷慨"],"scene":["雪","秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"山水":["瀑布"],"人生":["青春"]},"theme_conf":0.65},{"uid":"cp3bf43d6100f34f","title":"满江红","author":"岳飞","dynasty":"宋","section":"宋词","form":"词","paragraphs":["怒发冲冠，凭阑处、潇潇雨歇。","抬望眼、仰天长啸，壮怀激烈。","三十功名尘与土，八千里路云和月。","莫等闲、白了少年头，空悲切。","靖康耻，犹未雪。","臣子恨，何时灭。","驾长车踏破，贺兰山缺。","壮志饥餐胡虏肉，笑谈渴饮匈奴血。","待从头、收拾旧山河，朝天阙。"],"theme":"民生疾苦","theme2":["边塞征战"],"style":"豪放","style2":["沉郁","悲慨"],"mood":"慷慨","mood2":[],"scene":["雨","江","雪"],"cats":{"抒情":["爱国"],"山水":["江河"],"人生":["励志","梦想"]},"theme_conf":0.542},{"uid":"ae5b1a15-0b5c-4578-8f31-1b60030633a4","title":"江南逢李龟年","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["歧王宅里寻常见，崔九堂前几度闻。","正是江南好风景，落花时节又逢君。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["江南","江"],"cats":{"山水":["江河"]},"theme_conf":1.0},{"uid":"402c5cc0-8255-4a01-8e5e-2641417bf8a2","title":"杂曲歌辞 白马篇","author":"李白","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["龙马花雪毛，金鞍五陵豪。","秋霜切玉劒，落日明珠袍。","鬬鸡事万乘，轩盖一何高。","弓摧宜山虎，手接泰山猱。","酒后竞风彩，三杯弄宝刀。","杀人如翦草，剧孟同游遨。","发愤去函谷，从军向临洮。","叱咤万战场，匈奴尽波涛。","归来使酒气，未肯拜萧曹。","羞入原宪室，荒径隐蓬蒿。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":["悲慨"],"mood":"慷慨","mood2":[],"scene":["山","酒","秋"],"cats":{"四季":["秋天"],"山水":["泰山"],"人生":["战争"],"动物":["写马"]},"theme_conf":0.79},{"uid":"a5546090-d778-47ce-abde-d3184e225f64","title":"江村","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["清江一曲抱村流，长夏江村事事幽。","自去自来堂上燕，相亲相近水中鸥。","老妻画纸为碁局，稚子敲针作钓钩。","多病所须唯药物，微躯此外更何求。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":["清新"],"mood":"恬淡","mood2":[],"scene":["夏","江"],"cats":{"四季":["夏天"],"山水":["江河"],"人物":["儿童"],"生活":["乡村"]},"theme_conf":0.832},{"uid":"92681379-cbf2-4c6a-bc7c-b7e807cdccac","title":"奉和展礼岱宗涂经濮济","author":"萧楚材","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["拂汉星旗转，分霄日羽明。","将追会阜迹，更勒岱宗铭。","林戈咽济岸，兽鼓震河庭。","叶箭凌寒矫，鸟弓望晓惊。","已降汾水作，仍深迎渭情。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["山","园林"],"cats":{"山水":["泰山"]},"theme_conf":0.95},{"uid":"d9a38c34-7eb7-46d6-af26-da6f6f68bdf2","title":"送刘四赴夏县","author":"李颀","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["九霄特立红鸾姿，万仞孤生玉树枝。","刘侯致身能若此，天骨自然多叹美。","声名播扬二十年，足下长途几千里。","举世皆亲丞相阁，我心独爱伊川水。","脱略势利犹埃尘，啸傲时人而已矣。","新诗数岁即文雄，上书昔召蓬莱宫。","明主拜官麒麟阁，光车骏马看玉童。","高人往来庐山远，隐士往来张长公。","扶南甘蔗甜如蜜，杂以荔枝龙州橘。","赤县繁词满剧曹，白云孤峰晖永日。","朝持手板望飞鸟，暮诵楞伽对空室。","一朝出宰汾河间，明府下车人吏闲。","端坐讼庭更无事，开门咫尺巫咸山。","男耕女织蒙惠化，麦熟雉鸣长秋稼。","明年九府议功时，五辟三征当在兹。","闻道桐乡有遗老，邑中还欲置生祠。"],"theme":"送别","theme2":["山水田园"],"style":"沉郁","style2":["冲淡","绮丽"],"mood":"孤寂","mood2":[],"scene":["山","夏"],"cats":{"抒情":["孤独"],"四季":["夏天"],"山水":["庐山"],"食物":["荔枝"]},"theme_conf":0.307},{"uid":"335314f2-aa38-4f25-a0c3-6d8e375daec6","title":"宿曾江口示姪孙湘二首 一","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["云昏水奔流，天水漭相围。","三江灭无口，其谁识涯圻。","暮宿投民村，高处水半扉。","犬鸡俱上屋，不复走与飞。","篙舟入其家，暝闻屋中唏。","问知岁常然，哀此为生微。","海风吹寒晴，波扬众星辉。","仰视北斗高，不知路所归。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"冲淡","style2":[],"mood":"悲怆","mood2":[],"scene":["江"],"cats":{"抒情":["思乡"],"山水":["江河"],"天气":["星星"]},"theme_conf":0.534},{"uid":"a3e4aa0f-aba7-4024-a349-3c9fb23be270","title":"汉州月夕游房太尉西湖","author":"李德裕","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["丞相鸣琴地，何年闭玉徽。","偶因明月夕，重敞故楼扉。","桃柳谿空在，芙蓉客暂依。","谁怜济川楫，长与夜舟归。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["中秋","月","江南"],"cats":{"抒情":["思乡"],"山水":["西湖"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":1.0},{"uid":"81b905b4-aac5-4509-ba20-0826d15e9272","title":"寄郑二侍御归新郑无碍寺所居","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["何事休官早，归来作郑人。","云山随伴侣，伏腊见乡亲。","南亩无三径，东林寄一身。","谁当便静者，莫使甑生尘。"],"theme":"寄赠酬答","theme2":["羁旅思乡"],"style":"旷达","style2":["清新"],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"抒情":["思乡"],"山水":["庐山"]},"theme_conf":0.9},{"uid":"cf75254e-a399-47c0-b188-79c3b0be396b","title":"小孤山","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["古庙枫林江水边，寒鸦接饭雁横天。","大孤山远小孤出，月照洞庭归客船。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["山","江","鸟"],"cats":{"抒情":["思乡","孤独"],"山水":["西湖"]},"theme_conf":0.514},{"uid":"3a4f111b-6ab4-4457-9021-8c216f44ddf7","title":"寄终南真空禅师","author":"马戴","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["闲想白云外，了然清净僧。","松门山半寺，夜雨佛前灯。","此境可长住，浮生自不能。","一从林下别，瀑布几成冰。"],"theme":"寄赠酬答","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["夜","雨"],"cats":{"山水":["瀑布"],"人生":["哲理"]},"theme_conf":0.85},{"uid":"ee741325-dc51-4625-8bb5-20d477c3efaa","title":"寄天台秀师","author":"司空曙","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["天台瀑布寺，传有白头师。","幻迹示羸病，空门无住持。","雪晴看鹤去，海夜与龙期。","永愿亲瓶屦，呈功得问疑。"],"theme":"哲理悟道","theme2":["送别"],"style":"沉郁","style2":["豪放"],"mood":"恬淡","mood2":[],"scene":["楼","雪"],"cats":{"山水":["瀑布"]},"theme_conf":0.55},{"uid":"a2aed629-465d-412c-a68d-780068488725","title":"自河南经乱关内阻饥兄弟离散各在一处因望月有感聊书所怀寄上浮梁大兄於潜七兄乌江十五兄兼示符离及下邽弟妹","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["时难年饥世业空，弟兄羇旅各西东。","田园寥落干戈后，骨肉流离道路中。","吊影分为千里鴈，辞根散作九秋蓬。","共看明月应垂泪，一夜乡心五处同。"],"theme":"亲情","theme2":["民生疾苦","亲情","羁旅思乡"],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["月"],"cats":{"抒情":["离别","思乡","伤感"],"山水":["江河"],"天气":["月亮"],"生活":["田园"]},"theme_conf":0.87},{"uid":"ee8b870e-a2de-45e4-8fa6-a805e3ae1f7c","title":"相和歌辞 江南曲","author":"陆龟蒙","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["为爱江南雪，涉江聊采苹。","水深烟浩浩，空对双车轮。","车轮明月团，车盖浮云盘。","云月徒自好，水中行路难。","遥遥洛阳道，夹岸生春草。","寄语櫂船郎，莫夸风浪好。"],"theme":"山水田园","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["江南","江"],"cats":{"山水":["江河"],"天气":["月亮"]},"theme_conf":0.56},{"uid":"32021394-9342-4eb9-b5c0-f98c6e3beece","title":"钱唐湖春行","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["孤山寺北贾亭西，水面初平云脚低。","几处早莺争暖树，谁家新燕啄春泥。","乱花渐欲迷人眼，浅草才能没马蹄。","最爱湖东行不足，绿杨阴里白沙堤。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"山水":["西湖"]},"theme_conf":0.585},{"uid":"0d04cc1d-1ad6-472c-9de3-75695aae467c","title":"送唐中丞开淘西湖夏日游泛因书示郡人","author":"朱庆余","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["萍岸新淘见碧霄，中流相去忽成遥。","空余孤屿来诗景，无复横槎碍柳条。","红斾路幽山翠湿，锦帆风起浪花飘。","共知浸润同雷泽，何虑川源有旱苗。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":["惆怅"],"scene":["夏","江南","江"],"cats":{"抒情":["孤独"],"四季":["夏天"],"山水":["西湖"]},"theme_conf":0.67},{"uid":"26443368-af44-4a33-8f76-ec7f78d87448","title":"静夜酬通上人问疾","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["东林生早凉，高枕远公房。","大士看心后，中宵清漏长。","惊蝉出暗柳，微月隐回廊。","何事沈疴久，含毫问药王。"],"theme":"寄赠酬答","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["夜"],"cats":{"山水":["庐山"]},"theme_conf":0.91},{"uid":"72da81b5-8de5-4b5f-bc46-820925a90d64","title":"寄宋申锡评事时从李少师移军回归","author":"鲍溶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["君逐元侯静虏归，虎旗龙节驻春晖。","欲求岱岳燔柴礼，已锡鲁人缝掖衣。","长劒一时天外倚，五云多遶日边飞。","心期共贺太平世，去去故乡亲食薇。"],"theme":"寄赠酬答","theme2":["边塞征战","羁旅思乡"],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["春"],"cats":{"抒情":["思乡","感恩"],"四季":["春天"],"山水":["泰山"]},"theme_conf":0.9},{"uid":"b795db08-a132-4d2c-9925-654193077602","title":"喜弟淑再至为长歌","author":"李渤","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["前年别时秋九月，白露吹霜金吹烈。","离鸿一别影初分，泪袖双挥心哽咽。","别来几度得音书，南岳知□□□□。","庐山峨峨倚天碧，捧排空崖千万尺。","社牓长题高士名，食堂每记云山迹。","我本开云此山住，偶为名利相萦误。","自负心机四十年，羞闻社客山中篇。","忧时魂梦忆归路，觉来疑在林中眠。","昨日亭前乌鹊喜，果得今朝尔来此。","吾吟行路五十篇，尽说江南数千里。","自怜兄弟今五人，共萦儒素家尚贫。","虽然廪饩各不一，就中总免拘常伦。","长兄年少曾落托，拔劒沙场随卫霍。","口里虽谭周孔文，怀中不舍孙吴略。","次兄一生能苦节，夏聚流萤冬映雪。","非论疾恶志如霜，更觉临泉心似铁。","第三之兄更奇异，昂昂独负青云志。","下看金玉不如泥，肯道王侯身可贵。","却愁清逸不干时，高踪大器无人知。","倘逢感激许然诺，必能万古留清规。","念尔年来方二十，夙夜孜孜能独立。","卷中笔落星汉摇，洞里丹灵鬼神泣。","嗟余流浪心最狂，十年学劒逢时康。","心中不解事拘束，世间谈笑多相妨。","广海青山殊未足，逢著高楼还醉宿。","朝走安公枥上驹，暮伦陶令篱边菊。","近来诗思殊无况，苦被时流不相放。","云腾浪走势未衰，鹤膝蜂腰岂能障。","送尔为文殊不识，贵从一一传胷臆。","若到湖南见紫霄，会须待我同攀陟。"],"theme":"亲情","theme2":["山水田园","边塞征战"],"style":"豪放","style2":["沉郁","幽峭"],"mood":"愁怨","mood2":["欢愉","孤寂"],"scene":["山","江南","秋","冬","雪","夜"],"cats":{"抒情":["离别","伤感","孤独"],"四季":["秋天","冬天"],"山水":["庐山"],"人生":["励志","梦想","战争"],"生活":["边塞"]},"theme_conf":0.95},{"uid":"8474f5c4-d18e-4b42-9702-19ad909b9ea2","title":"哀江头","author":"杜甫","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["少陵野老吞声哭，春日潜行曲江曲。","江头宫殿锁千门，细柳新蒲为谁绿。","忆昔霓旌下南苑，苑中万物生颜色。","昭阳殿里第一人，同辇随君侍君侧。","辇前才人带弓箭，白马嚼啮黄金勒。","翻身向天仰射云，一箭正坠双飞翼。","明眸皓齿今何在，血污游魂归不得。","清渭东流劒阁深，去住彼此无消息。","人生有情泪沾臆，江水江花岂终极。","黄昏胡骑尘满城，欲往城南忘南北。"],"theme":"咏史怀古","theme2":["边塞征战"],"style":"沉郁","style2":["悲慨"],"mood":"悲怆","mood2":["愁怨"],"scene":["江"],"cats":{"抒情":["伤感","闺怨","怀古"],"山水":["江河"]},"theme_conf":0.9},{"uid":"edf071ea-ed26-4840-8842-fab95743a231","title":"郊庙歌辞 封泰山乐章 舒和","author":"张说","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["六钟翕协六变成，八佾倘佯八风生。","乐九[韶]兮人神感，美七德兮天地清。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"山水":["泰山"]},"theme_conf":1.0},{"uid":"da9dca80-4137-4ef6-8851-2c0e23463a22","title":"无可奈何歌","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["无可奈何兮！白日走而朱颜颓，少日往而老日催。","生者不住兮死者不回，况乎宠辱丰顇之外物。","又何常不十去而一来，去不可挽兮来不可推。","无可奈何兮！已焉哉！惟天长而地久，前无始兮后无终。","嗟吾生之几何，寄瞬息乎其中。","又如太仓之稊米，委一粒于万锺。","何不与道逍遥？","委化从容。","纵心放志，泄泄融融。","胡为乎分爱恶于生死，系忧喜于穷通。","倔强其骨髓，龃龉其心胷。","合冰炭以交战，祗自苦兮厥躬。","彼造物者，云何不为。","此与化者，云何不随。","或喣或吹，或盛或衰。","虽千变与万化，委一顺以贯之。","为彼何非，为此何是。","谁冥此心，梦蝶之子。","何祸非福，何吉非凶。","谁达此观，丧马之翁。","俾吾为秋毫之杪，吾亦自足。","不见其小，俾吾为泰山之阿。","吾亦无余，不见其多。","是以达人静则脗然与阴合迹，动则浩然与阳同波。","委顺而已，孰知其他。","时邪命邪！吾其无奈彼何？委邪顺邪！彼亦无奈吾何？夫两无奈何，然后能冥至顺而合太和。","故吾所以饮太和，扣至顺，而为无可奈何之歌。"],"theme":"哲理悟道","theme2":["讽喻刺世","悼亡挽歌","民生疾苦"],"style":"悲慨","style2":["旷达"],"mood":"惆怅","mood2":["愁怨"],"scene":["山"],"cats":{"抒情":["伤感","悼亡"],"山水":["泰山"]},"theme_conf":0.95},{"uid":"90f7a912-549f-444d-9b12-99c89f224b94","title":"自常州还江阴途中作","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["处处空篱落，江村不忍看。","无人花色惨，多雨鸟声寒。","黄霸初临郡，陶潜未罢官。","乘春务征伐，谁肯问凋残。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["江"],"cats":{"抒情":["孤独"],"山水":["江河"],"生活":["乡村"]},"theme_conf":1.0},{"uid":"368cbc24-d33d-4ef5-9940-c16acc077d73","title":"相和歌辞 江南曲八首 八","author":"刘希夷","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["忆昔江南年盛时，平生怨在长洲曲。","冠盖星繁湘水上，冲风摽落洞庭渌。","落花舞袖红纷纷，朝霞高阁洗晴云。","谁言此处婵娟子，珠玉为心以奉君。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":["相思"],"scene":["江","江南"],"cats":{"抒情":["思念"],"山水":["江河"],"节日":["中秋节"]},"theme_conf":1.0},{"uid":"a9c84c93-6f83-4456-80d8-8b7fe5e427a2","title":"江上曲","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["江心澹澹芙蓉花，江口蛾眉独浣纱。","可怜应是阳台女，对坐鹭鸶娇不语。","掩面羞看北地人，回身忽作空山语。","苍梧秋色不堪论，千载依依帝子魂。","君看峰上斑斑竹，尽是湘妃泣泪痕。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":["婉约"],"mood":"孤寂","mood2":["恬淡","悲怆"],"scene":["江","山"],"cats":{"抒情":["伤感","孤独"],"山水":["江河"]},"theme_conf":1.0},{"uid":"c012d2aa-e678-491c-aa1d-d201ed7d6e2a","title":"寄李白","author":"任华","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["古来文章有能奔逸气，耸高格。","清人心神，惊人魂魄。","我闻当今有李白，大猎赋，鸿猷文，嗤长卿，笑子云。","班张所作琐细不入耳，未知卿云得在嗤笑限。","登庐山，观瀑布，海风吹不断，江月照还空。","余爱此两句：登天台，望渤海云垂大鹏飞，山压巨鳌背，斯言亦好在。","至于他作多不拘常律，振摆超腾，既俊且逸。","或醉中操纸，或兴来走笔。","手下忽然片云飞，眼前划见孤峰出。","而我有时白日忽欲睡，睡觉歘然起攘臂。","任生知有君，君也知有任生未。","中间闻道在长安，及余戾止。","君已江东访元丹，邂逅不得见君面。","每常把酒，向东望良久。","见说往年在翰林，胸中矛戟何森森。","新诗传在宫人口，佳句不离明主心。","身骑天马多意气，目送飞鸿对豪贵。","承恩召入凡几回，待诏归来仍半醉。","权臣妬盛名，群犬多吠声。","有勅放君却归隐沦处，高歌大笑出关去。","且向东山为外臣，诸侯交迓驰朱轮。","白璧一双买交者，黄金百镒相知人。","平生傲岸其志不可测，数十年为客，未尝一日低颜色。","八咏楼中坦腹眠，五侯门下无心忆。","繁花越台上，细柳吴宫侧。","绿水青山知有君，白云明月偏相识。","养高兼养闲，可望不可攀。","庄周万物外，范蠡五湖间。","人传访道沧海上，丁令王乔每往还。","蓬莱径是曾到来，方丈岂唯方一丈。","伊余每欲乘兴往相寻，江湖拥隔劳寸心。","今朝忽遇东飞翼，寄此一章表胸臆。","傥能报我一片言，但访任华有人识。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":["清新","旷达"],"mood":"恬淡","mood2":["欢愉","慷慨"],"scene":["山","江","月","酒"],"cats":{"山水":["庐山","瀑布"],"天气":["写云","月亮"],"人生":["哲理","梦想"]},"theme_conf":0.95},{"uid":"d3f24d39-65c7-4348-973b-f8b7db595abc","title":"江楼晚眺景物鲜奇吟玩成篇寄水部张员外","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["澹烟疎雨间斜阳，江色鲜明海气凉。","蜃散云收破楼阁，虹残水照断桥梁。","风翻白浪花千片，雁点青天字一行。","好著丹青图画取，题诗寄与水曹郎。"],"theme":"寄赠酬答","theme2":[],"style":"幽峭","style2":["冲淡"],"mood":"相思","mood2":["恬淡"],"scene":["楼","江"],"cats":{"山水":["江河","西湖"],"生活":["写桥"]},"theme_conf":0.86},{"uid":"a2880bfc-d719-4112-996d-1966277498af","title":"咏石","author":"苏味道","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["济北甄神贶，河西濯锦文。","声应天池雨，影触岱宗云。","燕归犹可候，羊起自成群。","何当握灵髓，高枕绝嚣氛。"],"theme":"咏物","theme2":[],"style":"幽峭","style2":["绮丽"],"mood":"孤寂","mood2":[],"scene":["山","雨"],"cats":{"山水":["泰山"]},"theme_conf":1.0},{"uid":"c4912092-34c2-42fe-a9ff-b924b0dddf7f","title":"相和歌辞 春江花月夜","author":"温庭筠","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["玉树歌阑海云黑，花庭忽作青芜国。","秦淮有水水无情，还向金陵漾春色。","杨家二世安九重，不御华芝嫌六龙。","百幅锦帆风力满，连天展尽金芙蓉。","珠翠丁星复明灭，龙头劈浪哀笳发。","千里涵空照水魂，万枝破鼻团香雪。","漏转霞高沧海西，颇黎枕上闻天鸡。","蛮弦代雁曲如语，一醉昏昏天下迷。","四方倾动烟尘起，犹在浓香梦魂里。","后主荒宫有晓莺，飞来只隔西江水。"],"theme":"咏史怀古","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":["悲怆"],"scene":["江","春"],"cats":{"抒情":["怀古"],"四季":["春天"],"山水":["江河"],"天气":["月亮"]},"theme_conf":1.0},{"uid":"64ce1225-6e8b-46b5-b1df-50a4cba1f0f3","title":"晚发江宁道中呈严维","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["惆怅遥江路，萧条落日过。","蝉鸣独树急，鸦向古城多。","转曲随青嶂，因高见白波。","潘生秋径草，严子意如何。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":["孤寂"],"scene":["江","秋"],"cats":{"抒情":["思乡","孤独"],"四季":["秋天"],"山水":["江河"]},"theme_conf":0.86},{"uid":"c501f17a-230a-49b5-833c-5889a4e9bc85","title":"自淇涉黄河途中作十三首 十一","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["我行倦风湍，辍棹将问津。","空传歌瓠子，感慨独愁人。","孟夏桑叶肥，秾阴夹长津。","蚕农有时节，田野无闲人。","临水狎渔樵，望山怀隐沦。","谁能去京洛，顦顇对风尘。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["愁怨","恬淡"],"scene":["江","夏","舟","山"],"cats":{"抒情":["伤感","孤独"],"四季":["夏天"],"山水":["黄河"]},"theme_conf":0.603},{"uid":"17cd4a8b-9987-47b8-9d44-034c98f8f939","title":"相和歌辞 江南曲","author":"李贺","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["汀洲白苹草，柳恽乘马归。","江头樝树香，岸上蝴蝶飞。","酒杯若叶露，玉轸蜀桐虚。","朱楼通水陌，沙暖一双鱼。"],"theme":"哲理悟道","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["江","江南"],"cats":{"山水":["江河"]},"theme_conf":1.0},{"uid":"973ff843-3249-4773-9dc6-5ea401a75d33","title":"窊尊诗","author":"元结","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["巉巉小山石，数峰对窊亭。","窊石堪为樽，状类不可名。","巡回数尺间，如见小蓬瀛。","尊中酒初涨，始有岛屿生。","岂无日观峰，直下临沧溟。","爱之不觉醉，醉卧还自醒。","醒醉在尊畔，始为吾性情。","若以形胜论，坐隅临郡城。","平湖近阶砌，近山复青青。","异木几十株，林条冒簷楹。","盘根满石上，皆作龙蛇形。","酒堂贮酿器，户牖皆罂缾。","此尊可常满，谁是陶渊明。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"幽峭","style2":["豪放"],"mood":"恬淡","mood2":[],"scene":["酒","山"],"cats":{"山水":["泰山"]},"theme_conf":0.569},{"uid":"7bd52da1-5075-49d7-bcde-6680d97e5441","title":"奉和周二十丈酬郴州侍郎衡江夜泊得韶州书幷附当州生黄茶一封率然成篇代意之作","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["丘山仰德耀，天路下征𬴂。","梦喜三刀近，书嫌五载违。","凝情江月落，属思岭云飞。","会入司徒府，还邀周掾归。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":["欢愉"],"scene":["江","夜","山"],"cats":{"山水":["江河"],"食物":["写茶"]},"theme_conf":0.88},{"uid":"b422712d-ef98-46d3-b967-0a2c5c000fc7","title":"杂曲歌辞 结韈子","author":"李白","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["燕南壮士吴门豪，筑中置铅鱼隐刀。","感君恩重许君命，泰山一掷轻鸿毛。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"慷慨","mood2":["欢愉"],"scene":["山"],"cats":{"抒情":["怀古","感恩"],"山水":["泰山"]},"theme_conf":1.0},{"uid":"8af2d4cd-7f0c-4fcf-8046-21b75d174476","title":"题云际寺故僧院","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["白发悤悤色，青山草草心。","远公仍下世，从此别东林。"],"theme":"哲理悟道","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["园林"],"cats":{"山水":["庐山"]},"theme_conf":0.644},{"uid":"9185b303-813a-493d-ae09-5d4979cd90ef","title":"杂曲歌辞 古离别","author":"僧贯休","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["离恨如旨酒，古今饮皆醉。","只恐长江水，尽是儿女泪。","伊余非此辈，送人空把臂。","他日再相逢，清风动天地。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["豪放"],"mood":"愁怨","mood2":["孤寂"],"scene":["江","酒"],"cats":{"抒情":["离别","伤感"],"山水":["长江"]},"theme_conf":0.691},{"uid":"54b45313-84ba-446a-9cbe-f58304b1c29b","title":"相和歌辞 江南弄","author":"王勃","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["江南弄，巫山连楚梦，行雨行云几相送。","瑶轩金谷上春时，玉童仙女无见期。","紫露香烟眇难托，清风明月遥相思。","遥相思，草徒绿，为听双飞凤凰曲。"],"theme":"山水田园","theme2":["爱情相思","送别"],"style":"清新","style2":["绮丽"],"mood":"相思","mood2":[],"scene":["江南","江"],"cats":{"抒情":["爱情","思念"],"山水":["江河"],"天气":["月亮"]},"theme_conf":0.357},{"uid":"a1255e7f-9db9-45a3-85cf-ad00559a3e58","title":"沣水送郑鄠县读书","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["麦秋中夏凉风起，送君西郊及沣水。","孤烟远树动离心，隔岸江流若千里。","早年江海谢浮名，此路云山惬尔情。","上古全经皆在口，秦人如见济南生。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["夏","秋","江","山"],"cats":{"抒情":["离别","孤独"],"四季":["夏天","秋天"],"山水":["江河"],"人生":["读书"]},"theme_conf":0.766},{"uid":"c3966527-45c8-469f-8d74-cc906151e51a","title":"相和歌辞 江南曲八首 三","author":"刘希夷","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["君为陇西客，妾遇江南春。","朝游含灵果，夕采弄风苹。","果气时不歇，苹花日自新。","以此江南物，持赠陇西人。","空盈万里怀，欲赠竟无因。"],"theme":"爱情相思","theme2":[],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":["江南","江"],"cats":{"山水":["江河"]},"theme_conf":0.96},{"uid":"da5adcc3-327e-4fc0-aa4c-5da11168391e","title":"游坊口悬泉偶题石上","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["济源山水好，老尹知之久。","常日听人言，今秋入吾手。","孔山刀劒立，沁水龙蛇走。","危磴上悬泉，澄湾转坊口。","虚明见深底，净绿无纤垢。","仙櫂浪悠扬，尘缨风斗薮。","岩寒松柏短，石古莓苔厚。","锦坐缨高低，翠屏张左右。","虽无安石妓，不乏文举酒。","谈笑逐身来，管弦随事有。","时逢杖锡客，或值垂纶叟。","相与澹忘归，自辰将及酉。","公门欲返驾，溪路犹回首。","早晚重来游，心期罢官后。"],"theme":"山水田园","theme2":[],"style":"幽峭","style2":["绮丽","清新"],"mood":"恬淡","mood2":[],"scene":["山","秋","酒"],"cats":{"四季":["秋天"],"山水":["瀑布"]},"theme_conf":0.845},{"uid":"e4b624d5-60a5-42e4-8417-298431fb7625","title":"成都府","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["翳翳桑榆日，照我征衣裳。","我行山川异，忽在天一方。","但逢新人民，未卜见故乡。","大江东流去，游子去日长。","曾城填华屋，季冬树木苍。","喧然名都会，吹箫间笙簧。","信美无与适，侧身望川梁。","鸟[雀]夜各归，中原杳茫茫。","初月出不高，众星尚争光。","自古有羁旅，我何苦哀伤。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["冬","夜","月"],"cats":{"抒情":["思乡","伤感"],"四季":["冬天"],"山水":["长江"]},"theme_conf":0.617},{"uid":"40c8fa66-2802-43df-ada6-1bd286cb49db","title":"八哀诗 赠司空王公思礼","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["司空出东夷，童稚刷劲翮。","追随燕蓟儿，颖锐物不隔。","服事哥舒翰，意无流沙碛。","未甚拔行间，犬戎大充斥。","短小精悍姿，屹然强寇敌。","贯穿百万众，出入由咫尺。","马鞍悬将首，甲外控鸣镝。","洗劒青海水，刻铭天山石。","九曲非外蕃，其王转深壁。","飞兔不近驾，鸷鸟资远击。","晓达兵家流，饱闻春秋癖。","胷襟日沈静，肃肃自有适。","潼关初溃散，万乘犹辟易。","偏裨无所施，元帅见手格。","太子入朔方，至尊狩梁益。","胡马缠伊洛，中原气甚逆。","肃宗登宝位，塞望势敦迫。","公时徒步至，请罪将厚责。","际会清河公，间道传玉册天王拜跪毕，谠议果冰释。","翠华卷飞雪，熊虎亘阡陌。","屯兵凤皇山，帐殿泾渭辟。","金成贼咽喉诏镇雄所搤。","禁暴清无双，爽气春淅沥。","巷有从公歌，野多青青麦。","及夫哭庙后，复领太原役恐惧禄位高，怅望王土窄。","不得见清时，呜呼就窀穸。","永系五湖舟，悲甚田横客。","千秋汾晋间，事与云水白。","昔观文苑传，岂述廉蔺绩。","嗟嗟邓大夫，士卒终倒戟。"],"theme":"悼亡挽歌","theme2":["悼亡挽歌","送别"],"style":"冲淡","style2":["悲慨","清新"],"mood":"悲怆","mood2":[],"scene":["雪","鸟","冬"],"cats":{"抒情":["伤感","悼亡"],"山水":["黄河"],"天气":["写雪"]},"theme_conf":0.95},{"uid":"26587ca4-6af1-4180-a430-b29652a14f1d","title":"送高司直寻封阆州","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["丹雀衔书来，暮栖何乡树。","骅骝事天子，辛苦在道路。","司直非冗官，荒山甚无趣。","借问泛舟人，胡为入云雾。","与子姻娅间，即亲亦有故。","万里长江边，邂逅一相遇。","长卿消渴再，公干沈緜屡。","清谈慰老夫，开卷得佳句。","时见文章士，欣然澹情素。","伏枕闻别离，畴能忍漂寓。","良会苦短促，溪行水奔注。","熊罴咆空林，游子慎驰骛。","西谒巴中侯，艰险如跬步。","主人不世才，先帝常特顾。","拔为天军佐，崇大王法度。","淮海生清风，南翁尚思慕。","公宫造广厦，木石乃无数。","初闻伐松柏，犹卧天一柱。","我瘦书不成，成字读亦误。","为我问故人，劳心练征戍。"],"theme":"送别","theme2":[],"style":"冲淡","style2":["幽峭","豪放"],"mood":"恬淡","mood2":["欢愉"],"scene":["江"],"cats":{"抒情":["友情","离别"],"山水":["长江"]},"theme_conf":0.486},{"uid":"e41de81a-1060-4cf1-aa51-071011f32c5e","title":"龙兴观金箓建醮","author":"王翰","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["泰山岩岩兮凌紫氛，中有群仙兮乘白云，陈金荐璧兮□□□。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"山水":["泰山"]},"theme_conf":0.65},{"uid":"edc474d8-bb0f-469e-9367-328d9aefb568","title":"相和歌辞 江南曲","author":"宋之问","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["妾住越城南，离居不自堪。","采花惊曙鸟，摘叶𫗪春蚕。","嬾结茱萸带，愁安玳瑁簪。","侍臣消瘦尽，日暮碧江潭。"],"theme":"闺情宫怨","theme2":["送别","民生疾苦"],"style":"沉郁","style2":["幽峭"],"mood":"愁怨","mood2":[],"scene":["江南","江"],"cats":{"抒情":["伤感","闺怨"],"山水":["江河"],"节日":["重阳节"]},"theme_conf":0.474},{"uid":"1f92134b-bca9-46eb-b2fe-87b30413041a","title":"江雪","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["千山鸟飞绝，万迳人踪灭。","孤舟蓑笠翁，独钓寒江雪。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["雪","冬"],"cats":{"抒情":["孤独"],"山水":["江河"],"天气":["写雪"]},"theme_conf":0.787},{"uid":"f00ecdd7-7a93-4152-9947-90e068c37196","title":"杭州回舫","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["自别钱塘山水后，不多饮酒嬾吟诗。","欲将此意凭回櫂，报与西湖风月知。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["江南"],"cats":{"山水":["西湖"]},"theme_conf":0.559},{"uid":"fb087f9d-b19c-4c65-a310-c605f73a1fde","title":"夏日叹","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["夏日出东北，陵天经中街。","朱光彻厚地，郁蒸何由开。","上苍久无雷，无乃号令乖。","雨降不濡物，良田起黄埃。","飞鸟苦热死，池鱼涸其泥。","万人尚流冗，举目唯蒿莱。","至今大河北，化作虎与豺。","浩荡想幽蓟，王师安在哉？","对食不能餐，我心殊未谐。","眇然贞观初，难与数子偕。"],"theme":"民生疾苦","theme2":[],"style":"冲淡","style2":[],"mood":"悲怆","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"],"山水":["江河"],"天气":["太阳"]},"theme_conf":0.86},{"uid":"4dbfdde1-a5ba-440f-8acc-3d0872c72351","title":"浔阳陶氏别业","author":"刘眘虚","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["陶家习先隐，种柳长江边。","朝夕浔阳郭，白衣来几年。","霁云明孤岭，秋水澄寒天。","物象自清旷，野情何绵联。","萧萧丘中赏，明宰非徒然。","愿守黍稷税，归耕东山田。"],"theme":"送别","theme2":["山水田园","民生疾苦"],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["江"],"cats":{"抒情":["离别","孤独"],"山水":["长江"]},"theme_conf":0.382},{"uid":"e56e4c5d-9552-4ec9-a4c5-a86e08e1ef6f","title":"相和歌辞 春江花月夜二首 一","author":"张子容","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["林花发岸口，气色动江新。","此夜江中月，流光花上春。","分明石潭里，宜照浣纱人。"],"theme":"山水田园","theme2":["山水田园"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春","夜","月","江","花"],"cats":{"四季":["春天"],"山水":["江河"],"天气":["月亮"]},"theme_conf":0.91},{"uid":"98fc0ac5-1c75-4c64-8e09-6813c8d1b9fc","title":"峡口二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["峡口大江间，西南控百蛮。","城欹连粉堞，岸断更青山。","开辟多天险，防隅一水关。","乱离闻鼓角，秋气动衰颜。"],"theme":"边塞征战","theme2":["送别"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["秋","江","山"],"cats":{"四季":["秋天"],"山水":["长江"]},"theme_conf":0.6},{"uid":"bdb32446-6efc-402e-93f0-901b8eefe57e","title":"杂曲歌辞 生别离","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["食蘗不易食梅难，蘗能苦兮梅能酸。","未如生别之为难，苦在心兮酸在肝。","晨鸡载鸣残月没，征马重嘶行人出。","回看骨肉哭一声，梅酸蘗苦甘如蜜。","黄河水白黄云秋，行人河边相对愁。","天寒野旷何处宿？棠梨叶战风飕飕。","生离别，生离别，忧从中来无断绝。","忧积心劳血气衰，未年三十生白发。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["江","秋","月"],"cats":{"抒情":["离别","伤感"],"四季":["秋天"],"山水":["黄河"],"人生":["战争"]},"theme_conf":0.762},{"uid":"762e0a43-b8ed-4a11-bb82-28958998d354","title":"横吹曲辞 出塞 二","author":"王昌龄","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["白花垣上望京师，黄河水流无尽时。","穷秋旷野行人绝，马首东来知是谁。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["塞外","江"],"cats":{"山水":["黄河"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"36128fe1-a9f6-4841-99a6-9b7995ac94d3","title":"游徐城河忽见清淮因寄赵八","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["自缘迟暮忆沧洲，翻爱南河浊水流。","初过重阳惜残菊，行看旧浦识群鸥。","朝霞映日同归处，暝柳摇风欲别秋。","长恨相逢即分首，含情掩泪独回头。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["重阳"],"cats":{"抒情":["伤感"],"山水":["江河"],"节日":["重阳节"]},"theme_conf":0.88},{"uid":"ae472a2c-7977-4ed6-a893-7ef7c3136666","title":"柴门","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["孤舟登瀼西，回首望两崖。","东城干旱天，其气如焚柴。","长影没窈窕，余光散唅呀。","大江蟠嵌根，归海成一家。","下冲割坤轴，竦壁攒镆铘。","萧飒洒秋色，氛昏霾日车。","峡门自此始，最窄容浮查。","禹功翊造化，疎凿就攲斜。","巨渠决太古，众水为长蛇。","风烟渺吴蜀，舟楫通盐麻。","我今远游子，飘转混泥沙。","万物附本性，约身不愿奢。","茅栋盖一床，清池有余花。","浊醪与脱粟，在眼无咨嗟。","山荒人民少，地僻日夕佳。","贫病固其常，富贵任生涯。","老于干戈际，宅幸蓬荜遮。","石乱上云气，杉清延月华。","赏妍又分外，理惬夫何夸。","足了垂白年，敢居高士差。","书此豁平昔，回首犹暮霞。"],"theme":"山水田园","theme2":["羁旅思乡","闲适隐逸"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["舟","秋","酒"],"cats":{"抒情":["思乡","孤独"],"四季":["秋天"],"山水":["长江"],"天气":["月亮"],"生活":["乡村"]},"theme_conf":0.35},{"uid":"22abc39e-e43e-4644-97f0-08053b5fa3ee","title":"相和歌辞 上云乐","author":"李贺","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["飞香走红满天春，花龙盘盘上紫云。","三千宫女列金屋，五十弦瑟海上闻。","大江碎碎银沙路，嬴女机中断烟素。","断烟素，缝舞衣，八月一日君前舞。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["豪放"],"mood":"欢愉","mood2":[],"scene":["花","春","月"],"cats":{"抒情":["闺怨"],"四季":["春天"],"山水":["长江"],"天气":["写云"]},"theme_conf":1.0},{"uid":"1422a3b8-f6db-44e5-a842-3a1c44359b59","title":"过天门山怀友","author":"吴筠","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["举帆遇风劲，逸势如飞奔。","缥缈凌烟波，崩腾走川原。","两山夹沧江，豁尔开天门。","须臾轻舟远，想象孤屿存。","归路日已近，怡然慰心魂。","所经多奇趣，待与吾友论。","一日如三秋，相思意弥敦。"],"theme":"咏史怀古","theme2":["爱情相思","山水田园"],"style":"悲慨","style2":[],"mood":"相思","mood2":[],"scene":["山","舟","江"],"cats":{"抒情":["爱情","友情","思念","怀古"],"山水":["泰山"]},"theme_conf":0.371},{"uid":"ba35e964-379b-456f-b60b-6813f5783fb7","title":"天门街西观荣王聘妃","author":"梁铉","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["帝子乘龙夜，三星照户前。","两行宫火出，十里道铺筵。","罗绮明中识，箫韶暗里传。","灯攒九华扇，帐撒五铢钱。","交颈文鸳合，和鸣彩凤连。","欲知来日美，双拜紫微天。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["夜"],"cats":{"山水":["泰山"]},"theme_conf":0.7},{"uid":"22df0b35-cf47-4dd2-844b-1984891d5db0","title":"杂曲歌辞 春江曲","author":"王涯","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["摇漾越江春，相将看白苹。","归时不觉夜，出浦月随人。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["春","江"],"cats":{"四季":["春天"],"山水":["江河"]},"theme_conf":0.9},{"uid":"8c37cdbb-74bd-4eea-b15e-2237a6d7eaf1","title":"西湖晚归回望孤山寺赠诸客","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["柳湖松岛莲花寺，晚动归桡出道场。","卢橘子低山雨重，棕榈叶战水风凉。","烟波澹荡摇空碧，楼殿参差倚夕阳。","到岸请君回首望，蓬莱宫在海中央。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"冲淡","style2":["沉郁"],"mood":"孤寂","mood2":[],"scene":["江","山","江南"],"cats":{"抒情":["思乡","孤独"],"山水":["西湖"]},"theme_conf":0.86},{"uid":"3f44618a-ec8e-40e0-bbfd-7cefa27e61d2","title":"杂曲歌辞 凉州词","author":"薛逢","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["昨夜蕃兵报国讐，沙州都护破凉州。","黄河九曲今归汉，塞外纵横战血流。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":["豪放"],"mood":"慷慨","mood2":[],"scene":["江","塞外","夜"],"cats":{"抒情":["爱国"],"山水":["黄河"],"人生":["战争"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"dd0063b6-941f-409a-b14e-e149d44df3a3","title":"舍弟占归草堂检校聊示此诗","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["久客应吾道，相随独尔来。","孰知江路近，频为草堂回。","鹅鸭宜长数，柴荆莫浪开。","东林竹影薄，腊月更须栽。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"旷达","style2":[],"mood":"孤寂","mood2":[],"scene":["月","江"],"cats":{"抒情":["思乡","孤独"],"山水":["庐山"]},"theme_conf":0.624},{"uid":"03999410-ba31-4a8a-8718-340aa7d38735","title":"相和歌辞 江南曲八首 六","author":"刘希夷","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["暮春三月晴，维扬吴楚城。","城临大江汜，回映洞浦清。","晴云曲金阁，珠楼碧烟里。","月明芳树群鸟飞，风过长林杂花起。","可怜离别谁家子，于此一至情何已。"],"theme":"送别","theme2":["山水田园"],"style":"绮丽","style2":["清新"],"mood":"惆怅","mood2":[],"scene":["江南","江"],"cats":{"抒情":["离别"],"山水":["江河","长江"]},"theme_conf":0.58},{"uid":"4e167af1-7d67-4417-aa13-bff4bbe8f9f1","title":"独酌","author":"杜牧","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["长空碧杳杳，万古一飞鸟。","生前酒伴闲，愁醉闲多少。","烟深隋家寺，殷叶暗相照。","独佩一壶游，秋毫泰山小。"],"theme":"闲适隐逸","theme2":[],"style":"豪放","style2":["雄浑"],"mood":"孤寂","mood2":[],"scene":["酒"],"cats":{"抒情":["孤独"],"山水":["泰山"],"食物":["写酒"]},"theme_conf":0.86},{"uid":"0f7504df-cda2-4fe2-bc63-867ec2e418e7","title":"鼓吹曲辞 将进酒","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["君不见黄河之水天上来，奔流到海不复回。","君不见高堂明镜悲白发，朝如青丝暮成雪。","人生得意须尽欢，莫使金尊空对月。","天生我材必有用，千金散尽还复来。","烹羊宰牛且为乐，会须一饮三百杯。","岑夫子，丹丘生，将进酒，杯莫停。","与君歌一曲，请君为我侧耳听。","钟鼓馔玉不足贵，但愿长醉不复醒。","古来圣贤皆寂寞，惟有饮者留其名。","陈王昔时宴平乐，斗酒十千恣欢谑。","主人何为言少钱，径须酤取对君酌。","五花马，千金裘，呼儿将出换美酒，与尔同销万古愁。"],"theme":"咏怀抒感","theme2":["咏物","哲理悟道"],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["酒"],"cats":{"抒情":["伤感","孤独"],"山水":["黄河"],"食物":["写酒"]},"theme_conf":0.9},{"uid":"eedaf711-5cf8-4bda-aa6a-c66492d6b89e","title":"寄白石师","author":"姚合","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["白石师何在，师禅白石中。","无情云可比，不食鸟难同。","屦下苍苔雪，龛前瀑布风。","相寻未有计，只是礼虚空。"],"theme":"寄赠酬答","theme2":[],"style":"幽峭","style2":[],"mood":"孤寂","mood2":[],"scene":["雪"],"cats":{"山水":["瀑布"]},"theme_conf":0.88},{"uid":"e3553a22-2323-4926-a694-752c3481e2a5","title":"阆州东楼筵奉送十一舅往青城县得昏字","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["曾城有高楼，制古丹雘存。","迢迢百余尺，豁达开四门。","虽有车马客，而无人世喧。","游目俯大江，列筵慰别魂。","是时秋冬交，节往颜色昏。","天寒鸟兽休，霜露在草根。","今我送舅氏，万感集清尊。","岂伊山川间，回首盗贼繁。","高贤意不暇，王命久崩奔。","临风欲恸哭，声出已复吞。"],"theme":"送别","theme2":[],"style":"旷达","style2":["清新","沉郁"],"mood":"悲怆","mood2":["孤寂"],"scene":["楼","秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"山水":["长江"]},"theme_conf":1.0},{"uid":"07e12fb9-a0f7-4cba-81a3-65b03dbf4639","title":"冬至后西湖泛舟看断冰偶成长句","author":"李郢","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["一阳生后阴飙竭，湖上层冰看折时。","云母扇摇当殿色，珊瑚树碎满盘枝。","斜汀藻动鱼应觉，极浦波生鴈未知。","山影浅中留瓦砾，日光寒外送涟漪。","崖崩苇岸纵横散，篙蹙兰舟片段随。","曾向黄河望冲激，大鹏飞起雪风吹。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":["绮丽"],"mood":"欢愉","mood2":[],"scene":["冬","江","舟"],"cats":{"四季":["冬天"],"山水":["黄河","西湖"]},"theme_conf":0.86},{"uid":"3ff36d5d-66cc-48ce-9c48-924ef008666f","title":"送少微师西行","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["随缘忽西去，何日返东林。","世路宁磋别，空门久息心。","人烟一饭少，山雪独行深。","天外猨啼处，谁闻清梵音。"],"theme":"送别","theme2":[],"style":"旷达","style2":["婉约"],"mood":"孤寂","mood2":[],"scene":["雪","山"],"cats":{"抒情":["孤独"],"山水":["庐山"]},"theme_conf":0.673},{"uid":"38869ec6-7ab2-4c91-b1b1-6772267fdf63","title":"过梅里七首  家于无锡四十载今敝庐数堵犹存今列题于后 忆西湖双㶉𫛶","author":"李绅","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["双㶉𫛶，锦毛斓斑长比翼，戏绕莲藂回锦臆。","照灼花丛两相得，渔歌惊起飞南北。","缭绕追随不迷惑，云间上下同栖息。","不作惊禽远相忆，东家少妇机中语。","剪断回文泣机杼，徒嗟孔雀衔毛羽。","一去东南别离苦，五里裴回竟何补。"],"theme":"咏物","theme2":["送别","民生疾苦","咏史怀古"],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["江南","江"],"cats":{"抒情":["离别","思念","怀古"],"山水":["西湖"],"植物":["梅花"]},"theme_conf":0.85},{"uid":"526d4ecc-e123-4b9d-a213-958bb947593d","title":"凉州词二首 一","author":"王之涣","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["黄河远上白云间，一片孤城万仞山。","羌笛何须怨杨柳，春光不度玉门关。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["江","春","山"],"cats":{"抒情":["孤独"],"四季":["春天"],"山水":["黄河"],"生活":["边塞"]},"theme_conf":0.508},{"uid":"0fd38e52-42e1-4989-ac16-985e840e8a59","title":"郊庙歌辞 封泰山乐章 豫和","author":"张说","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["乐已终，[烟]燎上。","怀灵惠，结皇想。","归风疾，回风爽。","百[福]来，众神往。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"山水":["泰山"]},"theme_conf":1.0},{"uid":"4f87da9b-d715-4bc5-8ab8-319d5e0427a4","title":"江行无题一百首 十八","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["柳拂斜开路，篱边数户村。","可能还有意，不掩向江门。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["江"],"cats":{"山水":["江河"],"生活":["乡村"]},"theme_conf":1.0},{"uid":"2049c49c-8641-4e79-9342-992de31f2a5e","title":"酬普选二上人期相会见寄","author":"严维","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["本意宿东林，因听子贱琴。","遥知大小朗，已断去来心。","夜静溪声近，庭寒月色深。","宁知尘外意，定后便成吟。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["月"],"cats":{"山水":["庐山"],"天气":["月亮"]},"theme_conf":0.85},{"uid":"26b530b0-e610-4d5c-b8a1-0d7a9b648dac","title":"相和歌辞 江南曲八首 二","author":"刘希夷","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["艳唱潮初落，江花露未晞。","春洲惊翡翠，朱服弄芳菲。","画舫烟中浅，青阳日际微。","锦帆冲浪湿，罗袖拂行衣。","含情罢所采，相叹惜流晖。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["江","江南"],"cats":{"抒情":["闺怨"],"山水":["江河"]},"theme_conf":0.62},{"uid":"f07a2c0a-2ee3-4e4c-8c67-b13079494901","title":"符亭二首 一","author":"薛能","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["符亭之地雅离群，万古悬泉一旦新。","若念农桑也如此，县人应得似行人。"],"theme":"山水田园","theme2":[],"style":"雄浑","style2":[],"mood":"恬淡","mood2":[],"scene":["楼"],"cats":{"山水":["瀑布"]},"theme_conf":0.73},{"uid":"51c2f843-6831-4226-acf5-93a92e4981a1","title":"相和歌辞  苦寒行","author":"僧贯休","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["北风北风，职何严毒。","摧壮士心，缩金乌足。","冻云嚣嚣碍雪，一片下不得。","声绕枯桑，根在沙塞。","黄河彻底，顽直到海。","一气搏束，万物无态。","唯有吾庭前杉松树枝，枝枝健在。"],"theme":"民生疾苦","theme2":["山水田园"],"style":"悲慨","style2":["幽峭"],"mood":"慷慨","mood2":["愁怨"],"scene":["江","塞外","雪"],"cats":{"山水":["黄河"]},"theme_conf":0.467},{"uid":"02feeee3-8ca8-43eb-9e53-507cd7b9a960","title":"自淇涉黄河途中作十三首 一","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["川上常极目，世情今已闲。","去帆带落日，征路随长山。","亲友若云霄，可望不可攀。","于兹任所惬，浩荡风波间。"],"theme":"羁旅思乡","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["江","舟","山"],"cats":{"抒情":["思乡"],"山水":["黄河"]},"theme_conf":0.86},{"uid":"b1dad78c-4dd8-4b99-b37b-741ed761f26a","title":"宿桐庐江寄广陵旧游","author":"孟浩然","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["山暝闻猿愁，沧江急夜流。","风鸣两岸叶，月照一孤舟。","建德非吾土，维扬忆旧游。","还将两行泪，遥寄海西头。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["江"],"cats":{"抒情":["思念","思乡","伤感"],"山水":["江河"]},"theme_conf":0.78},{"uid":"7e6c09bc-04e4-487b-b201-43aaf6955c73","title":"送苏参军","author":"戎昱","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["忆昨青襟醉里分，酒醒回首怆离群。","舟移极浦城初掩，山束长江日早曛。","客来有恨空思德，别后谁人更议文。","常叹苏生官太屈，应缘才似鲍参军。"],"theme":"送别","theme2":["边塞征战"],"style":"豪放","style2":["沉郁"],"mood":"相思","mood2":["愁怨"],"scene":["江","酒"],"cats":{"抒情":["离别","思念"],"山水":["长江"]},"theme_conf":0.561},{"uid":"cpff779c5996e524","title":"月照梨花・河传","author":"陆游","dynasty":"宋","section":"宋词","form":"词","paragraphs":["霁景风软，烟江春涨。","小阁无人，绣帘半上。","花外姊妹相呼。","约樗蒲。","修蛾忘了章台样。","细思一饷。","感事添惆怅。","胸酥臂玉消减，拟觅双鱼。","倩传书。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["婉约"],"mood":"惆怅","mood2":["孤寂"],"scene":["花","月","楼","春"],"cats":{"抒情":["孤独","闺怨"],"四季":["春天"],"山水":["江河"],"天气":["月亮"],"植物":["梨花"]},"theme_conf":1.0},{"uid":"cb8e3c11-4405-450d-ab33-af54d1dc2df0","title":"五老峰大明观赠隐者","author":"姚系","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["云观此山北，与君携手稀。","林端涉横水，洞口入斜晖。","颇觉鸾鹤迩，忽为烟雾飞。","故人清和客，默会琴心微。","丹术幸可授，青龙当未归。","悠悠平生意，此日复相违。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["山"],"cats":{"抒情":["友情"],"山水":["庐山"]},"theme_conf":0.86},{"uid":"4902d495-3ed3-4aa2-9c67-36a054455042","title":"郊庙歌辞 封泰山乐章 豫和 二","author":"张说","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["亿上帝，临下庭。","骑日月，陪列星。","嘉祝信，大糦馨。","澹神心，醉皇灵。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":["豪放"],"mood":"欢愉","mood2":["恬淡"],"scene":["山"],"cats":{"山水":["泰山"]},"theme_conf":1.0},{"uid":"7782bee4-6ffc-4909-b441-71ab6cd74692","title":"南泾渔父","author":"陆龟蒙","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["予方任疎慵，地僻即所好。","江流背村落，偶往心已嫪。","田家相去远，岑寂且纵傲。","出户手先筇，见人头未帽。","南泾有渔父，往往携稚造。","问其所以渔，对我真蹈道。","我初簎鱼鼈，童丱至于耄。","窟穴与生成，自然通壶奥。","孜孜戒吾属，天物不可暴。","大小参去留，候其孳养报。","终朝获鱼利，鱼亦未常耗。","同覆天地中，违仁辜覆焘。","余观为政者，此意谅难到。","民皆死搜求，莫肯兴愍悼。","今年川泽旱，前岁山源潦。","牒诉已盈庭，闻之类禽噪。","譬如死鸡鹜，岂不容乳抱。","孟子讥宋人，非其揠苗躁。","吾嘉渔父旨，雅叶贤哲操。","倘遇采诗官，斯文诚敢告。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":["旷达"],"mood":"孤寂","mood2":["悲怆"],"scene":[],"cats":{"山水":["江河"],"人物":["父亲"],"生活":["田园"]},"theme_conf":0.472},{"uid":"cpd4852635a024cd","title":"八声甘州","author":"柳永","dynasty":"宋","section":"宋词","form":"词","paragraphs":["对潇潇、暮雨洒江天，一番洗清秋。","渐霜风凄惨，关河冷落，残照当楼。","是处红衰翠减，苒苒物华休。","惟有长江水，无语东流。","不忍登高临远，望故乡渺邈，归思难收。","叹年来踪迹，何事苦淹留。","想佳人、妆楼望，误几回、天际识归舟。","争知我、倚阑干处，正恁凝愁。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["婉约","绮丽"],"mood":"愁怨","mood2":[],"scene":["江"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"山水":["长江"],"人物":["女子"]},"theme_conf":1.0},{"uid":"2204bcb6-175b-46ba-a5f1-60e7e86f526d","title":"冬月长安雨中见终南雪","author":"贾岛","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["秋节新已尽，雨疎露山雪。","西峰稍觉明，残滴犹未绝。","气侵瀑布水，冻著白云穴。","今朝灞浐鴈，何夕潇湘月。","想彼石房人，对雪扉不闭。"],"theme":"山水田园","theme2":["民生疾苦"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["冬","雪","雨","月"],"cats":{"四季":["冬天"],"山水":["瀑布"],"天气":["写雨","写雪","月亮"]},"theme_conf":0.611},{"uid":"8bc003c1-d2d3-4708-b014-7048cda8846b","title":"暝投云智寺渡溪不得却取沿江路往","author":"杜牧","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["双嵓泻一川，回马断桥前。","古庙阴风地，寒钟暮雨天。","沙虚留虎迹，水滑带龙涎。","却下临江路，潮深无渡船。"],"theme":"山水田园","theme2":["哲理悟道"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["江"],"cats":{"山水":["江河","西湖"],"生活":["写桥"]},"theme_conf":0.632},{"uid":"f4a9f923-e4e3-4a02-856b-892800774ad4","title":"白沙渡","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["畏途随长江，渡口下绝岸。","差池上舟楫，杳窕入云汉。","天寒荒野外，日暮中流半。","我马向北嘶，山猨饮相唤。","水清石礧礧，沙白滩漫漫。","迥然洗愁辛，多病一疎散。","高壁抵嵚崟，洪涛越凌乱。","临风独回首，揽辔复三叹。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["愁怨"],"scene":["江"],"cats":{"抒情":["思乡","伤感","孤独"],"山水":["长江"]},"theme_conf":0.78},{"uid":"8c0c4d2b-a459-4a8b-9597-4d479f018863","title":"漫歌八曲 小回中","author":"元结","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["丛石横大江，人言是钓台。","水石相冲激，此中为小回。","回中浪不恶，复在武昌郭。","来客去客船，皆向此中泊。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["舟","江"],"cats":{"抒情":["思乡"],"山水":["长江"]},"theme_conf":0.503},{"uid":"abf7588f-bae4-41b5-8349-4d593f4a92ae","title":"怀江上（句）（卢延逊五举方登第。〖2〗尝作诗云。「狐冲」二句，租庸张相濬每诵之。又「饿猫」二句，成中令汭激赏之。又「栗爆」二句，王中懿建爱之。卢尝谓人曰：「平生投谒公卿，不意得猫儿狗子之力也。」） 三","author":"卢延让","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["栗爆烧氊破，猫跳触鼎翻。","（《北梦琐言》七、《诗话总龟》三九《诙谐门》。","参见同书八《评论门》引《谈苑》）（〖1〗《怀江上》之题，仅见《谈苑》引，为「饿猫」二句之题，另二联题未详。","〖2〗五举，《北梦琐言》作「二十五举」。","〖3〗「犬刺」，《北梦琐言》作「狗触」。","）。"],"theme":"民生疾苦","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["江"],"cats":{"山水":["江河"],"动物":["写猫"]},"theme_conf":0.664},{"uid":"a6e781fe-94d9-48fd-9d57-cc331970e10f","title":"姑苏怀古送秀才下第归江南","author":"刘商","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["姑苏台枕吴江水，层级鳞差向天倚。","秋高露白万林空，低望吴田三百里。","当时雄盛如何比，千仞无根立平地。","台前夹月吹玉鸾，台上迎凉撼金翠。","银河倒泻君王醉，滟酒峩冠眄西子。","宫娃酣态舞娉婷，香飙四飒青城坠。","伍员结舌长嘘嚱，忠谏无因到君耳。","城乌啼尽海霞销，深掩金屏日高睡。","王道潜隳伍员死，可叹斗间瞻王气。","会稽句践拥长矛，万马鸣蹄扫空垒。","瓦解冰销真可耻，凝艳妖芳安足恃。","可怜荒堞晚冥蒙，麋鹿呦呦达遗址。","君怀逸气还东吴，吟狂日日游姑苏。","兴来下笔到奇景，瑶盘迸洒蛟人珠。","大鹏矫翼翻云衢，嵩峰霁后凌天孤。","海潮秋打罗刹石，月魄夜当彭蠡湖。","有时凝思家虚无，霓幢仿佛游仙都。","琳琅暗戛玉华殿，天香静褭金芙蕖。","君声日下闻来久，清赡何人敢敌手。","我逃名迹遁西林，不得灞陵倾别酒。","莫便五湖为隐沦，年年三十升仙人。"],"theme":"咏史怀古","theme2":["送别"],"style":"豪放","style2":["绮丽"],"mood":"孤寂","mood2":["恬淡"],"scene":["江南","江"],"cats":{"抒情":["孤独","怀古"],"山水":["庐山","江河"]},"theme_conf":0.458},{"uid":"e75b38bd-659f-4d46-9c7f-f4213be5f33f","title":"从江西至彭蠡入浙西淮南界道中寄齐相公","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["大贤旧丞相，作镇江山雄。","自镇江山来，何人得如公。","处士待徐孺，仙人期葛洪。","一身控上游，八郡趋下风。","比屋除畏溺，林塘曳烟虹。","生人罢虔刘，井税均且充。","大府肃无事，欢然接悲翁。","心清百丈泉，目送孤飞鸿。","数年鄱阳掾，抱责栖微躬。","首阳及汨罗，无乃褊其衷。","杨朱幷阮籍，未免哀途穷。","四贤虽得仁，此怨何怱怱。","老氏齐宠辱，于陵一穷通。","本师留度门，平等冤亲同。","能依二谛法，了达三轮空。","真境靡方所，出离内外中。","无边尽未来，定惠双修功。","蹇步慙寸进，餙装随转蓬。","朝行楚水阴，夕宿吴洲东。","吴洲复白云，楚水飘丹枫。","晚霞烧廻潮，千里光曈曈。","蓂开海上影，桂吐淮南丛。","何当翼明庭，草木生春融。"],"theme":"寄赠酬答","theme2":[],"style":"悲慨","style2":["雄浑","旷达"],"mood":"悲怆","mood2":["孤寂"],"scene":["江"],"cats":{"抒情":["伤感","孤独"],"山水":["江河"],"节日":["端午节"]},"theme_conf":0.72},{"uid":"bef2cc78-10ff-4c56-8db2-7c496b1891b5","title":"早发若岘驿望庐山","author":"独孤及","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["雨罢山翠鲜，泠泠东风好。","断崖云生处，是向峰顶道。","谁谓峰顶远，跂予可瞻讨。","忘缘祛天机，脱屐恨不早。","祗恐岁云暮，遂与空名老。","心往迹未幷，惭愧山上草。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["山"],"cats":{"抒情":["思乡"],"山水":["庐山"]},"theme_conf":0.548},{"uid":"15520925-c4b7-4f94-a3dd-e79e48420c45","title":"同中书刘舍人题青龙上房","author":"韩翃","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["西掖归来后，东林静者期。","远峰春雪里，寒竹暮天时。","笑说金人偈，闲听宝月诗。","更怜茶兴在，好出下方迟。"],"theme":"佛道禅颂","theme2":["咏物","山水田园","哲理悟道"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":["欢愉"],"scene":["雪","春","月","山"],"cats":{"四季":["春天"],"山水":["庐山"]},"theme_conf":0.72},{"uid":"29f6c161-100e-4023-90c0-26a5739b7e53","title":"谕宝二首 一","author":"元稹","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["沈玉在弱泥，泥弱玉易沈。","扶桑寒日薄，不照万丈心。","安得潜渊虬，拔壑超邓林。","泥封泰山阯，水散旱天霖。","洗此泥下玉，照耀台殿深。","刻为传国宝，神器人不侵。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"山水":["泰山"]},"theme_conf":1.0},{"uid":"2205cb99-73fb-4acc-976f-5f2eeb381baa","title":"庐山瀑布歌送李顾","author":"顾况","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["飘白霓，挂丹梯。","应从织女机边落，不遣浔阳湖向西。","火雷劈山珠喷日，五老峰前九江溢。","九江悠悠万古情，古人行尽今人行。","老人也欲上山去，上个深山无姓名。"],"theme":"送别","theme2":["山水田园"],"style":"雄浑","style2":[],"mood":"惆怅","mood2":[],"scene":["山"],"cats":{"山水":["庐山","瀑布"],"节日":["七夕节"]},"theme_conf":0.631},{"uid":"a2d9200a-2ba4-4232-8ebc-3c07e377b060","title":"题水洞二首 二","author":"刘商","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["长看岩穴泉流出，忽听悬泉入洞声。","莫摘山花抛水上，花浮出洞世人惊。"],"theme":"山水田园","theme2":["咏物"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"山水":["瀑布"]},"theme_conf":0.579},{"uid":"20491a26-8ddd-490c-bc26-c8d48929d779","title":"登蒲州石矶望横江口潭岛深逈斜对香零山","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["隐忧倦永夜，凌雾临江津。","猿鸣稍已疎，登石娱清沦。","日出洲渚静，澄明皛无垠。","浮晖翻高禽，沈景照文鳞。","双江汇西奔，诡怪潜坤珍。","孤山乃北峙，森爽栖灵神。","洄潭或动容，岛屿疑摇振。","陶埴兹择土，蒲鱼相与邻。","信美非所安，羁心屡逡巡。","𫄙结良可解，纡郁亦已伸。","高歌返故室，自𫍬非所欣。"],"theme":"咏史怀古","theme2":["山水田园","羁旅思乡"],"style":"幽峭","style2":["清新"],"mood":"恬淡","mood2":["孤寂","愁怨"],"scene":["江","山"],"cats":{"抒情":["思乡","孤独","怀古"],"山水":["江河","西湖"]},"theme_conf":0.388},{"uid":"252b4e33-b8d1-462d-a8e9-55a9766df5cf","title":"送惠师","author":"韩愈","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["惠师浮屠者，乃是不羇人。","十五爱山水，超然谢朋亲。","脱冠翦头发，飞步遗踪尘。","发迹入四明，梯空上秋旻。","遂登天台望，众壑皆嶙峋。","夜宿最高顶，举头看星辰。","光芒相照烛，南北争罗陈。","兹地绝翔走，自然严且神。","微风吹木石，澎湃闻韶钧。","夜半起下视，溟波衔日轮。","鱼龙惊踊跃，呌啸成悲辛。","怪气或紫赤，敲磨共轮囷。","金鸦既腾翥，六合俄清新。","常闻禹穴奇，东去窥瓯闽。","越俗不好古，流传失其真。","幽踪邈难得，圣路嗟长堙。","回临浙江涛，屹起高峨岷。","壮志死不息，千年如隔晨。","是非竟何有，弃去非吾伦。","凌江诣庐岳，浩荡极游巡。","崔崒没云表，陂陀浸湖沦。","是时雨初霁，悬瀑垂天绅。","前年往罗浮，步戛南海漘。","大哉阳德盛，荣茂恒留春。","鹏𬸣堕长翮，鲸戏侧修鳞。","自来连州寺，曾未造城𬮱。","日携青云客，探胜穷崖滨。","太守邀不去，群官请徒频。","囊无一金资，翻谓富者贫。","昨日忽不见，我令访其隣。","奔波自追及，把手问所因。","顾我却兴欢，君宁异于民。","离合自古然，辞别安足珍。","吾闻九疑好，夙志今欲伸。","斑竹啼舜妇，清湘沈楚臣。","衡山与洞庭，此固道所循。","寻崧方抵洛，历华遂之秦。","浮游靡定处，偶往即通津。","吾言子当去，子道非吾遵。","江鱼不池活，野鸟难笼驯。","吾非西方教，怜子狂且醇。","吾嫉惰游者，怜子愚且谆。","去矣各异趣，何为浪沾巾。"],"theme":"送别","theme2":[],"style":"清新","style2":["幽峭","豪放"],"mood":"悲怆","mood2":["慷慨","欢愉"],"scene":["江","山"],"cats":{"抒情":["离别","伤感"],"山水":["江河"],"人生":["励志","梦想"]},"theme_conf":0.619},{"uid":"cp5992981c866722","title":"高阳台","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["修竹凝妆，垂杨驻马，凭阑浅画成图。","山色谁题，楼前有雁斜书。","东风紧送斜阳下，弄旧寒、晚酒醒馀。","自销凝，能几花前，顿老相如。","伤春不在高楼上，在灯前攲枕，雨外熏炉。","怕舣游船，临流可奈清臞。","飞红若到西湖底，搅翠澜、总是愁鱼。","莫重来，吹尽香绵，泪满平芜。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["婉约","绮丽"],"mood":"愁怨","mood2":[],"scene":["楼","春","花"],"cats":{"抒情":["伤感"],"四季":["春天"],"山水":["西湖"]},"theme_conf":1.0},{"uid":"97e74ab5-16ae-4acf-b0b1-9329ebce61fe","title":"詶浙东李侍郎越州春晚即事长句","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["越中蔼蔼繁华地，秦望峰前禹穴西。","湖草初生边鴈去，山花半谢杜鹃啼。","青油昼卷临高阁，红斾晴翻绕古堤。","明日汉庭征旧德，老人争出若耶溪。"],"theme":"山水田园","theme2":["应制干谒"],"style":"绮丽","style2":["清新"],"mood":"恬淡","mood2":[],"scene":["江南"],"cats":{"四季":["春天"],"山水":["西湖"]},"theme_conf":0.545},{"uid":"d9bb3556-f0d9-4989-afdd-0163fb826a01","title":"相和歌辞 从军行","author":"刘希夷","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["秋来风瑟瑟，群马胡行疾。","严城昼不开，伏兵暗相失。","天子庙堂拜，将军玉门出。","纷纷伊洛间，戎马数千匹。","军门压黄河，兵气冲白日。","平生怀伏劒，忼慨既投笔。","南登汉月孤，北走燕云密。","近取韩彭计，早知孙吴术。","丈夫清万里，谁能埽一室。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":["孤寂"],"scene":["江","秋","月"],"cats":{"抒情":["孤独"],"四季":["秋天"],"山水":["黄河"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"4d79a7f2-2e3c-496a-b9bd-9f778aee26ee","title":"秋日旅舍别司空文明","author":"李端","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["凉风飒穷巷，秋思满高云。","吏隐俱不就，此心仍别君。","素怀宗淡泊，羁旅念功勋。","转忆西林寺，江声月下闻。"],"theme":"羁旅思乡","theme2":["送别"],"style":"冲淡","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["秋"],"cats":{"抒情":["离别","思念","思乡"],"四季":["秋天"],"山水":["庐山"]},"theme_conf":0.477},{"uid":"f96506ea-e8ac-47e0-a0a6-ccd306e56645","title":"旅夜书怀","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["细草微风岸，危樯独夜舟。","星垂平野阔，月涌大江流。","名岂文章著，官因老病休。","飘飘何所似，天地一沙鸥。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"孤寂","mood2":[],"scene":["夜"],"cats":{"抒情":["思乡","孤独"],"山水":["江河","长江"]},"theme_conf":0.651},{"uid":"cp39e5bcd45f57af","title":"卜算子","author":"李之仪","dynasty":"宋","section":"宋词","form":"词","paragraphs":["我住长江头，君住长江尾。","日日思君不见君，共饮长江水。","此水几时休，此恨何时已。","只愿君心似我心，定不负相思意。"],"theme":"爱情相思","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["江"],"cats":{"抒情":["爱情","思念"],"山水":["长江"]},"theme_conf":1.0},{"uid":"e9a7af99-eb7c-4977-bb08-833c8f32f7f9","title":"早春西湖闲游怅然兴怀忆与微之同赏因思在越官重事殷镜湖之游或恐未暇偶成十八韵寄微之","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["上马复呼宾，湖边景气新。","管弦三数事，骑从十余人。","立换登山屐，行携漉酒巾。","逢花看当妓，遇草坐为茵。","西日笼黄柳，东风荡白苹。","小桥装鴈齿，轻浪甃鱼鳞。","画舫牵徐转，银船酌慢巡。","野情遗世累，醉态任天真。","彼此年将老，平生分最亲。","高天从所愿，远地得为邻。","云树分三驿，烟波限一津。","飜嗟寸步隔，却厌尺书频。","浙右称雄镇，山阴委重臣。","贵垂长紫绶，荣驾大朱轮。","出动刀枪队，归生道路尘。","鴈惊弓易散，鸥怕鼓难驯。","百吏瞻相面，千夫捧拥身。","自然闲兴少，应负镜湖春。"],"theme":"寄赠酬答","theme2":["送别"],"style":"婉约","style2":["豪放"],"mood":"欢愉","mood2":["相思","恬淡"],"scene":["江南","春","江","酒"],"cats":{"抒情":["思念"],"四季":["春天"],"山水":["西湖"],"生活":["写桥"]},"theme_conf":0.9},{"uid":"ce8e3003-0741-4a1d-94ee-761086827b5d","title":"唐封泰山乐章 豫和六首 一","author":"张说","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["挹泰坛，紫泰清。","受天命，报天成。","竦皇心，荐乐声。","志上达，歌下迎。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"山水":["泰山"]},"theme_conf":1.0},{"uid":"132c7276-e108-4501-b619-ae997cf31e4b","title":"杂曲歌辞 江上曲","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["江上澹澹芙蓉花，江口蛾眉独浣纱。","可怜应是阳台女，坐对鸬鹚娇不语。","掩面羞看北地人，回首忽作空山雨。","苍梧秋色不堪论，千载依依帝子魂。","君看峰上斑斑竹，尽是湘妃泣泪痕。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":["婉约"],"mood":"孤寂","mood2":["恬淡","悲怆"],"scene":["江","山"],"cats":{"抒情":["伤感","孤独"],"山水":["江河"]},"theme_conf":1.0},{"uid":"9080a103-2750-4b9b-a4fa-1167cd670a0c","title":"汉江临泛","author":"王维","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["楚塞三湘接，荆门九派通。","江流天地外，山色有无中。","郡邑浮前浦，波澜动远空。","襄阳好风日，留醉与山翁。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["江"],"cats":{"山水":["江河"]},"theme_conf":0.686},{"uid":"cp0be6d5514dd406","title":"临江仙","author":"晁冲之","dynasty":"宋","section":"宋词","form":"词","paragraphs":["忆昔西池池上饮，年年多少欢娱。","别来不寄一行书。","寻常相见了，犹道不如初。","安稳锦屏今夜梦，月明好度江湖。","相思休问定何如。","情知春去后，管得落花无。"],"theme":"送别","theme2":["爱情相思"],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["江"],"cats":{"抒情":["爱情","思念"],"山水":["江河"]},"theme_conf":0.469},{"uid":"9e49be0f-69ae-44a6-a0d6-dcd636c6452f","title":"寄哥舒仆射","author":"韩翃","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["万里长城家，一生唯报国。","腰垂紫文绶，手控黄金勒。","高视黑头翁，遥吞白骑贼。","先麾牙门将，转鬬黄河北。","帐下亲兵皆少年，锦衣承日绣行缠。","辘轳宝劒初出鞘，宛转角弓初上弦。","步人抽箭大如笛，前把两矛后双戟。","左盘右射红尘中，鹘入鸦群有谁敌。","杀将破军白日余，回旃舞旆北风初。","郡公楯鼻好磨墨，走马为君飞羽书。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":[],"mood":"慷慨","mood2":[],"scene":["江"],"cats":{"抒情":["爱国"],"山水":["黄河"]},"theme_conf":0.672},{"uid":"66312123-6671-49e5-a4ed-790959f4157e","title":"江村乱后","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["江村日暮寻遗老，江水东流横浩浩。","竹里闲窗不见人，门前旧路生青草。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"恬淡","mood2":[],"scene":["江"],"cats":{"山水":["江河"],"生活":["乡村"]},"theme_conf":0.785},{"uid":"6ed3a7f5-c68a-40ba-b28f-50ebbfac1091","title":"相和歌辞 春江花月夜二首 二","author":"张子容","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["交甫怜瑶佩，仙妃难重期。","沈沈绿江晚，惆怅碧云姿。","初逢花上月，言是弄珠时。"],"theme":"山水田园","theme2":[],"style":"清新","style2":["绮丽"],"mood":"惆怅","mood2":[],"scene":["月","江","春","花","夜"],"cats":{"四季":["春天"],"山水":["江河"],"天气":["月亮"]},"theme_conf":0.65},{"uid":"7a6e1b7d-494b-4ffe-94ac-2b69f9784f35","title":"江涨","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["江涨柴门外，儿童报急流。","下床高数尺，倚杖没中洲。","细动迎风燕，轻摇逐浪鸥。","渔人萦小楫，容易拔船头。"],"theme":"山水田园","theme2":[],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["江"],"cats":{"山水":["江河"],"人物":["儿童"]},"theme_conf":1.0},{"uid":"fbf22c24-6020-4423-b6ce-2980ad7128d6","title":"过天门街","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["雪尽终南又欲春，遥怜翠色对红尘。","千车万马九衢上，回首看山无一人。"],"theme":"咏史怀古","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["雪","春","山"],"cats":{"抒情":["怀古"],"四季":["春天"],"山水":["泰山"]},"theme_conf":1.0},{"uid":"3c19217c-7f07-45f9-b317-3744725dc11c","title":"郊庙歌辞 禅社首乐章 福和","author":"贺知章、源乾曜","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["穆穆天子，告成岱宗。","大裘如濡，执珽有颙。","乐以平志，礼以和容。","上帝临我，云胡肃邕。"],"theme":"哲理悟道","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"山水":["泰山"],"人生":["哲理"]},"theme_conf":0.692},{"uid":"417dd972-fc55-4972-b698-e5e595453dbd","title":"相和歌辞 王昭君","author":"刘长卿","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["自矜妖艳色，不顾丹青人。","那知粉缋能相负，却使容华飜误身。","上马辞君嫁骄虏，玉颜对人啼不语。","北风雁急浮清秋，万里独见黄河流。","纤腰不复汉宫宠，双蛾长向胡天愁。","琵琶弦中苦调多，萧萧羌笛声相和。","可怜一曲传乐府，能使千秋伤绮罗。"],"theme":"题画咏艺","theme2":["边塞征战"],"style":"绮丽","style2":["豪放"],"mood":"愁怨","mood2":[],"scene":["江","秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"山水":["黄河"]},"theme_conf":0.435},{"uid":"fd353d00-a484-4bb1-a4d7-e595fac0ea52","title":"郊庙歌辞 封泰山乐章 豫和 四","author":"张说","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["高在上，道光明。","物资始，德难名。","承眷命，牧苍生。","寰宇谧，太阶平。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"山水":["泰山"]},"theme_conf":1.0},{"uid":"ee523bdd-916e-4c51-b261-5bbc2d6f5bfd","title":"八哀诗 故司徒李公光弼","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["司徒天宝末，北收晋阳甲。","胡骑攻吾城，愁寂意不惬。","人安若泰山，蓟北断右胁。","朔方气乃苏，黎首见帝业。","二宫泣西郊，九庙起颓压。","未散河阳卒，思明伪臣妾。","复自碣石来，火焚乾坤猎。","高视笑禄山，公又大献捷。","异王册崇勋，小敌信所怯。","拥兵镇河汴，千里初妥帖。","青蝇纷营营，风雨秋一叶。","内省未入朝死泪终映睫。","大屋去高栋，长城埽遗堞。","平生白羽扇，零落蛟龙匣。","雅望与英姿，恻怆槐里接。","三军晦光彩，烈士痛稠叠。","直笔在史臣，将来洗箱箧。","吾思哭孤冢，南纪阻归楫。","扶颠永萧条，未济失利涉。","疲{艹/尔}竟何人，洒涕巴东峡。"],"theme":"悼亡挽歌","theme2":["边塞征战"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["山","雨"],"cats":{"抒情":["伤感","悼亡"],"山水":["泰山"]},"theme_conf":0.97},{"uid":"9d10fdb5-9d0a-4c80-9e21-27f82b929c9f","title":"相和歌辞 江南曲","author":"韩翃","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["长乐花枝雨点消，江城日暮好相邀。","春楼不闭葳蕤锁，绿水回通宛转桥。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["江南","江"],"cats":{"山水":["江河"],"生活":["写桥"]},"theme_conf":0.65},{"uid":"939b6cc6-63cf-4c88-a5bf-7396fac69fb1","title":"题青龙寺镜公房","author":"马戴","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["一室意何有，闲门为我开。","炉香寒自灭，履雪饭初回。","窗迥孤山入，灯残片月来。","禅心方此地，不必访天台。"],"theme":"佛道禅颂","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["冬","雪","月","山"],"cats":{"抒情":["孤独"],"山水":["西湖"],"人生":["哲理"]},"theme_conf":0.86},{"uid":"8e2f586b-9ef4-4672-af24-723a5ec87773","title":"和令狐舍人酬峰上人题山栏孤竹","author":"杨巨源","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["满院冰姿粉箨残，一茎青翠近帘端。","离丛自欲亲香火，抱节何妨共岁寒。","能让繁声任真籁，解将孤影对芳兰。","范云许访西林寺，枝叶须和彩凤看。"],"theme":"山水田园","theme2":["送别"],"style":"沉郁","style2":["旷达"],"mood":"孤寂","mood2":[],"scene":["山","冬"],"cats":{"抒情":["孤独"],"四季":["冬天"],"山水":["庐山"],"植物":["竹子"]},"theme_conf":0.381},{"uid":"22624fe3-d419-451c-81e0-51d4be56e014","title":"长江二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["众水会涪万，瞿塘争一门。","朝宗人共挹，盗贼尔谁尊。","孤石隐如马，高萝垂饮猨。","归心异波浪，何事即飞飜。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["江"],"cats":{"抒情":["思乡","孤独"],"山水":["长江"]},"theme_conf":1.0},{"uid":"0422e408-0484-40d0-b826-da8e2c947490","title":"猛虎行","author":"李贺","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["长戈莫舂，长弩莫抨。","乳孙哺子，教得生狞。","举头为城，掉尾为旌。","东海黄公，愁见夜行。","道逢驺虞，牛哀不平。","何用尺刀，壁上雷鸣。","泰山之下，妇人哭声。","官家有程，吏不敢听。"],"theme":"边塞征战","theme2":["悼亡挽歌","羁旅思乡"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["山"],"cats":{"抒情":["思乡","伤感","悼亡"],"山水":["泰山"]},"theme_conf":0.408},{"uid":"a4856804-965c-40d0-a54d-5379ace1d95c","title":"陪王使君晦日泛江就黄家亭子二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["山豁何时断，江平不肯流。","稍知花改岸，始验鸟随舟。","结束多红粉，欢娱恨白头。","非君爱人客，晦日更添愁。"],"theme":"羁旅思乡","theme2":["送别"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["江"],"cats":{"抒情":["思乡","伤感"],"山水":["江河"],"天气":["太阳"]},"theme_conf":0.634},{"uid":"952ec2cf-b0ac-4fc9-b83e-90b60ab4c4a9","title":"和刘侍郎入隆唐观","author":"杨炯","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["福地阴阳合，仙都日月开。","山川临四险，城树隐三台。","伏槛排云出，飞轩遶涧回。","参差凌倒影，潇洒轶浮埃。","百果珠为实，群峰锦作苔。","悬萝暗疑雾，瀑布响成雷。","方士烧丹液，真人泛玉杯。","还如问桃水，更似得蓬莱。","汉帝求仙日，相如作赋才。","自然金石奏，何必上天台。"],"theme":"山水田园","theme2":["游仙梦幻","应制干谒"],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["山","楼","月"],"cats":{"山水":["瀑布"]},"theme_conf":0.427},{"uid":"bd285a68-be33-4ac0-b7ca-0dbd2b19b885","title":"平齐行二首 二","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["泰山沈寇六十年，旅祭不享生愁烟。","今逢圣君欲封禅，神使阴兵来阻战。","妖氛扫尽河水清，日观杲杲卿云见。","开元黄帝东封时，百神受职争奔驰。","千钧猛簴顺流下，洪波涵淡浮熊罴。","侍臣燕公秉文笔，玉检告天无媿词。","当今睿孙承圣祖，岳神望幸河宗舞。","青门大道属车尘，共待葳蕤翠华举。"],"theme":"应制干谒","theme2":["边塞征战","闺情宫怨","哲理悟道"],"style":"绮丽","style2":["清新"],"mood":"愁怨","mood2":["恬淡"],"scene":["山"],"cats":{"抒情":["伤感","闺怨"],"山水":["泰山"],"人生":["哲理","战争"]},"theme_conf":0.82},{"uid":"0145ae39-2773-42f7-9287-ea653ce947a7","title":"过故斛斯校书庄二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["燕入非旁舍，鸥归祗故池。","断桥无复板，卧柳自生枝。","遂有山阳作，多惭鲍叔知。","素交零落尽，白首泪双垂。"],"theme":"咏史怀古","theme2":["山水田园"],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["山"],"cats":{"抒情":["伤感","怀古"],"山水":["西湖"],"生活":["写桥"]},"theme_conf":0.617},{"uid":"9bb05363-395d-48f6-b28a-55d3e414d6cf","title":"杂曲歌辞 发白马","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["将军发白马，旌节渡黄河。","箫鼓聒川岳，沧溟涌洪波。","武安有振瓦，易水无寒歌。","铁骑若雪山，饮流涸滹沱。","扬兵猎月窟，转战畧朝那。","倚剑登燕然，边峰列嵯峨。","萧条万里外，耕作五原多。","一扫清大漠，包虎戢金戈。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["雄浑","清新"],"mood":"慷慨","mood2":[],"scene":["山","江","雪","塞外","月"],"cats":{"山水":["黄河"],"人生":["战争"],"生活":["边塞"],"动物":["写马"]},"theme_conf":0.777},{"uid":"feb085bc-e461-4a18-b787-e831e3ef1885","title":"宿庐山赠白鹤观刘尊师","author":"包佶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["苍苍五老雾中坛，杳杳三山洞里官。","手护昆仑象牙简，心推霹雳枣枝盘。","春飞雪粉如毫润，晓漱琼膏冰齿寒。","渐恨流年筋力少，惟思露冕事星冠。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":["清新","雄浑"],"mood":"愁怨","mood2":[],"scene":["山","雪"],"cats":{"山水":["庐山"],"天气":["写雪"],"人生":["时光"],"动物":["写鸟"]},"theme_conf":0.72},{"uid":"0ee73c58-cce4-4852-b95b-73ce2d12618e","title":"过宣上人湖上兰若","author":"朱湾","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["十年湖上结幽期，偏向东林遇远师。","未道姓名童子识，不酬言语上人知。","闲花落日滋苔径，细雨和烟著柳枝。","问我别来何所得，解将无事当无为。"],"theme":"佛道禅颂","theme2":["闲适隐逸","山水田园","咏史怀古"],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["江","雨"],"cats":{"抒情":["怀古"],"山水":["庐山"],"天气":["写雨"]},"theme_conf":0.82},{"uid":"3c004054-61d3-442e-b15c-07ee460b9cfe","title":"天门谷题孙逸人石壁","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["崖石乱流处，竹深斜照归。","主人卧磻石，心耳涤清晖。","春雷近作解，空谷半芳菲。","云栋彩虹宿，药圃蝴蝶飞。","恶嚣慕嘉遯，几夜瞻少微。","相见竟何说，忘情同息机。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"幽峭","style2":[],"mood":"恬淡","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"山水":["泰山"],"天气":["彩虹"]},"theme_conf":0.465},{"uid":"325be953-64ad-4563-85bc-3d3814ab485d","title":"送孔江州","author":"权德舆","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["九派寻阳郡，分明似画图。","秋光连瀑布，晴翠辨香𬬻。","才子厌兰省，邦君荣竹符。","江城多暇日，能寄八行无。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["江"],"cats":{"山水":["江河","瀑布"]},"theme_conf":0.826},{"uid":"5cd3431c-26c9-4049-90d6-f5049ca88c3e","title":"暝投灵智寺渡谿不得却取沿江路往","author":"许浑","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["双岩泻一川，回马断桥前。","古庙阴风地，寒钟暮雨天。","沙虚留虎迹，水滑带龙涎。","却下临江路，潮深无渡船。"],"theme":"哲理悟道","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["江"],"cats":{"山水":["江河","西湖"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"2ac203a8-6e70-4b78-ad75-9acacae9b04a","title":"相和歌辞  北上行","author":"李白","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["北上何所苦，北上缘太行。","磴道盘且峻，巉岩凌穹苍。","马足蹶侧石，车轮摧高冈。","沙尘接幽州，烽火连朔方。","杀气毒劒戟，严风裂衣裳。","奔鲸夹黄河，凿齿屯洛阳。","前行无归日，返顾思旧乡。","惨戚冰雪里，悲号绝中肠。","尺布不掩体，皮肤剧枯桑。","汲水涧谷阻，采薪陇坂长。","猛虎又掉尾，磨牙皓秋霜。","草木不可湌，饥饮零露浆。","叹此北上苦，停骖为之伤。","何日王道平？开颜覩天光。"],"theme":"边塞征战","theme2":["民生疾苦","山水田园","羁旅思乡"],"style":"豪放","style2":[],"mood":"相思","mood2":["悲怆"],"scene":["秋","冬","江","雪"],"cats":{"抒情":["思念","思乡","伤感"],"四季":["秋天"],"山水":["黄河"],"天气":["写雪"],"人生":["战争"]},"theme_conf":0.296},{"uid":"b0f61bf4-5c31-4875-a33f-97de1a1560d2","title":"浪淘沙九首 一","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["九曲黄河万里沙，浪淘风簸自天涯。","如今直上银河去，同到牵牛织女家。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":["江","七夕"],"cats":{"抒情":["思乡"],"山水":["黄河"],"天气":["星星"],"节日":["七夕节"]},"theme_conf":0.551},{"uid":"2c044e03-74a7-41e1-a28e-1386228564c3","title":"寄衞明府常见短靴褐裘又务持诵是以有末句之赠","author":"司空曙","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["柴桑官舍近东林，儿稚初髫即道心。","侧寄绳床嫌凭几，斜安苔帻嬾穿簪。","高僧静望山僮逐，走吏喧来水鸭沈。","翠竹黄花皆佛性，莫教尘境误相侵。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"山水":["庐山"]},"theme_conf":0.93},{"uid":"ac2f736a-0a3d-4ec1-a855-374f26faff25","title":"再至界围岩水帘遂宿岩下","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["发春念长违，中夏欣再覩。","是时植物秀，杳若临悬圃。","歊阳讶垂冰，白日惊雷雨。","笙簧潭际起，鹳鹤云间舞。","古苔凝青枝，阴草湿翠羽。","蔽空素彩列，激浪寒光聚。","的皪沈珠渊，锵鸣捐佩浦。","幽岩画屏倚，新月玉钩吐。","夜凉星满川，忽疑眠洞府。"],"theme":"山水田园","theme2":["闺情宫怨"],"style":"绮丽","style2":["婉约","冲淡"],"mood":"孤寂","mood2":[],"scene":["山"],"cats":{"抒情":["闺怨"],"山水":["瀑布"]},"theme_conf":0.579},{"uid":"35f446ec-9bd1-4df3-bb94-7b3b45888f24","title":"新乐府 缭绫\t\t念女工之劳也","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["缭绫缭绫何所似，不似罗绡与纨绮。","应似天台山上月明前，四十五尺瀑布泉。","中有文章又奇绝，地铺白烟花簇雪。","织者何人衣者谁，越溪寒女汉宫姬。","去年中使宣口敕，天上取样人间织。","织为云外秋雁行，染作江南春水色。","广裁衫袖长制帬，金斗熨波刀翦纹。","异彩奇文相隐映，转侧看花花不定。","昭阳舞人恩正深，春衣一对直千金。","汗沾粉污不再著，曳土蹋泥无惜心。","缭绫织成费功绩，莫比寻常缯与帛。","丝细缲多女手疼，扎扎千声不盈尺。","昭阳殿里歌舞人，若见织时应也惜。"],"theme":"山水田园","theme2":["闺情宫怨"],"style":"绮丽","style2":["幽峭"],"mood":"欢愉","mood2":[],"scene":["江南"],"cats":{"抒情":["闺怨"],"山水":["瀑布"]},"theme_conf":0.585},{"uid":"f6cb3848-f434-458b-aebf-8fb321d13ca6","title":"郊庙歌辞 封泰山乐章 寿和","author":"张说","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["皇祖严配，配享皇天。","皇皇降嘏，天子万年。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"山水":["泰山"]},"theme_conf":1.0},{"uid":"207b2dcf-2f03-4fe2-8a1d-47e4f41f9325","title":"酬乐天雪中见寄","author":"元稹","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["知君夜听风萧索，晓望林亭雪半糊。","撼落不教封柳眼，埽来偏尽附梅株。","敲扶密竹枝犹亚，煦暖寒禽气渐苏。","坐觉湖声迷远浪，回惊云路在长途。","钱塘湖上苹先合，梳洗楼前粉暗铺。","石立玉童披鹤氅，台施瑶席换龙须。","满空飞舞应为瑞，寡和高歌只自娱。","莫遣拥帘伤思妇，且将盈尺慰农夫。","称觞彼此情何异，对景东西事有殊。","镜水遶山山尽白，琉璃云母世间无。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":["冲淡"],"mood":"欢愉","mood2":["孤寂","相思"],"scene":["雪","冬","楼"],"cats":{"山水":["西湖"],"天气":["写雪"]},"theme_conf":0.95},{"uid":"4a9c0b9d-b051-4f1b-b4b7-c6b70db36ea7","title":"郊庙歌辞 封泰山乐章 寿和","author":"张说","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["烝烝我后，享献惟夤。","躬酌郁鬯，跪奠明神。","孝莫孝乎，配上帝亲。","敬莫敬乎，教天下臣。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"山水":["泰山"]},"theme_conf":1.0},{"uid":"0f980b6f-473d-4f04-8090-0e04da5e2655","title":"奉同郭给事汤东灵湫作","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["东山气鸿蒙，宫殿居上头。","君来必十月，树羽临九州。","阴火煮玉泉，喷薄涨岩幽。","有时浴赤日，光抱空中搂。","阆风入辙迹，旷原延冥搜。","沸天万乘动，观水百丈湫。","幽灵斯可佳，王命宫属休。","初闻龙用壮，擘石摧林丘。","中夜窟宅改，移因风雨秋。","倒悬瑶池影，屈注苍江流。","味如甘露浆，挥弄滑且柔。","翠旗澹偃蹇，云车纷少留。","箫鼓荡四溟，异香泱漭浮。","鲛人献微绡，曾祝沈豪牛。","百祥奔盛明，古先莫能俦。","坡陀金虾蟆，出见盖有由。","至尊顾之笑，王母不肯收。","复归虚无底，化作长黄虬。","飘飘青琐郎，文采珊瑚钩。","浩歌渌水曲，清绝听者愁。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":["婉约","冲淡"],"mood":"慷慨","mood2":["愁怨","恬淡"],"scene":["山","雨","秋"],"cats":{"抒情":["伤感","爱国"],"四季":["秋天"],"山水":["江河"]},"theme_conf":1.0},{"uid":"be118ff0-566d-466d-ac07-0de6e6493419","title":"雨中宿义兴寺","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["遥夜宿东林，虫声阶草深。","高风初落叶，多雨未归心。","家国身犹负，星霜鬓已侵。","沧洲纵不去，何处有知音。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["雨"],"cats":{"抒情":["友情","思乡"],"山水":["庐山"],"天气":["写雨"]},"theme_conf":0.658},{"uid":"8674fa82-1c80-400d-b329-2c6ef1c5fee2","title":"冬日汉江南行将赴夏口途次江陵界寄裴尚书","author":"武元衡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["五部拥双旌，南依墨客卿。","关山迥梁甸，波浪接湓城。","烟景迷时候，云帆渺去程。","蛤珠冯月吐，芦雁触罗惊。","浦树凝寒晦，江天湛镜清。","赏心随处惬，壮志逐年轻。","舟檝不可驻，提封如任情。","向方曾指路，射策许言兵。","兰渚歇芳意，菱歌非应声。","元戎武昌守，羊祜幸连营。"],"theme":"寄赠酬答","theme2":["送别","山水田园"],"style":"绮丽","style2":[],"mood":"慷慨","mood2":[],"scene":["江","江南","冬","夏","舟"],"cats":{"四季":["夏天","冬天"],"山水":["江河"],"人生":["励志","梦想"]},"theme_conf":0.87},{"uid":"12fdaad8-b197-4526-b56d-c7c713267248","title":"望岳","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["岱宗夫如何，齐鲁青未了。","造化钟神秀，阴阳割昏晓。","荡胷生曾云，决眦入归鸟。","会当凌绝顶，一览众山小。"],"theme":"山水田园","theme2":["哲理悟道"],"style":"冲淡","style2":[],"mood":"慷慨","mood2":[],"scene":["山"],"cats":{"山水":["泰山"]},"theme_conf":0.56},{"uid":"6fc239af-e267-4a89-a804-330cf037dcb5","title":"秋夜有怀高三十五兼呈空和尚","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["晚节闻君趋道深，结茅栽树近东林。","大师几度曾摩顶，高士何年遂发心。","北渚三更闻过雁，西城万里动寒砧。","不见支公与玄度，相思拥膝坐长吟。"],"theme":"哲理悟道","theme2":["爱情相思"],"style":"豪放","style2":["冲淡"],"mood":"相思","mood2":["孤寂"],"scene":["夜","秋"],"cats":{"抒情":["爱情","思念"],"四季":["秋天"],"山水":["庐山"]},"theme_conf":0.603},{"uid":"5f4eb2fc-17fd-4302-88e6-4bda6fcff473","title":"鼓吹曲辞 巫山高","author":"李贺","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["碧丛丛，高插天，大江翻澜神曳烟。","楚魂寻梦风飔然，晓风飞雨生苔钱。","瑶姬一去一千年，丁香笻竹啼老猨。","古祠近月蟾桂寒，椒花坠红湿云间。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山","月","花"],"cats":{"山水":["长江"]},"theme_conf":1.0},{"uid":"163e6b84-544c-426c-820f-0b6bac718a2d","title":"相和歌辞 江南曲","author":"罗隐","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["江烟湿雨鲛绡輭，漠漠远山眉黛浅。","水国多愁又有情，夜槽压酒银船满。","绷丝采怨凝晓空，吴王台榭春梦中。","鸳鸯㶉𫛶唤不起，平铺渌水眠东风。","西陵路边月悄悄，油壁轻车嫁苏小。"],"theme":"咏史怀古","theme2":["山水田园","爱情相思"],"style":"婉约","style2":["冲淡"],"mood":"愁怨","mood2":[],"scene":["江南","江"],"cats":{"抒情":["爱情","伤感","怀古"],"四季":["春天"],"山水":["江河"]},"theme_conf":0.55},{"uid":"99b28edd-1f27-415b-993f-f7ca05f18279","title":"深上人见访忆李端","author":"司空曙","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["雁稀秋色尽，落日对寒山。","避事多称疾，留僧独闭关。","心归尘俗外，道胜有无间。","仍忆东林友，相期久不还。"],"theme":"寄赠酬答","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["秋","鸟","山"],"cats":{"抒情":["思念","孤独"],"四季":["秋天"],"山水":["庐山"]},"theme_conf":0.56},{"uid":"8e6ba3fd-d983-4950-9fec-8e55331d0c09","title":"海上诗送薛文学归海东","author":"刘眘虚","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["何处归且远，送君东悠悠。","沧溟千万里，日夜一孤舟。","旷望绝国所，微茫天际愁。","有时近仙境，不定若梦游。","或见青色古，孤山百里秋。","前心方杳眇，后路劳夷犹。","离别惜吾道，风波敬皇休。","春浮花气远，思逐海水流。","日暮骊歌后，永怀空沧洲。"],"theme":"送别","theme2":[],"style":"豪放","style2":["沉郁","冲淡"],"mood":"孤寂","mood2":["相思","愁怨"],"scene":["舟","秋","春","夜"],"cats":{"抒情":["离别","伤感","孤独"],"四季":["春天","秋天"],"山水":["西湖"]},"theme_conf":0.66},{"uid":"3fe183cd-7771-4bb4-81d1-0d3ee507c647","title":"观拔河俗戏","author":"明皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["壮徒恒贾勇，拔拒抵长河。","欲练英雄志，须明胜负多。","噪齐山岌嶪，气作水腾波。","预期年岁稔，先此乐时和。"],"theme":"咏史怀古","theme2":[],"style":"雄浑","style2":["豪放"],"mood":"慷慨","mood2":["欢愉"],"scene":["山"],"cats":{"抒情":["怀古"],"山水":["江河"]},"theme_conf":0.65},{"uid":"80b9bf77-80cf-41a1-8278-5e5b37dd5b3b","title":"郊庙歌辞 封泰山乐章 豫和 一","author":"张说","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["款泰坛，柴泰清。","受天命，报天成。","竦皇心，荐乐声。","志上达，歌下迎。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"山水":["泰山"]},"theme_conf":1.0},{"uid":"1e63f4cf-a078-44df-814f-8bea0929e526","title":"题僊游寺","author":"朱庆余","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["石抱龙堂藓石干，山遮白日寺门寒。","长松瀑布饶奇状，曾有仙人驻鹤看。"],"theme":"哲理悟道","theme2":[],"style":"幽峭","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"山水":["瀑布"]},"theme_conf":0.661},{"uid":"f51694bd-8955-4c4d-9ed6-673c2fbb5321","title":"太子李舍人城东别业与二三文友逃暑","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["下马失炎暑，重门深绿篁。","宫臣礼嘉客，林表开兰堂。","兹夕兴难尽，澄罍照墨塲。","鲜风吹印绶，密坐皆馨香。","美景惜文会，清吟迟羽觞。","东林晚来好，目极趣何长。","鸟道挂疎雨，人家残夕阳。","城隅拥归骑，留醉恋琼芳。"],"theme":"送别","theme2":["羁旅思乡"],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["夏"],"cats":{"抒情":["友情","离别","思乡"],"四季":["夏天"],"山水":["庐山"]},"theme_conf":0.585},{"uid":"d6d2ba3a-f3a7-479e-b4d7-705ef40659fc","title":"颍州从事西湖亭䜩饯","author":"许浑","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["西湖清宴不知回，一曲离歌酒一杯。","城带夕阳闻鼓角，寺临秋水见楼台。","兰堂客散蝉犹噪，桂檝人稀鸟自来。","独想征车过巩洛，此中霜菊遶潭开。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["江南","楼","秋","江"],"cats":{"抒情":["孤独"],"四季":["秋天"],"山水":["西湖"]},"theme_conf":0.688},{"uid":"4b70cf4d-91c2-4f35-88b6-27719132e234","title":"留别公安太易沙门","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["隐居欲就庐山远，丽藻初逢休上人。","数问舟航留制作，长开箧笥拟心神。","沙村白雪仍含冻，江县红梅已放春。","先蹋炉峰置兰若，徐飞锡杖出风尘。"],"theme":"送别","theme2":[],"style":"旷达","style2":[],"mood":"恬淡","mood2":[],"scene":["山","冬"],"cats":{"抒情":["离别"],"山水":["庐山"]},"theme_conf":0.433},{"uid":"2d69a74c-1dad-46c4-a6d8-78d56d12145d","title":"东郊纳凉忆左威卫李录事收昆季太原崔参军三首 二","author":"楼颕","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["纳凉每选地，近得青门东。","林与缭垣接，池将沁水通。","枝交帝女树，桥映美人虹。","想是忘机者，悠悠在兴中。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"相思","mood2":["恬淡"],"scene":[],"cats":{"抒情":["思念"],"山水":["庐山"],"人物":["女子"],"生活":["写桥"]},"theme_conf":0.695},{"uid":"cp3132bc43c19b92","title":"摸鱼儿","author":"刘辰翁","dynasty":"宋","section":"宋词","form":"词","paragraphs":["怎知他、春归何处，相逢且尽尊酒。","少年袅袅天涯恨，长结西湖烟柳。","休回首。","但细雨断桥，憔悴人归后。","东风似旧。","问前度桃花，刘郎能记，花复认郎否。","君且住，草草留君翦韭。","前宵更恁时候。","深杯欲共歌声滑，翻湿春衫半袖。","空眉皱。","看白发尊前，已似人人有。","临分把手。","叹一笑论文，清狂顾曲，此会几时又。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":["旷达","豪放"],"mood":"愁怨","mood2":[],"scene":["春","雨","酒","夜","江南"],"cats":{"抒情":["思乡"],"四季":["春天"],"山水":["西湖"],"天气":["写雨"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"269e39c7-8e54-43de-bad4-86909285f911","title":"寄献北都留守裴令公","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["天上中台正，人间一品高。","休明值尧舜，勋业过萧曹。","始擅文三捷，终兼武六韬。","动人名赫赫，忧国意忉忉。","荡蔡擒封豕，平齐斩巨鼇。","两河收土宇，四海定波涛。","宠重移宫籥，恩新换阃旄。","保厘东宅静，守护北门牢。","晋国封疆阔，幷州士马豪。","胡兵惊赤帜，边雁避乌号。","令下流如水，仁沾泽似膏。","路喧歌五袴，军醉感单醪。","将校森貔武，宾僚俨隽髦。","客无烦夜柝，吏不犯秋毫。","神在台骀助，魂亡猃狁逃。","德星销彗孛，霖雨灭腥臊。","烽戍高临代，关河远控洮。","汾云晴漠漠，朔吹冷𩙫𩙫。","豹尾交牙戟，蚪须捧佩刀。","通天白犀带，照地紫麟袍。","羌管吹杨柳，燕姬酌蒲萄。","银含凿落醆，金屑琵琶槽。","遥想从军乐，应忘报国劳。","紫微留北阙，绿野寄东臯。","忽忆前时会，多慙下客叨。","清宵陪䜩话，美景从游遨。","花月还同赏，琴诗雅自操。","朱弦拂宫征，洪笔振风骚。","近竹开方丈，依林架桔槔。","春池八九曲，画舫两三艘。","径滑苔黏屐，潭深水没篙。","绿丝萦岸柳，红粉映楼桃。","为穆先陈醴，招刘共藉糟。","舞鬟金翡翠，歌颈玉蛴螬。","盛德终难过，明时岂易遭。","公虽慕张范，帝未舍伊臯。","眷恋心方结，踟蹰首已搔。","鸾皇上寥廓，燕雀任蓬蒿。","欲献文狂简，徒烦思郁陶。","可怜四百字，轻重抵鸿毛。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":["清新","豪放"],"mood":"欢愉","mood2":["相思","慷慨"],"scene":["雨","酒","夜","鸟","楼"],"cats":{"抒情":["思念","爱国"],"山水":["黄河"]},"theme_conf":0.451},{"uid":"38438036-586a-47f6-a4c0-d75bc30801c0","title":"相和歌辞 从军行二首 一","author":"虞世南","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["涂山烽候惊，弭节度龙城。","冀马楼兰将，燕犀上谷兵。","劒寒花不落，弓晓月逾明。","凛凛严霜节，冰壮黄河绝。","蔽日卷征蓬，浮天散飞雪。","全兵值月满，精骑乘胶折。","结发早驱驰，辛苦事旌麾。","马冻重关冷，轮摧九折危。","独有西山将，年年属数奇。"],"theme":"边塞征战","theme2":[],"style":"幽峭","style2":["清新"],"mood":"孤寂","mood2":["慷慨"],"scene":["雪","冬","江"],"cats":{"抒情":["孤独"],"山水":["黄河"],"天气":["写雪"],"生活":["边塞"]},"theme_conf":0.776},{"uid":"8036c622-e19b-454b-be17-d5fd4f9ec789","title":"江畔独步寻花七绝句 三","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["江深竹静两三家，多事红花映白花。","报答春光知有处，应须美酒送生涯。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["江","花"],"cats":{"抒情":["孤独","感恩"],"山水":["江河"]},"theme_conf":0.703},{"uid":"2bdc4aa6-9b3f-4243-9d45-825d13267797","title":"登玉山诸峰偶至悟真寺","author":"钱起","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["郭南云水佳，讼简野情发。","紫芝每相引，黄绶不能𫄬。","稍入石门幽，始知灵境绝。","冥搜未寸晷，仙迳俄九折。","蟠木盖石梁，崩岸露云穴。","数峰拔昆仑，秀色与空澈。","玉气交晴虹，桂花留曙月。","半岩采珉者，一点如片雪。","真赏无前程，奇观宁暂辍。","更闻东林磬，可听不可说。","兴中寻觉化，寂尔诸象灭。"],"theme":"山水田园","theme2":["山水田园"],"style":"绮丽","style2":["冲淡","幽峭"],"mood":"孤寂","mood2":["欢愉"],"scene":["山"],"cats":{"山水":["庐山"],"人生":["哲理"]},"theme_conf":0.72},{"uid":"888fd3d3-d777-401d-8b4a-e94d3ab3607f","title":"横吹曲辞 入塞曲 二","author":"沈彬","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["苦战沙间卧箭痕，戍楼闲上望星文。","生希国泽分偏将，死夺河源荅圣君。","鸢覰败兵眠白草，马惊边鬼哭阴云。","功多地远无人纪，汉阁笙歌日又曛。"],"theme":"边塞征战","theme2":[],"style":"幽峭","style2":["沉郁"],"mood":"悲怆","mood2":[],"scene":["塞外","楼"],"cats":{"山水":["黄河"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.877},{"uid":"92dd65da-8301-4c83-b8f3-986b6095c481","title":"征怨","author":"柳中庸","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["岁岁金河复玉关，朝朝马策与刀环。","三春白雪归青冢，万里黄河遶黑山。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":["豪放"],"mood":"愁怨","mood2":[],"scene":["江","雪","春","山"],"cats":{"四季":["春天"],"山水":["黄河"]},"theme_conf":0.71},{"uid":"29ad430b-4f67-43c7-bbd2-0a7020e2a9aa","title":"和段校书冬夕寄题庐山","author":"刘得仁","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["名高身未到，此恨蓄多时。","是夕吟因话，他年必去随。","尝闻庐岳顶，半入楚江湄。","几处悬崖上，千寻瀑布垂。","炉峰松淅沥，湓浦柳参差。","日色连湖白，钟声拂浪迟。","烟梯缘薜荔，岳寺步欹危。","地本饶灵草，林曾出祖师。","石楼霞耀壁，猨树鹤分枝。","细径萦岩末，高窗见海涯。","嵌空寒更极，寂寞夜尤思。","阴谷冰埋术，仙田雪覆芝。","乱泉禅客濑，异迹逸人知。","藓室新开灶，柽潭末了棋。","如何遂闲放，长得在希夷。","空务渔樵事，方无道路悲。","谢公台尚在，陶令柳潜衰。","尘外难相许，人间贵迹遗。","虽怀丹桂影，不忘白云期。","仁者终携手，今朝预赋诗。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["山","冬"],"cats":{"抒情":["孤独"],"四季":["冬天"],"山水":["庐山","瀑布"]},"theme_conf":0.381},{"uid":"92f47c36-d77a-4ab5-b5df-893d6ea09e28","title":"赋得白云起封中","author":"李正辞","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["千年泰山顶，云起汉皇封。","不作奇峰状，宁分触石容。","为霖虽易得，表圣自难逢。","冉冉排空上，依依叠影重。","素光非曳练，灵贶是从龙。","岂学无心出，东西任所从。"],"theme":"咏物","theme2":[],"style":"冲淡","style2":["幽峭"],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"山水":["泰山"],"天气":["写云"]},"theme_conf":0.648},{"uid":"e1264668-8b25-4c5a-9260-904b20979589","title":"鼓吹曲辞 鼓吹铙歌 河右平","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["河右澶漫，顽为之魁。","王师如雷震，昆仑以颓。","上聋下聪，骜不可回。","助雠抗有德，惟人之灾。","乃溃乃奋，执缚归厥命。","万室蒙其仁，一夫则病。","濡以鸿泽，皇之圣。","威畏德怀，功以定。","顺之于理，物咸遂厥性。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"山水":["江河"]},"theme_conf":1.0},{"uid":"23818817-a8c2-4a52-a995-0f84dd5b548e","title":"送敭法师","author":"贾岛","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["度岁不相见，严冬始出关。","孤烟寒色树，高雪夕阳山。","瀑布寺应到，牡丹房甚闲。","南朝遗迹在，此去几时还。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["冬","雪"],"cats":{"抒情":["孤独"],"四季":["冬天"],"山水":["瀑布"]},"theme_conf":0.616},{"uid":"b298777c-4db6-424c-b441-e4051bf7ecc9","title":"春日叶秀才曲江","author":"罗隐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["江花江草暖相隈，也向江边把酒杯。","春色恼人遮不得，别愁如疟避还来。","安排贱迹无良策，裨补明时望重才。","一曲吴歌齐拍手，十年尘眼未曾开。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["春","江","酒"],"cats":{"抒情":["伤感"],"四季":["春天"],"山水":["江河"],"植物":["叶子"]},"theme_conf":1.0},{"uid":"a28d04d1-9f9b-492e-8f1f-2d70542ffa27","title":"酬叶县刘明府避地庐山言怀诒郑录事昆季苟尊师兼见赠之","author":"吴筠","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["明哲良罕遇，遇君輙思齐。","挺生著天爵，自可析人珪。","河洛初沸腾，方期扫虹霓。","时命竟未合，安能亲鼓鼙。","从此罢飞凫，投簪辞割鸡。","驱车适南土，忠孝两不暌。","庐岳镇江介，于焉惬林栖。","入门披彩服，出谷杖红藜。","隐令旧闾里，而今复成跻。","郑公解簪绂，华萼曜松谿。","贤哉苟征君，灭迹为圃畦。","顾已成非薄，忝兹忘筌蹄。","相观对绿樽，逸思凌丹梯。","道泰我长往，时清君勿迷。","王孙且无归，芳草正萋萋。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["山","花"],"cats":{"山水":["庐山"],"天气":["彩虹"],"植物":["叶子"]},"theme_conf":0.96},{"uid":"f4bc9ca4-dab8-40de-b76c-29ab3e6640e7","title":"唐封泰山乐章 豫和","author":"张说","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["礼乐终，[烟]燎上。","怀灵惠，结皇想。","归风疾，回风爽。","百[福]来，众神往。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"山水":["泰山"]},"theme_conf":1.0},{"uid":"ef36b0a2-6327-47a2-b777-ccf669af3ebb","title":"大历三年春白帝城放船出瞿塘峡久居夔府将适江陵漂泊有诗凡四十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["老向巴人里，今辞楚塞隅。","入舟飜不乐，解缆独长吁。","窄转深啼狖，虚随乱浴凫。","石苔凌几杖，空翠扑肌肤。","叠壁排霜劒，奔泉溅水珠。","杳冥藤上下，浓澹树荣枯。","神女峰娟妙，昭君宅有无。","曲留明怨惜，梦尽失欢娱。","摆阖盘涡沸，欹斜激浪输。","风雷缠地脉，冰雪耀天衢。","鹿角真走险，狼头如跋胡。","恶滩宁变色，高卧负微躯。","书史全倾挠，装囊半压濡。","生涯临臬兀，死地脱斯须。","不有平川决，焉知众壑趋。","乾坤霾涨海，雨露洗春芜。","欧鸟牵丝飏，骊龙濯锦纡。","落霞沈绿绮，残月坏金枢。","泥笋苞初荻，沙茸出小蒲。","雁儿争水马，燕子逐樯乌。","绝岛容烟雾，环洲纳晓晡。","前闻辨陶牧，转眄拂宜都。","县郭南畿好，津亭北望孤。","劳心依憩息，朗咏划昭苏。","意遣乐还笑，衰迷贤与愚。","飘萧将素发，汩没听洪𬬻。","丘壑曾忘返，文章敢自诬。","此生遭圣代，谁分哭穷途。","卧疾淹为客，蒙恩早厕儒。","廷争酬造化，朴直乞江湖。","滟滪险相迫，沧浪深可逾。","浮名寻已已，嬾计却区区。","喜近天皇寺，先披古画图。","应经帝子渚，同泣舜苍梧。","朝士兼戎服，君王按湛卢。","旄头初俶扰，鹑首丽泥涂。","甲卒身虽贵，书生道固殊。","出尘皆野鹤，历块匪辕驹。","伊吕终难降，韩彭不易呼。","五云高太甲，六月旷抟扶。","回首黎元病，争权将帅诛。","山林托疲苶，未必免崎岖。"],"theme":"羁旅思乡","theme2":["羁旅思乡","边塞征战"],"style":"绮丽","style2":["沉郁","清新"],"mood":"欢愉","mood2":["悲怆","孤寂"],"scene":["江","鸟","春","舟","山"],"cats":{"抒情":["思乡","孤独"],"四季":["春天"],"山水":["江河"],"天气":["写雪"],"生活":["边塞"]},"theme_conf":0.8},{"uid":"3383ff3c-b6bf-44b6-900a-766acc558644","title":"王兵马使二角鹰","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["悲台萧飒石巃嵸，哀壑杈枒浩呼汹。","中有万里之长江，回风滔日孤光动。","角鹰飜倒壮士臂，将军玉帐轩翠气。","二鹰猛脑徐侯穟，目如愁胡视天地。","杉鸡竹兔不自惜，溪虎野羊俱辟易。","鞲上锋棱十二翮，将军勇锐与之敌。","将军树勋起安西，昆仑虞泉入马蹄。","白羽曾肉三狻猊，敢决岂不与之齐。","荆南芮公得将军，亦如角鹰下翔云。","恶鸟飞飞啄金屋，安得尔辈开其群，驱出六合枭鸾分。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":["绮丽"],"mood":"悲怆","mood2":["慷慨"],"scene":["江"],"cats":{"抒情":["伤感"],"山水":["长江"],"人生":["战争"],"动物":["写马"]},"theme_conf":0.518},{"uid":"321a1b75-4cdf-48c7-8f57-047300fa7f50","title":"杂曲歌辞 水调 歌第一","author":"不详","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["平沙落日大荒西，陇上明星高复低。","孤山几处看烽火，壮士连营候鼓鼙。"],"theme":"边塞征战","theme2":["山水田园"],"style":"悲慨","style2":[],"mood":"孤寂","mood2":["慷慨"],"scene":["山"],"cats":{"抒情":["孤独"],"山水":["西湖"],"人生":["战争"]},"theme_conf":0.506},{"uid":"cb65a8de-23eb-4aa0-a490-61fb8e57f42a","title":"登湓城浦望庐山初晴直省赍敕催赴江阴","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["西望香炉雪，千峰晚色新。","白头悲作吏，黄纸苦催人。","多负登山屐，深藏漉酒巾。","伤心公府内，手板日相亲。"],"theme":"山水田园","theme2":["咏史怀古"],"style":"清新","style2":[],"mood":"悲怆","mood2":["相思"],"scene":["山"],"cats":{"抒情":["伤感","怀古"],"山水":["庐山"]},"theme_conf":0.562},{"uid":"c1e68d61-a599-4f76-9fab-3eb4b4780564","title":"漫歌八曲 大回中","author":"元结","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["樊水欲东流，大江又北来。","樊山当其南，此中为大回。","回中鱼好游，回中多钓舟。","漫欲作渔人，终焉无所求。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":["舟","江","山"],"cats":{"山水":["长江"]},"theme_conf":1.0},{"uid":"08a8ab7b-fb84-4a05-8b4e-177f2728bdbf","title":"和浙西李大夫晚下北固山喜径松成阴怅然怀古偶题临江亭幷浙东元相公所和依本韵","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["一辞温室树，几见武昌柳。","荀谢年何少，韦平望已久。","种松夹石道，纡组临沙阜。","目览帝王州，心存股肱守。","叶动惊彩翰，波澄见頳首。","晋宋齐梁都，千山万江口。","烟散隋宫出，涛来海门吼。","风俗太伯余，衣冠永嘉后。","江长天作限，山固壤无朽。","自古称佳丽，非贤谁奄有。","八元邦族盛，万石门风厚。","天柱揭东溟，文星照北斗。","高亭一骋望，举酒共为寿。","因赋咏怀诗，远寄同心友。","禁中晨夜直，江左东西偶。","将手握兵符，儒腰盘贵绶。","颁条风有自，立事言无苟。","农野闻让耕，军人不使酒。","用材当构厦，知道宁窥牖。","谁谓青云高，鹏飞终背负。"],"theme":"咏史怀古","theme2":["山水田园"],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["江","山","楼"],"cats":{"抒情":["怀古"],"山水":["江河"],"天气":["星星"],"人生":["梦想"]},"theme_conf":0.383},{"uid":"da254237-36a9-4eec-b44c-47058833c411","title":"山亭怀古","author":"张弘靖","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["丛石依古城，悬泉洒清池。","高低袤丈内，衡霍相蔽亏。","归田竟何因，为郡岂所宜。","谁能辨人野，寄适聊在斯。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"惆怅","mood2":[],"scene":["山","楼"],"cats":{"抒情":["怀古"],"山水":["瀑布"]},"theme_conf":0.595},{"uid":"a8ffe7a3-5f14-43c9-b22e-28eea904da02","title":"天门街西观荣王聘妃","author":"张光朝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["仙媛来朱邸，名山出紫微。","三周初展义，百两遂言归。","郑国通梁苑，天津接帝畿。","桥成乌鹊助，盖转凤皇飞。","霜仗迎秋色，星缸满夜辉。","从兹磐石固，应为得贤妃。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"山水":["泰山"],"生活":["写桥"]},"theme_conf":0.65},{"uid":"0613f575-4f07-4326-8591-603fb3d1da45","title":"秦中感秋寄远上人","author":"孟浩然","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["一丘常欲卧，三径苦无资。","北土非吾愿，东林怀我师。","黄金然桂尽，壮志逐年衰。","日夕凉风至，闻蝉但益悲。"],"theme":"寄赠酬答","theme2":["闲适隐逸"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["慷慨"],"scene":["秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"山水":["庐山"],"人生":["励志","梦想"]},"theme_conf":0.82},{"uid":"edf798b9-3594-4320-bcbd-dfd9f6ef22b6","title":"独孤中丞筵陪饯韦君赴升州","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["中司龙节贵，上客虎符新。","地控吴襟带，才高汉缙绅。","泛舟应度腊，入境便行春。","处处歌来暮，长江建业人。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["江"],"cats":{"抒情":["孤独"],"山水":["长江"]},"theme_conf":0.704},{"uid":"6aad28c5-dded-4c0c-884f-1c21d25854ef","title":"黄河二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["黄河北岸海西军，椎鼓鸣钟天下闻。","铁马长鸣不知数，胡人高鼻动成群。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["江"],"cats":{"山水":["江河","黄河"]},"theme_conf":1.0},{"uid":"877224c7-59e3-4b74-898e-8ccc947b4be6","title":"送田卓入华山","author":"贾岛","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["幽深足暮蝉，惊觉石床眠。","瀑布五千仞，草堂瀑布边。","坛松涓滴露，岳月泬寥天。","鹤过君须看，上头应有仙。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["山","月"],"cats":{"山水":["瀑布"]},"theme_conf":0.71},{"uid":"b3b95e77-5985-49ef-b603-cce95a5c6ae2","title":"杂曲歌辞 春江曲","author":"郭元振","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["江水春沈沈，上有双竹林。","竹叶坏水色，郎亦坏人心。"],"theme":"山水田园","theme2":["爱情相思"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春","江"],"cats":{"四季":["春天"],"山水":["江河"]},"theme_conf":0.511},{"uid":"0e12fbf7-ae7c-4b70-83b4-d442fe1b23da","title":"郊庙歌辞 封泰山乐章 豫和 六","author":"张说","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["飨帝飨亲，维孝维圣。","缉熙懿德，敷扬成命。","华夷志同，笙镛礼盛。","明灵降止，感此诚敬。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"山水":["泰山"]},"theme_conf":1.0},{"uid":"f889634b-508b-4a3a-9557-b64733de3b45","title":"奉和过旧宅应制","author":"上官仪","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["石关清晚夏，璇舆御早秋。","神麾飏珠雨，仙吹响飞流。","沛水祥云泛，宛郊瑞气浮。","大风迎汉筑，藂烟入舜球。","翠梧临凤邸，滋兰带鹤舟。","偃伯歌玄化，扈跸颂王游。","遗簪谬昭奖，珥笔荷恩休。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":["清新"],"mood":"欢愉","mood2":[],"scene":["夏","秋","舟"],"cats":{"四季":["夏天","秋天"],"山水":["瀑布"]},"theme_conf":0.98},{"uid":"27db32d1-c747-4c6d-a937-4091287b6622","title":"灵门寺赠灵一上人","author":"朱放","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["所思劳旦夕，惆怅去湘东。","禅客知何在，春山几处同。","独行残雪里，相见暮云中。","请住东林寺，弥年事远公。"],"theme":"寄赠酬答","theme2":["送别"],"style":"沉郁","style2":[],"mood":"惆怅","mood2":["孤寂"],"scene":["雪","春","山"],"cats":{"抒情":["孤独"],"四季":["春天"],"山水":["庐山"]},"theme_conf":0.88},{"uid":"8551389a-8251-4516-80e0-9247893493ca","title":"乌江女","author":"屈同仙","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["越艳谁家女，朝游江岸傍。","青春犹未嫁，红粉旧来娼。","锦袖盛朱橘，银钩摘紫房。","见人羞不语，回艇入溪藏。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["江"],"cats":{"山水":["江河"],"人生":["青春"]},"theme_conf":1.0},{"uid":"77a60918-aade-46c7-92f5-744c1f6d025c","title":"送人赴举","author":"郑巢","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["篇章动玉京，坠叶满前程。","旧国与僧别，秋江罢钓行。","马过隋代寺，樯出楚山城。","应近嵩阳宿，潜闻瀑布声。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["秋","江","山"],"cats":{"四季":["秋天"],"山水":["瀑布"]},"theme_conf":0.613},{"uid":"1a75c701-e7ec-453d-97dd-ba70181e07b5","title":"送杜秀才归桂林","author":"许浑","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["桂州南去与谁同，处处山连水自通。","两岸晓霞千里草，半帆斜日一江风。","瘴雨欲来枫树黑，火云初起荔枝红。","愁君路远销年月，莫滞三湘五岭中。"],"theme":"送别","theme2":["山水田园"],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["月","山"],"cats":{"抒情":["伤感"],"山水":["江河"],"食物":["荔枝"]},"theme_conf":0.632},{"uid":"f613e665-0ed5-449e-9f4f-e094a102f993","title":"九曲词三首 二","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["万骑争歌杨柳春，千塲对舞绣骐𬴊。","到处尽逢欢洽事，相看总是太平人。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"山水":["黄河"]},"theme_conf":0.65},{"uid":"5fe01760-2d47-4df6-b61d-518cf952af9d","title":"相和歌辞 公无渡河","author":"王叡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["浊波洋洋兮凝晓雾，公无渡河兮公苦渡。","风号水激兮呼不闻，提壶看入兮中流去。","浪摆衣裳兮随步没，沈尸深入兮蛟螭窟。","蛟螭尽醉兮君血干，推出黄沙兮泛君骨。","当时君死妾何适？遂就波澜合魂魄。","愿持精卫衔石心，穷取河源塞泉脉。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"悲怆","mood2":[],"scene":["酒","塞外"],"cats":{"山水":["江河","黄河"],"生活":["边塞"]},"theme_conf":0.431},{"uid":"a07e44fe-2a73-40af-a53a-e735eb124928","title":"宿悬泉驿","author":"贾岛","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["晓行沥水楼，暮到悬泉驿。","林月值云遮，山灯照愁寂。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["楼","月","山"],"cats":{"抒情":["思乡","伤感"],"山水":["瀑布"]},"theme_conf":0.524},{"uid":"6dceb62b-832f-40d9-8055-2d12282d781c","title":"自淇涉黄河途中作十三首 三","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["野人头尽白，与我忽相访。","手持青竹竿，日暮淇水上。","虽老美容色，虽贫亦闲放。","钓鱼三十年，中心无所向。"],"theme":"闲适隐逸","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"恬淡","mood2":[],"scene":["江"],"cats":{"山水":["黄河"]},"theme_conf":0.82},{"uid":"0b4365f7-5f12-44bf-aef1-b30e2762fe41","title":"题云际寺暕上人故院","author":"李端","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["白发怱怱色，青山草草心。","远公仍下世，从此别东林。"],"theme":"哲理悟道","theme2":["送别"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["园林"],"cats":{"山水":["庐山"]},"theme_conf":0.486},{"uid":"09d9d2b1-e2a0-499c-a673-bd9f9333a435","title":"酬栢侍御闻与韦处士同游灵台寺见寄","author":"王建","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["西域传中说，灵台属雍州。","有泉皆圣迹，有石皆佛头。","所出薝卜香，外国俗来求。","毒蛇护其下，樵者不可偷。","古碑在云巅，备载置寺由。","魏家移下来，后人始增修。","近与韦处士，爱此山之幽。","各自具所须，竹笼盛茶瓯。","牵马过危栈，襞衣涉奔流。","草开平路尽，林下大石稠。","过郭转经峰，忽见东西楼。","瀑布当寺门，逬落衣裳秋。","石苔铺紫花，溪叶裁碧油。","松根载殿高，飘飖仙山浮。","县中贤大夫，一月前此游。","赛神贺得雨，岂暇多停留。","二十韵新诗，远寄寻山俦。","清冷玉涧泣，冷切石磬愁。","君名高难闲，余身愚终休。","相将长无因，从今生离忧。"],"theme":"寄赠酬答","theme2":["送别"],"style":"幽峭","style2":[],"mood":"愁怨","mood2":[],"scene":["楼","山"],"cats":{"抒情":["伤感"],"山水":["瀑布"]},"theme_conf":0.85},{"uid":"46c03530-4479-4300-a884-aa4c01ea91a2","title":"招孟武昌","author":"元结","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["风霜枯万物，退谷如春时。","穷冬涸江海，桮湖澄清漪。","湖尽到谷口，单船近堦墀。","湖中更何好，坐见大江水。","欹石为水涯，半山在湖里。","谷口更何好，绝壑流寒泉。","松桂荫茅舍，白云生坐边。","武昌不干进，武昌人不厌。","退谷正可游，桮湖任来泛。","湖上有水鸟，见人不飞鸣。","谷口有山兽，往往随人行。","莫将车马来，令我鸟兽惊。"],"theme":"山水田园","theme2":[],"style":"清新","style2":["旷达"],"mood":"孤寂","mood2":[],"scene":["江","山","冬"],"cats":{"四季":["冬天"],"山水":["长江"]},"theme_conf":1.0},{"uid":"5641758a-d34f-4d86-8631-5f0b17869fc3","title":"相和歌辞 江南曲八首 四","author":"刘希夷","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["皓如楚江月，霭若吴岫云。","波中自皎镜，山上亦氛氲。","明月留照妾，轻云持赠君。","山川各离散，光气乃殊分。","天涯一为别，江北自相闻。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["江南","江","月"],"cats":{"抒情":["离别"],"山水":["江河"],"天气":["月亮"]},"theme_conf":0.94},{"uid":"aeb28c6b-8831-4018-a16a-7434ecf48df2","title":"送头陀上人赴庐山寺","author":"郑常","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["僧家无住著，早晚出东林。","得道非真相，头陀是苦心。","持斋山果熟，倚锡野云深。","溪寺谁相待，香花与梵音。"],"theme":"送别","theme2":["送别","山水田园"],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"山水":["庐山"]},"theme_conf":0.78},{"uid":"823ebceb-6848-442c-918e-5cbfe2a70f93","title":"浔阳三题 东林寺白莲","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["东林北塘水，湛湛见底清。","中生白芙蓉，菡萏三百茎。","白日发光彩，清飙散芳馨。","泄香银囊破，泻露玉盘倾。","我慙尘垢眼，见此琼瑶英。","乃知红莲花，虚得清净名。","夏萼敷未歇，秋房结才成。","夜深众僧寝，独起绕池行。","欲收一颗子，寄向长安城。","但恐出山去，人间种不生。"],"theme":"咏物","theme2":[],"style":"清新","style2":["绮丽"],"mood":"孤寂","mood2":[],"scene":["花"],"cats":{"抒情":["孤独"],"山水":["庐山"],"植物":["荷花"]},"theme_conf":0.94},{"uid":"17cc0659-dfef-47e7-a538-bd689b2b8c2b","title":"题邵公禅院","author":"刘得仁","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["无事门多掩，阴阶竹扫苔。","劲风吹雪聚，渴鸟啄冰开。","树向寒山得，人从瀑布来。","终期天目老，擎锡逐云回。"],"theme":"哲理悟道","theme2":["山水田园"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["园林","冬","雪"],"cats":{"山水":["瀑布"],"人生":["哲理"]},"theme_conf":0.63},{"uid":"7a3afe60-f683-4e4f-a11d-ecfd38c7dc98","title":"送客一归襄阳二归浔阳","author":"韩翃","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["南驱匹马会心期，东望扁舟惬梦思。","熨斗山前春色早，香炉峰顶暮烟时。","空林欲访庞居士，古寺应怀远法师。","两地由来堪取兴，三贤他日幸留诗。"],"theme":"羁旅思乡","theme2":["送别"],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["舟","山"],"cats":{"抒情":["思乡"],"山水":["庐山"]},"theme_conf":0.413},{"uid":"81b32160-4eaa-4765-8824-ef33e4ae353e","title":"赠道者","author":"朱庆余","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["独住神仙境，门当瀑布开。","地多临水石，行不惹尘埃。","风起松花散，琴鸣鹤翅回。","还归九天上，时有故人来。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":[],"cats":{"抒情":["友情","孤独"],"山水":["瀑布"]},"theme_conf":0.88},{"uid":"cp6c3b8276f269f5","title":"采桑子","author":"欧阳修","dynasty":"宋","section":"宋词","form":"词","paragraphs":["群芳过后西湖好，狼籍残红。","飞絮蒙蒙。","垂柳阑干尽日风。","笙歌散尽游人去，始觉春空。","垂下帘栊。","双燕归来细雨中。"],"theme":"山水田园","theme2":[],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["雨","江南"],"cats":{"山水":["西湖"],"天气":["写雨"]},"theme_conf":1.0},{"uid":"9f180d24-de06-4b4b-b98f-67aca6d65beb","title":"寄华州崔中丞","author":"姚合","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["莲华峰下郡，僊洞亦难胜。","闾里苍苔水，虚空瀑布冰。","酒香和药熟，山峭过云登。","清净黎人泰，唯忧急诏征。"],"theme":"寄赠酬答","theme2":["山水田园","应制干谒"],"style":"幽峭","style2":[],"mood":"愁怨","mood2":[],"scene":["山","酒"],"cats":{"山水":["瀑布"]},"theme_conf":0.79},{"uid":"dfcaab39-5c64-4eba-911e-2dec1cedc259","title":"送陵州路使君赴任","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["王室比多难，高官皆武臣。","幽燕通使者，岳牧用词人。","国待贤良急，君当拔擢新。","佩刀成气象，行盖出风尘。","战伐乾坤破，疮痍府库贫。","众僚宜洁白，万役但平均。","霄汉瞻佳士，泥途任此身。","秋天正摇落，回首大江滨。"],"theme":"送别","theme2":[],"style":"旷达","style2":["清新"],"mood":"惆怅","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"山水":["长江"]},"theme_conf":0.616},{"uid":"6bd61d48-95a3-4505-a201-27a22d06f17a","title":"郊庙歌辞 封泰山乐章 雍和","author":"张说","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["俎豆有馥，粢盛洁丰。","亦有和羹，既戒既平。","钟鼓管磬，肃唱和鸣。","皇皇后祖，来我思成。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"山水":["泰山"]},"theme_conf":1.0},{"uid":"0b94137b-109a-4e54-b5e6-016650363115","title":"寓言","author":"韦庄","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["黄金日日销还铸，僊桂年年折又生。","兔走乌飞如未息，路尘终见泰山平。"],"theme":"讽喻刺世","theme2":[],"style":"悲慨","style2":[],"mood":"愁怨","mood2":[],"scene":["山"],"cats":{"山水":["泰山"]},"theme_conf":0.65},{"uid":"0732a1c2-259d-451e-b11e-11344d0ed7ce","title":"登庐山峰顶寺","author":"刘眘虚","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["孤峰临万象，秋气何高清。","天际南郡出，林端西江明。","山门二缁叟，振锡闻幽声。","心照有无界，业悬前后生。","虽知真机静，尚与爱网幷。","方首金门路，未遑参道情。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["山"],"cats":{"抒情":["孤独"],"山水":["庐山"]},"theme_conf":0.538},{"uid":"346fa139-195f-40dc-b3e2-3758a5dd01ff","title":"庐山歌送至弘法师兼呈薛江州","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["释子去兮访名山，禅舟容与兮住仍前。","猿啾啾兮怨月，江渺渺兮多烟。","东林西林兮入何处，上方下方兮通石路。","连湘接楚饶桂花，事久年深无杏树。","使君爱人兼爱山，时引双旌万木间。","政成人野皆不扰，遂令法侣性安闲。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"恬淡","mood2":["愁怨"],"scene":["山","江"],"cats":{"山水":["庐山","江河"]},"theme_conf":0.46},{"uid":"1669d597-4c37-4897-b5f8-a15eedd8cdf0","title":"经河上公庙","author":"明皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["昔闻有耆叟，河上独遗荣。","迹与尘嚻隔，心将道德幷。","讵以天地累，宁为宠辱惊。","矫然翔寥廓，如何屈坚贞。","玄玄妙门启，肃肃祠宇清。","冥漠无先后，那能纪姓名。"],"theme":"咏史怀古","theme2":[],"style":"雄浑","style2":[],"mood":"孤寂","mood2":[],"scene":["塞外"],"cats":{"抒情":["孤独","怀古"],"山水":["江河"]},"theme_conf":0.65},{"uid":"03ab8d68-3b2a-4180-8592-cd523ee54570","title":"相和歌辞 猛虎行","author":"李贺","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["长戈莫舂，彊弩莫烹。","乳孙哺子，教得生狞。","举头为城，掉尾为旌。","东海黄公，愁见夜行。","道逢驺虞，牛哀不平。","生何用尺刀，壁上雷鸣。","泰山之下，妇人哭声。","官家有程，吏不敢听。"],"theme":"边塞征战","theme2":["悼亡挽歌","羁旅思乡"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["山"],"cats":{"抒情":["思乡","伤感","悼亡"],"山水":["泰山"]},"theme_conf":0.408},{"uid":"e9632216-d53c-4548-9fd7-da40dabefaba","title":"湖口望庐山瀑布泉","author":"张九龄","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["万丈洪泉落，迢迢半紫氛。","奔飞流杂树，洒落出重云。","日照虹蜺似，天清风雨闻。","灵山多秀色，空水共氤氲。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"山水":["庐山","瀑布"]},"theme_conf":1.0},{"uid":"6b78aaf7-4de0-4fc2-a524-8eaa6e66a244","title":"题清源寺","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["儒墨兼宗道，云泉隐旧庐。","盂城今寂寞，辋水自纡余。","内学销多累，西林易故居。","深房春竹老，细雨夜钟疎。","陈迹留金地，遗文在石渠。","不知登座客，谁得蔡邕书。"],"theme":"山水田园","theme2":["哲理悟道"],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["雨"],"cats":{"抒情":["孤独"],"山水":["庐山"],"天气":["写雨"]},"theme_conf":0.563},{"uid":"cp8a42437795a11b","title":"高阳台","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["宫粉雕痕，仙云堕影，无人野水荒湾。","古石埋香，金沙锁骨连环。","南楼不恨吹横笛，恨晓风、千里关山。","半飘零，庭上黄昏，月冷阑干。","寿阳空理愁鸾。","问谁调玉髓，暗补香瘢。","细雨归鸿，孤山无限春寒。","离魂难倩招清些，梦缟衣、解佩溪边。","最愁人，啼鸟晴明，叶底青圆。"],"theme":"山水田园","theme2":["羁旅思乡","游仙梦幻"],"style":"沉郁","style2":["婉约","绮丽"],"mood":"孤寂","mood2":["愁怨"],"scene":["楼","雨"],"cats":{"抒情":["思乡","伤感","孤独"],"山水":["西湖"],"天气":["写雨"]},"theme_conf":0.378},{"uid":"a891ddeb-0dd1-486f-9ea1-54682101004c","title":"送陆侍御归淮南使府五韵","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["江左重诗篇，陆生名久传。","凤城来已熟，羊酪不嫌膻。","归路芙蓉府，离堂玳瑁筵。","泰山呈腊雪，隋柳布新年。","曾忝扬州荐，因君达短牋。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["山"],"cats":{"山水":["泰山"],"节日":["春节"]},"theme_conf":0.818},{"uid":"10cd87b1-fae0-4741-b32e-140d49041c4f","title":"江上送客游庐山","author":"张继","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["楚客自相送，沾裳春水边。","晚来风信好，并发上江船。","花映新林岸，云开瀑布泉。","惬心应在此，佳句向谁传。"],"theme":"送别","theme2":["羁旅思乡"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["山","江"],"cats":{"抒情":["思乡"],"山水":["庐山","江河","瀑布"]},"theme_conf":0.458},{"uid":"c348bc2e-f50d-436b-88b7-c198d63dacfc","title":"行路难三首 一","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["金樽清酒斗十千，玉盘珍羞直万钱。","停杯投筯不能食，拔劒四顾心茫然。","欲渡黄河冰塞川，将登太行雪满山。","闲来垂钓碧溪上，忽复乘舟梦日边。","行路难，行路难，多岐路，今安在。","长风破浪会有时，直挂云帆济沧海。"],"theme":"咏怀抒感","theme2":["山水田园","哲理悟道"],"style":"豪放","style2":["绮丽"],"mood":"恬淡","mood2":["慷慨","惆怅"],"scene":["酒"],"cats":{"山水":["黄河"],"人生":["励志"]},"theme_conf":0.95},{"uid":"6c3450f9-3313-4b37-a250-3a2a65ffc6ea","title":"杂曲歌辞 春江曲二首 一","author":"张仲素","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["家寄征江岸，征人几岁游。","不知潮水信，每日到沙头。"],"theme":"送别","theme2":["边塞征战"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["江","春"],"cats":{"四季":["春天"],"山水":["江河"]},"theme_conf":0.5},{"uid":"d43a4767-2240-44b7-8d5b-c2acdc689839","title":"黄鹤楼送孟浩然之广陵","author":"李白","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["故人西辞黄鹤楼，烟花三月下扬州。","孤帆远影碧山尽，唯见长江天际流。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["楼","江"],"cats":{"抒情":["友情","孤独"],"山水":["长江"],"动物":["写鸟"]},"theme_conf":0.73},{"uid":"19afaf8e-aaa5-4a06-9e92-5fc4cdecb40c","title":"相和歌辞 公无渡河","author":"温庭筠","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["黄河怒浪连天来，大响谹谹如殷雷。","龙伯驱风不敢上，百川喷雪高崔嵬。","二十五弦何太哀？请公勿渡立裴回。","下有狂蛟锯为尾，裂帆截櫂磨霜齿。","神锥凿石塞神潭，白马𫎺𧽼赤尘起。","公乎跃马扬玉鞭，灭没高蹄日千里。"],"theme":"咏物","theme2":["边塞征战"],"style":"豪放","style2":[],"mood":"悲怆","mood2":[],"scene":["江","塞外","雪","山","舟"],"cats":{"山水":["江河","黄河"],"生活":["边塞"]},"theme_conf":0.533},{"uid":"29d98345-e050-49c2-89cb-88dbdcd0af97","title":"相和歌辞 江南弄","author":"李贺","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["江中绿雾起凉波，天上叠𪩘红嵯峨。","水风浦云生老竹，渚瞑蒲帆如一幅。","鲈鱼千头酒百斛，酒中倒卧南山绿。","吴歈越吟未终曲，江上团团帖寒玉。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["江南","江"],"cats":{"山水":["江河"]},"theme_conf":1.0},{"uid":"64ab14be-6565-4ac9-aa39-4a9e40d92023","title":"病后游青龙寺","author":"李端","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["病来形貌秽，斋沫入东林。","境静闻神远，身羸向道深。","芭蕉高自折，荷叶大先沈。"],"theme":"哲理悟道","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"恬淡","mood2":[],"scene":[],"cats":{"山水":["庐山"]},"theme_conf":0.522},{"uid":"2247b3d2-8476-4f8a-be6e-d3f8276751d3","title":"忆杭州梅花因叙旧游寄萧协律","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["三年闲闷在余杭，曾为梅花醉几场。","伍相庙边繁似雪，孤山园里丽如妆。","蹋随游骑心长惜，折赠佳人手亦香。","赏自初开直至落，欢因小饮便成狂。","薛刘相次埋新垅，沈谢双飞出故乡。","歌伴酒徒零散尽，唯残头白老萧郎。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":["沉郁"],"mood":"欢愉","mood2":["相思","孤寂"],"scene":["花","冬","酒"],"cats":{"抒情":["思念","思乡","孤独"],"山水":["西湖"],"人物":["女子"],"植物":["梅花"]},"theme_conf":0.9},{"uid":"7569d663-805a-47fc-97ed-72d88c179880","title":"送右司薛员外赴处州","author":"姚合","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["怀中天子书，腰下使君鱼。","瀑布和云落，仙都与世疎。","远程兼水陆，半岁在舟车。","相送难相别，南风入夏初。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["夏","舟"],"cats":{"四季":["夏天"],"山水":["瀑布"]},"theme_conf":1.0},{"uid":"cp49b50543fc106f","title":"兰陵王","author":"刘辰翁","dynasty":"宋","section":"宋词","form":"词","paragraphs":["送春去。","春去人间无路。","秋千外、芳草连天，谁遣风沙暗南浦。","依依甚意绪。","漫忆海门飞絮。","乱鸦过，斗转城荒，不见来时试灯处。","春去。","最谁苦。","但箭雁沉边，梁燕无主。","杜鹃声里长门暮。","想玉树凋土，泪盘如露。","咸阳送客屡回顾。","斜日未能度。","春去。","尚来否。","正江令恨别，庾信愁赋。","苏堤尽日风和雨。","叹神游故国，花记前度。","人生流落，顾孺子，共夜雨。"],"theme":"送别","theme2":["咏史怀古"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["鸟"],"cats":{"抒情":["离别","思念","伤感","闺怨","怀古"],"山水":["西湖"]},"theme_conf":0.452},{"uid":"480d7d0b-277f-4ad9-9829-e32b45bca9a7","title":"上李常侍","author":"戎昱","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["旌旗晓过大江西，七校前驱万队齐。","千里政声人共喜，三军令肃马前嘶。","恩沾境内风初变，春入城阴柳渐低。","桃李不须令更种，早知门下旧成蹊。"],"theme":"边塞征战","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"山水":["长江"]},"theme_conf":1.0},{"uid":"70cfbaa0-6ea5-4a6a-a6ac-0e8bbfd8413c","title":"贻华阳柳少府","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["系马乔木间，问人野寺门。","柳侯披衣笑，见我颜色温。","竝坐石下堂，俛视大江奔。","火云洗月露，绝壁上朝暾。","自非晓相访，触热生病根。","南方六七月，出入异中原。","老少多暍死，汗逾水浆飜。","俊才得之子，筋力不辞烦。","指挥当世事，语及戎马存。","涕泪溅我裳，悲气排帝阍。","郁陶抱长策，义仗知者论。","吾衰卧江汉，但媿识玙璠。","文章一小技，于道未为尊。","起予幸斑白，因是托子孙。","俱客古信州，结庐依毁垣。","相去四五里，径微山叶繁。","时危挹佳士，况免军旅喧。","醉从赵女舞，歌鼓秦人盆。","子壮顾我伤，我驩兼泪痕。","余生如过鸟，故里今空邨。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["婉约"],"mood":"悲怆","mood2":["慷慨"],"scene":["月"],"cats":{"抒情":["思乡","伤感"],"山水":["长江"],"植物":["柳树"]},"theme_conf":0.708},{"uid":"410b6c68-3226-47ea-a83c-c93f648d5213","title":"安平公诗","author":"李商隐","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["丈人博陵王名家，怜我总角称才华。","华州留语晓至暮，高声喝吏放两衙。","明朝骑马出城外，送我习业南山阿。","仲子延岳年十六，面如白玉欹乌纱。","其弟炳章犹两丱，瑶林琼树含奇花。","陈留阮家诸侄秀，逦迤出拜何骈罗。","府中从事杜与李，麟角虎翅相过摩。","清词孤韵有歌响，击触钟磬鸣环珂。","三月石堤冻销释，东风开花满阳坡。","时禽得伴戏新木，其声尖咽如鸣梭。","公时载酒领从事，踊跃鞍马来相过。","仰看楼殿撮清汉，坐视世界如恒沙。","面热脚掉互登陟，青云表柱白云崖。","一百八句在贝叶，三十三天长雨花。","长者子来辄献盖，辟支佛去空留𫖇。","公时受诏镇东鲁，遣我草诏随车牙。","顾我下笔即千字，疑我读书倾五车。","呜嘑大贤苦不寿，时世方士无灵砂。","五月至止六月病，遽颓泰山惊逝波。","明年徒步吊京国，宅破子毁哀如何。","西风冲户卷素帐，隟光斜照旧燕窠。","古人常叹知己少，况我沦贱艰虞多。","如公之德世一二，岂得无泪如黄河。","沥胆咒愿天有眼，君子之泽方滂沱。"],"theme":"送别","theme2":["悼亡挽歌","民生疾苦"],"style":"沉郁","style2":["清新"],"mood":"孤寂","mood2":["愁怨","恬淡"],"scene":["山","江"],"cats":{"抒情":["友情","伤感","孤独","悼亡"],"山水":["泰山","黄河"],"天气":["写风"],"人生":["读书"]},"theme_conf":0.431},{"uid":"c9dd1e11-5396-498a-a228-9afeb720dc41","title":"春日江村五首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["迢递来三蜀，蹉跎有六年。","客身逢故旧，发兴自林泉。","过懒从衣结，频游任履穿。","藩篱无限景，恣意买江天。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["江","春"],"cats":{"四季":["春天"],"山水":["江河"],"生活":["乡村"]},"theme_conf":1.0},{"uid":"92f88db8-3548-4e2e-87f7-aa0aac87af2c","title":"汴河怀古二首 二","author":"皮日休","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["尽道隋亡为此河，至今千里赖通波。","若无水殿龙舟事，共禹论功不较多。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"惆怅","mood2":[],"scene":["端午","舟"],"cats":{"抒情":["怀古"],"山水":["江河"],"节日":["端午节"]},"theme_conf":1.0},{"uid":"a456cc8d-2cd1-41c9-9cc8-52163216510d","title":"西江上送渔父","author":"温庭筠","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["却逐严光向若耶，钓轮菱櫂寄年华。","三秋梅雨愁枫叶，一夜篷舟宿苇花。","不见水云应有梦，偶随鸥鹭便成家。","白苹风起楼船暮，江燕双双五两斜。"],"theme":"送别","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["相思"],"scene":["江","舟","秋"],"cats":{"抒情":["思念","伤感"],"四季":["秋天"],"山水":["江河"],"人物":["父亲"]},"theme_conf":0.443},{"uid":"3d26433c-a673-4094-8c83-cadb1b08412a","title":"登柳州城楼寄漳汀封连四州","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["城上高楼接大荒，海天愁思正茫茫。","惊风乱飐芙蓉水，密雨斜侵薜荔墙。","岭树重遮千里目，江流曲似九廻肠。","共来百越文身地，犹自音书滞一乡。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["楼","江"],"cats":{"抒情":["伤感"],"山水":["江河"],"植物":["柳树"]},"theme_conf":0.92},{"uid":"6a5f693e-7c8d-4c20-a1c3-bfec8a474e6f","title":"重别西湖","author":"李绅","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["浦边梅叶看凋落，波上双禽去寂寥。","吹管曲传花易失，织文机学羽难飘。","雪欺春早摧芳蕚，隼励秋深拂翠翘。","繁艳彩毛无处所，尽成愁叹别谿桥。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["江南","江"],"cats":{"抒情":["离别","伤感"],"山水":["西湖"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"7081981c-0e2b-4d64-b610-1cf2d95d5fbe","title":"句","author":"吴越王钱镠","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["须将一片地，付与有心人。","黄河信有澄清日，后代应难继此才。","传语龙王幷水府，钱塘借与筑钱城。"],"theme":"咏怀抒感","theme2":[],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["江","江南"],"cats":{"山水":["黄河"]},"theme_conf":0.75},{"uid":"01d61dfa-6c6e-421d-a5b3-c7db62f9d7fe","title":"题杭州孤山寺","author":"张祜","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["楼台耸碧岑，一径入湖心。","不雨山长润，无云水自阴。","断桥荒藓涩，空院落花深。","犹忆西窗月，钟声在北林。"],"theme":"山水田园","theme2":["哲理悟道"],"style":"沉郁","style2":["幽峭"],"mood":"孤寂","mood2":[],"scene":["山","楼"],"cats":{"抒情":["孤独"],"山水":["西湖"],"生活":["写桥"]},"theme_conf":0.56},{"uid":"5b7bdb65-ec29-4ebe-b698-19a2f60498df","title":"长江二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["浩浩终不息，乃知东极临。","众流归海意，万国奉君心。","色借潇湘阔，声驱滟滪深。","未辞添雾雨，接上遇衣襟。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["江"],"cats":{"山水":["长江"]},"theme_conf":0.65},{"uid":"c0616c55-b4a7-45f5-a73c-76e59fe5c4d7","title":"续古二十九首 十","author":"陈陶","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["周穆恣游幸，横天驱八龙。","宁知泰山下，日日望登封。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["山"],"cats":{"抒情":["怀古"],"山水":["泰山"]},"theme_conf":0.95},{"uid":"bfb6764d-41ce-4929-946c-2bce0573be04","title":"和韦承庆过义阳公主山池五首 四","author":"杜审言","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["攒石当轩倚，悬泉度牖飞。","鹿麛冲妓席，鹤子曳童衣。","园果尝难遍，池莲摘未稀。","卷帘唯待月，应在醉中归。"],"theme":"山水田园","theme2":["咏史怀古"],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["园林"],"cats":{"抒情":["怀古"],"山水":["瀑布"]},"theme_conf":0.544},{"uid":"f0952fff-6045-44ee-bc86-cf2192e23e7c","title":"题禅院","author":"喻凫","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["无花地亦香，有鹤松多直。","向此奚必孤，山僧尽相识。"],"theme":"闲适隐逸","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["园林","花"],"cats":{"抒情":["孤独"],"山水":["西湖"],"人生":["哲理"]},"theme_conf":0.68},{"uid":"b9615ed8-64d5-4106-b37e-feca45697b6c","title":"送杨皞擢第游江南","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["行人临水去，新咏复新悲。","万里高秋月，孤山远别时。","挂帆严子濑，酹酒敬亭祠。"],"theme":"送别","theme2":[],"style":"豪放","style2":["悲慨"],"mood":"悲怆","mood2":["孤寂"],"scene":["江南","江"],"cats":{"抒情":["伤感","孤独"],"山水":["西湖"]},"theme_conf":0.825},{"uid":"e40d3f8a-7e0c-47df-b0a4-f2e55fded03a","title":"陪包谏议湖墅路中举帆","author":"权德舆","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["萧萧凉雨歇，境物望中闲。","风际片帆去，烟中独鸟还。","断桥通远浦，野墅接秋山。","更喜陪清兴，尊前一解颜。"],"theme":"山水田园","theme2":["山水田园"],"style":"冲淡","style2":[],"mood":"欢愉","mood2":["孤寂","恬淡"],"scene":["舟"],"cats":{"抒情":["孤独"],"山水":["西湖"],"生活":["写桥"]},"theme_conf":0.88},{"uid":"c1b6399b-c2e2-4a61-8d15-b3362da6d6b0","title":"题灵台县东山村主人","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["处处征胡人渐稀，山村寥落暮烟微。","门临莽苍经年闭，身逐嫖姚几日归。","贫妻白发输残税，余寇黄河未解围。","天子如今能用武，祗应岁晚息兵机。"],"theme":"山水田园","theme2":["边塞征战"],"style":"雄浑","style2":["沉郁"],"mood":"恬淡","mood2":[],"scene":["山","江"],"cats":{"山水":["黄河"],"生活":["乡村"]},"theme_conf":0.356},{"uid":"cd66d8b3-abe6-4316-ab34-b88a4bb8bb83","title":"杂曲歌辞 北风行","author":"李白","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["烛龙栖寒门，光曜犹旦开。","日月照之何不及此，惟有北风怒号天上来。","燕山雪花大如席，片片吹落轩辕台。","幽州思妇十二月，停歌罢笑双蛾摧。","倚门望行人，念君长城苦寒良可哀。","别时提劒救边去，遗此虎文金髀钗。","中有一双白羽箭，蜘蛛结网生尘埃。","箭空在，人今战死不复回。","不忍见此物，焚之已成灰。","黄河捧土尚可塞，北风雨雪恨难裁。"],"theme":"边塞征战","theme2":["闺情宫怨"],"style":"豪放","style2":[],"mood":"相思","mood2":["悲怆","愁怨"],"scene":["雪","冬","雨"],"cats":{"抒情":["闺怨"],"山水":["黄河"],"天气":["写风"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.317},{"uid":"80e19627-4051-46fc-806c-da3defb76cd1","title":"陪王侍御同登东山最高顶宴姚通泉晚携酒泛江","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["姚公美政谁与俦，不减昔时陈太丘。","邑中上客有柱史，多暇日陪骢马游。","东山高顶罗珍羞，下顾城郭销我忧。","清江白日落欲尽，复携美人登彩舟。","笛声愤怨哀中流，妙舞逶迤夜未休。","灯前往往大鱼出，听曲低昂如有求。","三更风起寒浪涌，取乐喧呼觉船重。","满空星河光破碎，四座宾客色不动。","请公临深莫相违，回船罢酒上马归。","人生欢会岂有极，无使霜过沾人衣。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":["愁怨"],"scene":["夜","酒","山","江","舟"],"cats":{"山水":["江河"],"天气":["星星"],"人物":["女子"],"食物":["写酒"]},"theme_conf":0.407},{"uid":"3fff5496-d24c-48c6-9c61-0d8925b663fe","title":"登蒲州逍遥楼","author":"明皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["长榆息烽火，高柳静风尘。","卜征巡九洛，展豫出三秦。","昔是潜龙地，今为上理辰。","时平乘道泰，聊赏遇年春。","黄河分地络，飞观接天津。","一览遗芳翰，千载肃如神。"],"theme":"咏史怀古","theme2":["边塞征战"],"style":"旷达","style2":[],"mood":"恬淡","mood2":[],"scene":["楼","江","春"],"cats":{"抒情":["怀古"],"四季":["春天"],"山水":["黄河"],"人生":["战争"]},"theme_conf":0.565},{"uid":"9d974ae6-2223-4fa3-bb66-15a079adec68","title":"送孔巢父赴河南军","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["江城相送阻烟波，况复新秋一雁过。","闻道全师征北虏，更言诸将会南河。","边心杳杳乡人绝，塞草青青战马多。","共许陈琳工奏记，知君名宦未蹉跎。"],"theme":"送别","theme2":["边塞征战"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["江","塞外","秋"],"cats":{"四季":["秋天"],"山水":["江河"],"人物":["父亲"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.403},{"uid":"e2740c24-d6db-4562-81ff-be9f0bfe16e0","title":"闲园即事寄暕公","author":"司空曙","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["欲就东林寄一身，尚怜儿女未成人。","柴门客去残阳在，药圃虫喧秋雨频。","近水方同梅市隐，曝衣多笑阮家贫。","深山兰若何时到，羡与闲云作四邻。"],"theme":"闲适隐逸","theme2":["闲适隐逸","山水田园"],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["园林","秋","雨"],"cats":{"四季":["秋天"],"山水":["庐山"]},"theme_conf":0.78},{"uid":"05dda800-bd7b-43f0-b0f4-6edeafa87e5f","title":"酬孟武昌苦雪","author":"元结","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["积[雪]闲山路，有人到庭前。","云是孟武昌，令献苦雪篇。","长吟未及终，不觉为凄然。","古之贤达者，与世竟何异。","不能救时患，讽谕以全意。","知公惜春物，岂非爱时和。","知公苦阴雪，伤彼灾患多。","奸凶正驱驰，不合问君子。","林莺与野兽，无乃怨于此。","兵兴向九岁，稼穑谁能忧。","何时不发卒，何日不杀牛。","耕者日已少，耕牛日已希。","皇天复何忍，更又恐毙之。","自经危乱来，触物堪伤叹。","见君问我意，只益胸中乱。","山禽饥不飞，山木冻皆折。","悬泉化为冰，寒水近不热。","出门望天地，天地皆昏昏。","时见双峰下，雪中生白云。"],"theme":"民生疾苦","theme2":["山水田园","送别"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["雪","冬"],"cats":{"抒情":["伤感"],"山水":["瀑布"],"天气":["写雪"]},"theme_conf":0.319},{"uid":"cp66426d06db2e64","title":"夜合花","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["柳暝河桥，莺晴台苑，短策频惹春香。","当时夜泊，温柔便入深乡。","词韵窄，酒杯长。","翦蜡花、壶箭催忙。","共追游处，凌波翠陌，连棹横塘。","十年一梦凄凉。","似西湖燕去，吴馆巢荒。","重来万感，依前唤酒银罂。","溪雨急，岸花狂。","趁残鸦、飞过苍茫。","故人楼上，凭谁指与，芳草斜阳。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"清新","style2":["雄浑","豪放"],"mood":"愁怨","mood2":[],"scene":["花","酒","夜","鸟","江南","春"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"山水":["西湖"],"生活":["写桥"]},"theme_conf":0.558},{"uid":"382c265b-130c-43b1-b500-f49215b85f2e","title":"岭南江行","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["瘴江南去入云烟，望尽黄茆是海边。","山腹雨晴添象迹，潭心日暖长蛟涎。","射工巧伺游人影，飓母偏惊旅客船。","从此忧来非一事，岂容华髪待流年。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"慷慨","mood2":["愁怨"],"scene":["江","山","江南"],"cats":{"抒情":["思乡"],"山水":["江河"],"人生":["时光"]},"theme_conf":0.531},{"uid":"b0e51eac-3f11-473d-b3de-f2e9bdc1e74f","title":"自淇涉黄河途中作十三首 七","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["乱流自兹远，倚檝时一望。","遥见楚汉城，崔嵬高山上。","天道昔未测，人心无所向。","屠钓称侯王，龙蛇争霸王。","缅怀多杀戮，顾此生惨怆。","圣代休甲兵，吾其得闲放。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"旷达","style2":[],"mood":"恬淡","mood2":[],"scene":["山","江"],"cats":{"山水":["黄河"]},"theme_conf":0.535},{"uid":"cp870b6030df582d","title":"高阳台","author":"张炎","dynasty":"宋","section":"宋词","form":"词","paragraphs":["接叶巢莺，平波卷絮，断桥斜日归船。","能几番游，看花又是明年。","东风且伴蔷薇住，到蔷薇、春已堪怜。","更凄然。","万绿西泠，一抹荒烟。","当年燕子知何处，但苔深韦曲，草暗斜川。","见说新愁，如今也到鸥边。","无心再续笙歌梦，掩重门、浅醉闲眠。","莫开帘。","怕见飞花，怕听啼鹃。"],"theme":"咏史怀古","theme2":["山水田园"],"style":"清新","style2":[],"mood":"愁怨","mood2":["恬淡"],"scene":["春","鸟"],"cats":{"抒情":["伤感","怀古"],"四季":["春天"],"山水":["西湖"],"生活":["写桥"]},"theme_conf":0.82},{"uid":"c0f731fe-706b-4e7e-a27c-db14c06686e9","title":"相和歌辞 江南曲","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["江南人家多橘树，吴姬舟上织白纻。","土地卑湿饶虫蛇，连木为牌入江住。","江村亥日长为市，落帆渡桥来浦里。","青莎覆城竹为屋，无井家家饮潮水。","长江午日酤春酒，高高酒旗悬江口。","倡楼两岸悬水栅，夜唱竹枝留北客。","江南风土欢乐多，悠悠处处尽经过。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["江","江南"],"cats":{"抒情":["思乡"],"山水":["江河","长江"],"生活":["写桥"]},"theme_conf":0.604},{"uid":"cp334c6d9b3adb62","title":"月下笛","author":"张炎","dynasty":"宋","section":"宋词","form":"词","paragraphs":["万里孤云，清游渐远，故人何处。","寒窗梦里，犹记经行旧时路。","连昌约略无多柳，第一是、难听夜雨。","谩惊回凄悄，相看烛影，拥衾谁语。","张绪。","归何暮。","半零落，依依断桥鸥鹭。","天涯倦旅。","此时心事良苦。","只愁重洒西州泪，问杜曲、人家在否。","恐翠袖、正天寒，犹倚梅花那树。"],"theme":"羁旅思乡","theme2":["咏史怀古"],"style":"沉郁","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["月"],"cats":{"抒情":["思乡","伤感","怀古"],"山水":["西湖"],"天气":["月亮"],"人生":["读书"],"生活":["写桥"]},"theme_conf":0.416},{"uid":"c76247eb-572b-4fa3-8d38-ab33fe686124","title":"江上柳送人","author":"戎昱","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["江柳断肠色，黄丝垂未齐。","人看几重恨，鸟入一枝低。","乡泪正堪落，与君又解携。","相思万里道，春去夕阳西。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["婉约","豪放"],"mood":"愁怨","mood2":["相思"],"scene":["江"],"cats":{"抒情":["思念","伤感"],"山水":["江河"],"植物":["柳树"]},"theme_conf":0.609},{"uid":"2ed9d032-88fc-465d-a637-3a344fcad426","title":"宿新安江深渡馆寄郑州王使君","author":"朱长文","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["霜飞十月中，摇落众山空。","孤馆闭寒木，大江生夜风。","赋诗忙有意，沈约在关东。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["江"],"cats":{"抒情":["孤独"],"山水":["江河","长江"]},"theme_conf":0.86},{"uid":"96b213f7-21b6-47a8-936c-39dde6ca7969","title":"相和歌辞 櫂歌行","author":"徐坚","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["櫂女饰银钩，新妆下翠楼。","霜丝青桂檝，兰栧紫霞舟。","水落金陵曙，风起洞庭秋。","扣船过曲浦，飞帆越回流。","影入桃花浪，香飘杜若洲。","洲长殊未返，萧散云霞晚。","日下大江平，烟生归岸远。","岸远闻潮波，争途游戏多。","因声赵津女，来听采菱歌。"],"theme":"咏史怀古","theme2":["羁旅思乡"],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["江","舟"],"cats":{"抒情":["思乡","怀古"],"四季":["秋天"],"山水":["长江"],"天气":["写云"]},"theme_conf":0.579},{"uid":"2d80a795-beea-4881-b268-de73dc423218","title":"读故许昌薛尚书诗集","author":"郑谷","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["篇篇高且真，真为国风陈。","澹薄虽师古，纵横得意新。","翦裁成几箧，唱和是谁人。","华岳题无敌，黄河句绝伦。","吟残荔枝雨，咏彻海棠春。","李白欺前辈，陶潜仰后尘。","难忘嵩室下，不负蜀江滨。","属思看山眼，冥搜倚树身。","楷模劳梦想，讽诵爽精神。","落笔空追怆，曾蒙借斧斤。"],"theme":"咏物","theme2":[],"style":"冲淡","style2":["豪放"],"mood":"相思","mood2":["恬淡"],"scene":["江"],"cats":{"山水":["黄河"],"食物":["荔枝"]},"theme_conf":1.0},{"uid":"127a633c-22c0-45a6-af3f-21a31f284d5a","title":"曾游","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["泊舟古城下，高阁快登眺。","大江会彭蠡，群峰豁玄峤。","清影涵空明，黛色凝远照。","碑留太史书，词刻长公调。","绝粒感楚囚，丹衷犹照耀。","怀哉不可招，凭阑一悲啸。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":["悲慨"],"mood":"悲怆","mood2":[],"scene":["舟","楼","江","山"],"cats":{"抒情":["伤感"],"山水":["长江"]},"theme_conf":1.0},{"uid":"fc602fe2-1cc5-4eb6-a67e-8dc478e1579c","title":"题汉州西湖","author":"薛能","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["西湖天下名，可以濯吾缨。","况是携家赏，从妨半驿程。","尝茶春味渴，断酒晚怀清。","尽得幽人趣，犹嫌守吏迎。","重湌逢角暮，百事喜诗成。","坐阻湘江谪，谁为话政声。"],"theme":"山水田园","theme2":["咏物","羁旅思乡"],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["江南","江"],"cats":{"抒情":["思乡"],"山水":["西湖"]},"theme_conf":0.7},{"uid":"de08789e-f931-4c88-aece-d70d5c5aa197","title":"送荀道士归庐山","author":"李端","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["先生归有处，欲别笑无言。","绿水到山口，青林连洞门。","月明寻石路，云霁望花源。","早晚还乘鹤，悲歌向故园。"],"theme":"送别","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["欢愉"],"scene":["山"],"cats":{"抒情":["思乡","伤感"],"山水":["庐山"]},"theme_conf":0.522},{"uid":"a42d87f4-4427-4933-90d9-d25d0192f409","title":"元和甲午岁诏书尽征江湘逐客余自武陵赴京宿于都亭有怀续来诸君子","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["雷雨江山起卧龙，武陵樵客蹑仙踪。","十年楚水枫林下，今夜初闻长乐钟。"],"theme":"羁旅思乡","theme2":["山水田园","咏史怀古"],"style":"雄浑","style2":[],"mood":"欢愉","mood2":[],"scene":["江"],"cats":{"抒情":["思乡","怀古"],"山水":["江河"],"植物":["桃花"]},"theme_conf":0.359},{"uid":"23c9e117-1272-4f69-9d77-0d784c91ff39","title":"周先生","author":"元稹","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["寥寥空山岑，冷冷风松林。","流月垂鳞光，悬泉扬高音。","希夷周先生，烧香调琴心。","神力盈三千，谁能还黄金。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["月","山"],"cats":{"山水":["瀑布"]},"theme_conf":1.0},{"uid":"89150285-38e4-480d-87d6-95db4cb9a4ed","title":"自淇涉黄河途中作十三首 四","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["南登滑台上，却望河淇间。","竹树夹流水，孤城对远山。","念兹川路阔，羡尔沙鸥闲。","长想别离处，犹无音信还。"],"theme":"送别","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"孤寂","mood2":["恬淡","相思"],"scene":["江","山"],"cats":{"抒情":["离别","孤独"],"山水":["江河","黄河"]},"theme_conf":0.455},{"uid":"7d89d155-45a6-432d-a873-d00d2917c366","title":"送蔡希曾都尉还陇右因寄高三十五书记","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["蔡子勇成癖，弯弓西射胡。","健儿宁鬬死，壮士耻为儒。","官是先锋得，材缘挑战须。","身轻一鸟过，枪急万人呼。","云幕随开府，春城赴上都。","马头金狎帢，驼背锦糢糊。","咫尺云山路，归飞青海隅。","上公犹宠锡，突将且前驱。","汉使黄河远，凉州白麦枯。","因君问消息，好在阮元瑜。"],"theme":"送别","theme2":["边塞征战"],"style":"绮丽","style2":["悲慨"],"mood":"慷慨","mood2":["悲怆"],"scene":["江","春"],"cats":{"四季":["春天"],"山水":["黄河"],"人生":["战争"]},"theme_conf":0.528},{"uid":"3d46a51d-3295-440e-88f0-1a2985aae729","title":"送李秀才游嵩山","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["嵩山石壁挂飞流，无限神仙在上头。","采得新诗题石壁，老人惆怅不同游。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["山"],"cats":{"山水":["瀑布"]},"theme_conf":0.738},{"uid":"982f789a-c377-4b64-808a-56f36abf9ff0","title":"可叹","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["天上浮云如白衣，斯须改变如苍狗。","古往今来共一时，人生万事无不有。","近者抉眼去其夫，河东女儿身姓柳。","丈夫正色动引经，酆城客子王季友。","群书万卷常暗诵，孝经一通看在手。","贫穷老瘦家卖屐，好事就之为携酒。","豫章太守高帝孙，引为宾客敬颇久。","闻道三年未曾语，小心恐惧闭其口。","太守得之更不疑，人生反复看亦丑。","明月无瑕岂容易，紫气郁郁犹冲斗。","时危可仗真豪俊，二人得置君侧否。","太守顷者领山南，邦人思之比父母。","王生早曾拜颜色，高山之外皆培𪣻。","用为羲和天为成，用平水土地为厚。","王也论道阻江湖，李也丞疑旷前后。","死为星辰终不灭，致君尧舜焉肯朽。","吾辈碌碌饱饭行，风后力牧长回首。"],"theme":"羁旅思乡","theme2":["亲情"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["月","江"],"cats":{"抒情":["思乡"],"山水":["江河"],"天气":["月亮"],"人生":["读书"]},"theme_conf":0.523},{"uid":"8fc09639-9e38-402f-9827-589c1cc161ff","title":"夏日对雨寄朱放拾遗","author":"武元衡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["才非谷永传，无意谒王侯。","小暑金将伏，微凉麦正秋。","远山欹枕见，暮雨闭门愁。","更忆东林寺，诗家第一流。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"沉郁","style2":["旷达"],"mood":"愁怨","mood2":["相思"],"scene":["夏","雨"],"cats":{"抒情":["思念","伤感"],"四季":["夏天"],"山水":["庐山"],"天气":["写雨"]},"theme_conf":0.95},{"uid":"98b9c819-c287-4a62-b844-f08172081922","title":"奉和圣制同刘晃喜雨应制","author":"张说","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["青气含春雨，知从岱岳来。","行云避师出，洒雨待车廻。","厌浥尘清道，空蒙柳映台。","最宜三五夜，晴月九重开。"],"theme":"应制干谒","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["雨"],"cats":{"山水":["泰山"],"天气":["写雨"]},"theme_conf":0.98},{"uid":"72e1b5ac-d83c-483c-a5eb-5b33172fc16f","title":"江北忆崔汶","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["夜问江西客，还知在楚乡。","全身出部伍，尽室逐渔商。","晴日游瓜步，新年对汉阳。","月昏惊浪白，瘴起觉云黄。","望岭家何处，登山泪几行。","闽中传有雪，应且住南康。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"清新","style2":["婉约","沉郁"],"mood":"相思","mood2":[],"scene":["江","山"],"cats":{"抒情":["思念","思乡"],"山水":["江河"],"节日":["春节"]},"theme_conf":0.504},{"uid":"4b0bc117-6db3-4fe7-a7ac-6df03c52a62a","title":"天边行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["天边老人归未得，日暮东临大江哭。","陇右河源不种田，胡骑羌兵入巴蜀。","洪涛滔天风拔木，前飞秃鹙后鸿鹄。","九度附书向洛阳，十年骨肉无消息。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["江"],"cats":{"抒情":["思乡"],"山水":["长江","黄河"],"人生":["梦想"]},"theme_conf":0.425},{"uid":"cp6df3966a4d64dc","title":"卜算子","author":"陆游","dynasty":"宋","section":"宋词","form":"词","paragraphs":["驿外断桥边，寂寞开无主。","已是黄昏独自愁，更著风和雨。","无意苦争春，一任群芳妒。","零落成泥碾作尘，只有香如故。"],"theme":"羁旅思乡","theme2":[],"style":"旷达","style2":["婉约"],"mood":"孤寂","mood2":["愁怨"],"scene":["夜","花","春","雨"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["春天"],"山水":["西湖"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"f0dc1af7-c04b-47b3-a488-a60082869b1b","title":"经埋轮地","author":"蒋冽","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["汉家张御史，晋国绿珠楼。","时代邈已远，共谢洛阳秋。","洛阳大道边，旧地尚依然。","下马独太息，扰扰城市喧。","时人欣绿珠，诗满金谷圆。","千载埋轮地，无人兴一言。","正直死犹忌，况乃未死前。","汨罗有飜浪，恐是嫌屈原。","我闻太古水，上与天相连。","如何一落地，又作九曲泉。","万古惟高步，可以旌我贤。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["端午"],"cats":{"抒情":["孤独"],"山水":["黄河"],"节日":["端午节"]},"theme_conf":1.0},{"uid":"df7ccf42-3d7d-4927-a388-43ec90d7ec7b","title":"送鸿举游江[西]","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["禅客学禅兼学文，出山初似无心云。","从风卷舒来何处，缭绕巴山不得去。","山州古寺好闲居，读尽龙王宫里书。","使君滩头拣石砚，白帝城边寻野蔬。","忽然登高心瞥起，又欲浮杯信流水。","烟波浩淼鱼鸟情，东去三千三百里。","荆门峡断无盘涡，湘平汉阔清光多。","庐山雾开见瀑布，江西月净闻渔歌。","钟陵八郡多名守，半是西方社中友。","与师相见便谈空，想得高斋狮子吼。"],"theme":"送别","theme2":["闲适隐逸","哲理悟道"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["江","山"],"cats":{"山水":["庐山","江河","瀑布"],"人生":["哲理"],"动物":["写鸟"]},"theme_conf":0.351},{"uid":"9ad03d65-0953-4326-8d85-9e69bb02b4de","title":"和西川李尚书汉州微月游房太尉西湖","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["木落汉川夜，西湖悬玉钩。","旌旗环水次，舟檝泛中流。","目极想前事，神交如共游。","瑶琴久已绝，松韵自悲秋。"],"theme":"山水田园","theme2":["边塞征战"],"style":"婉约","style2":["悲慨"],"mood":"悲怆","mood2":[],"scene":["江南","江"],"cats":{"抒情":["伤感"],"山水":["西湖"],"天气":["月亮"]},"theme_conf":0.545},{"uid":"44c8d252-7815-447a-a937-57e4d8cbe30c","title":"平阳寓怀","author":"薛能","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["晋国风流阻洳川，家家弦管路岐边。","曾为郡职随分竹，亦作歌词乞采莲。","北榭远峰闲即望，西湖残景醉常眠。","墙花此日休回避，不是当时恶少年。"],"theme":"咏怀抒感","theme2":["山水田园"],"style":"旷达","style2":[],"mood":"恬淡","mood2":[],"scene":["江南","山","酒"],"cats":{"山水":["西湖"]},"theme_conf":0.9},{"uid":"0a5c5d0f-c729-4ca6-8655-68557df89721","title":"瀑布泉","author":"冷朝阳","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["潺湲半空里，霖落石房边。","风激珠光碎，山欹练影偏。","急流难起浪，迸沫祗如烟。","自古惟今日，凄凉一片泉。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["雨","山"],"cats":{"抒情":["伤感"],"山水":["瀑布"]},"theme_conf":0.737},{"uid":"8e61bd73-2066-410f-88f8-ec41840eeee7","title":"发南康夜泊灨石中","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["倦客乘归舟，春溪杳将暮。","群林结暝色，孤泊有佳趣。","夜山转长江，赤月吐深树。","飒飒松上吹，泛泛花间露。","险石俯潭涡，跳湍碍沿溯。","岂唯垂堂戒，兼以临深惧。","稍出回雁峰，明登斩蛟柱。","连云向重山，杳未见钟路。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"幽峭","style2":["沉郁"],"mood":"孤寂","mood2":[],"scene":["江","夜","山"],"cats":{"抒情":["思乡","孤独"],"山水":["长江"]},"theme_conf":0.571},{"uid":"d9a9bf4b-fba8-424b-b81c-309bcdade7aa","title":"奉和裴令公新成午桥庄绿野堂即事","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["旧径开桃李，新池凿凤皇。","只添丞相阁，不改午桥庄。","远处尘埃少，闲中日月长。","青山为外屏，绿野是前堂。","引水多随势，栽松不趂行。","年华玩风景，春事看农桑。","花妬谢家妓，兰偷荀令香。","游丝飘酒席，瀑布溅琴床。","巢许终身稳，萧曹到老忙。","千年落公便，进退处中央。"],"theme":"应制干谒","theme2":["闲适隐逸","山水田园"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["春","花","酒","月"],"cats":{"四季":["春天"],"山水":["瀑布"],"生活":["写桥"]},"theme_conf":0.97},{"uid":"3f0c3044-abde-40f5-bd9f-ac83fdbe8319","title":"杂曲歌辞 伊州 入破第五","author":"盖嘉运","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["君住孤山下，烟深夜径长。","辕门渡绿水，游苑遶垂杨。"],"theme":"爱情相思","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["夜","山"],"cats":{"抒情":["孤独"],"山水":["西湖"]},"theme_conf":0.62},{"uid":"4e491c2f-c3c8-487f-8e76-63bd0a811b30","title":"庐山谣寄卢侍御虚舟","author":"李白","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["我本楚狂人，凤歌笑孔丘。","手持绿玉杖，朝别黄鹤楼。","五岳寻仙不辞远，一生好入名山游。","庐山秀出南斗傍，屏风九叠云锦张，影落明湖青黛光。","金阙前开二峰长，银河倒挂三石梁。","香炉瀑布遥相望，回厓沓嶂凌苍苍。","翠影红霞映朝日，鸟飞不到吴天长。","登高壮观天地间，大江茫茫去不还。","黄云万里动风色，白波九道流雪山。","好为庐山谣，兴因庐山发。","闲窥石镜清我心，谢公行处苍苔没。","早服还丹无世情，琴心三叠道初成。","遥见仙人彩云里，手把芙蓉朝玉京。","先期汗漫九垓上，愿接卢敖游太清。"],"theme":"山水田园","theme2":["送别","闲适隐逸"],"style":"绮丽","style2":["豪放"],"mood":"欢愉","mood2":["慷慨"],"scene":["山"],"cats":{"山水":["庐山","长江","瀑布"],"天气":["写云"]},"theme_conf":0.353},{"uid":"927908c0-999f-4d3f-8192-d67d28f93576","title":"八阵图","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["功盖三分国，名高八阵图。","江流石不转，遗恨失吞吴。"],"theme":"题画咏艺","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["江","江南"],"cats":{"山水":["江河"]},"theme_conf":0.603},{"uid":"a15343da-3f7e-4d97-8df0-6d9a5b567a40","title":"秋思二首 一","author":"马戴","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["万木秋霖后，孤山夕照余。","田园无岁计，寒近忆樵渔。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["秋"],"cats":{"抒情":["思念","孤独"],"四季":["秋天"],"山水":["西湖"],"生活":["田园"]},"theme_conf":1.0},{"uid":"ed927451-c3fd-4566-97a2-c86f8c2fa756","title":"行官张望补稻畦水归","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["东屯大江北，百顷平若案。","六月青稻多，千畦碧泉乱。","插秧适云已，引溜加溉灌。","更仆往方塘，决渠当断岸。","公私各地著，浸润无天旱。","主守问家臣，分明见溪伴。","芊芊炯翠羽，剡剡生银汉。","欧鸟镜里来，关山云边看。","秋菰成黑米，精凿传白粲。","玉粒足晨炊，红鲜任霞散。","终然添旅食，作苦期壮观。","遗穗及众多，我仓戒滋蔓。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"绮丽","style2":[],"mood":"慷慨","mood2":[],"scene":["秋","七夕"],"cats":{"抒情":["思乡"],"四季":["秋天"],"山水":["长江"],"生活":["田园"],"节日":["七夕节"]},"theme_conf":0.531},{"uid":"b07e39b5-eafc-4493-a320-454e7a81149a","title":"玄都观","author":"蜀太后徐氏","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["千寻绿嶂夹流溪，登眺因知海岳低。","瀑布迸舂青石碎，轮茵横翦翠峰齐。","步黏苔藓龙桥滑，日闭烟罗鸟径迷。","莫道穹天无路到，此山便是碧云梯。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"山水":["瀑布"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"9532d5be-e0a2-4623-aaf5-322a8b90d1ea","title":"暮秋扬子江寄孟浩然","author":"刘眘虚","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["木叶纷纷下，东南日烟霜。","林山相晚暮，天海空青苍。","暝色况复久，秋声亦何长。","孤舟兼微月，独夜仍越乡。","寒笛对京口，故人在襄阳。","咏思劳今夕，江汉遥相望。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["相思"],"scene":["秋","江"],"cats":{"抒情":["友情","孤独"],"四季":["秋天"],"山水":["江河","长江"]},"theme_conf":0.86},{"uid":"4f743153-575a-413e-b217-b10d18c723e9","title":"瀑布","author":"施肩吾","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["豁开青冥颠，写出万丈泉。","如裁一条素，白日悬秋天。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"山水":["瀑布"]},"theme_conf":0.65},{"uid":"7448b7d5-4a3b-40f9-9174-5b0405dd04b0","title":"庐山瀑布","author":"徐凝","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["虚空落泉千仞直，雷奔入江不暂息。","今古长如白练飞，一条界破青山色。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"山水":["庐山","瀑布"]},"theme_conf":1.0},{"uid":"687eb62a-e2af-449a-b1d5-4a8a7c0c6f09","title":"招隐寺送阎判官还江州","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["离别那逢秋气悲，东林更作上方期。","共知客路浮云外，暂爱僧房坠叶时。","长江九派人归少，寒岭千重雁度迟。","借问浔阳在何处，每看潮落一相思。"],"theme":"送别","theme2":[],"style":"悲慨","style2":[],"mood":"相思","mood2":["悲怆"],"scene":["江"],"cats":{"抒情":["离别","思念","伤感"],"山水":["庐山","江河","长江"]},"theme_conf":0.426},{"uid":"d1734c10-cff7-42c7-8763-0b04378a3864","title":"感石榴二十韵","author":"元稹","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["何年安石国，万里贡榴花。","迢递河源道，因依汉使槎。","酸辛犯葱岭，顦顇涉龙沙。","初到摽珍木，多来比乱麻。","深抛故园里，少种贵人家。","唯我荆州见，怜君胡地赊。","从教当路长，兼恣入檐斜。","绿叶裁烟翠，红英动日华。","新帘帬透影，疎牖烛笼纱。","委作金炉燄，飘成玉砌瑕。","乍惊珠缀密，终误绣帏奢。","琥珀烘梳碎，燕支嬾颊涂。","风翻一树火，电转五云车。","绛帐迎宵日，芙蕖绽早牙。","浅深俱隐映，前后各分葩。","宿露低莲脸，朝光借绮霞。","暗虹徒缴绕，濯锦莫周遮。","俗态能嫌旧，芳姿尚可嘉。","非专爱颜色，同恨阻幽遐。","满眼思乡泪，相嗟亦自嗟。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["花","园林"],"cats":{"抒情":["思乡","伤感"],"山水":["黄河"],"人物":["老师"]},"theme_conf":0.504},{"uid":"8e4dd8bd-be62-478f-bd88-f6db89276125","title":"相和歌辞 明妃曲","author":"王偃","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["北望单于日半斜，明君马上泣胡沙。","一双泪滴黄河水，应得东流入汉家。"],"theme":"边塞征战","theme2":["咏史怀古"],"style":"婉约","style2":["沉郁"],"mood":"悲怆","mood2":["愁怨"],"scene":["江"],"cats":{"抒情":["伤感","怀古"],"山水":["黄河"]},"theme_conf":0.56},{"uid":"da88e355-99df-4d78-9680-2f61b0bf8336","title":"秦州杂诗二十首 十","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["云气接昆仑，涔涔塞雨繁。","羌童看渭水，使客向河源。","烟火军中幕，牛羊岭上村。","所居秋草净，正闭小蓬门。"],"theme":"边塞征战","theme2":["山水田园"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["塞外","秋","雨"],"cats":{"四季":["秋天"],"山水":["黄河"],"生活":["边塞"]},"theme_conf":0.481},{"uid":"287bc2ee-eb64-4d40-9f02-07052ccea9ca","title":"奉送刘相公江淮催转运","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["国用资戎事，臣劳为主忧。","将徴任土贡，更发济川舟。","拥传星还去，过池凤不留。","唯高饮水节，稍浅别家愁。","落叶淮边雨，孤山海上秋。","遥知谢公兴，微月上江楼。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["江","秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"山水":["江河","西湖"]},"theme_conf":0.54},{"uid":"ab07dac2-299a-485a-bc5f-41450e4a41e0","title":"杂曲","author":"李益","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["妾本蚕家女，不识贵门仪。","藁砧持玉斧，交结五陵儿。","十日或一见，九日在路岐。","人生此夫壻，富贵欲何为。","杨柳徒可折，南山不可移。","妇人贵结发，宁有再嫁资。","嫁女莫望高，女心愿所宜。","宁从贱相守，不愿贵相离。","蓝叶郁重重，蓝花若榴色。","少妇归少年，华光自相得。","谁言配君子，以奉百年身。","有义即夫壻，无义还他人。","爱如寒炉火，弃若秋风扇。","山岳起面前，相看不相见。","丈夫非小儿，何用强相知。","不见朝生菌，易成还易衰。","征客欲临路，居人还出门。","北风河梁上，四野愁云繁。","岂不恋我家，夫壻多感恩。","前程有日月，勋绩在河源。","少妇马前立，请君听一言。","春至草亦生，谁能无别情。","殷勤展心素，见新莫忘故。","遥望孟门山，殷勤报君子。","既为随阳雁，勿学西流水。","尝闻生别离，悲莫悲于此。","同器不同荣，堂下即千里。","与君贫贱交，何异萍上水。","托身天使然，同生复同死。"],"theme":"送别","theme2":["羁旅思乡"],"style":"豪放","style2":["悲慨"],"mood":"悲怆","mood2":[],"scene":["秋","山"],"cats":{"抒情":["离别","思乡","伤感","感恩"],"四季":["秋天"],"山水":["黄河"],"天气":["写风"],"人物":["儿童"],"人生":["青春"]},"theme_conf":0.616},{"uid":"c5c4e4d0-682a-4c8f-9756-c181dc9a52dc","title":"杂曲歌辞 羽林行","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["朔雪寒断指，朔风劲裂冰。","胡中射雕者，此日犹不能。","翩翩羽林儿，锦臂飞苍鹰。","挥鞭决白马，走出黄河凌。"],"theme":"山水田园","theme2":["边塞征战"],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["冬","江"],"cats":{"四季":["冬天"],"山水":["黄河"],"天气":["写风"]},"theme_conf":0.509},{"uid":"c1854cf4-5d46-4e9f-b6c2-5d29f71a57cd","title":"奉和幸韦嗣立山庄侍宴应制","author":"李峤","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["南洛师臣契，东岩王佐居。","幽情遗绂冕，宸眷属樵渔。","制下峒山跸，恩回灞水舆。","松门驻旌盖，薜幄引簪裾。","石磴平黄陆，烟楼半紫虚。","云霞仙路近，琴酒俗尘疎。","乔木千龄外，悬泉百丈余。","崖深经炼药，穴古旧藏书。","树宿抟风鸟，池潜纵壑鱼。","宁知天子贵，尚忆武侯庐。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"山水":["瀑布"],"天气":["写云"]},"theme_conf":0.98},{"uid":"4e70707e-2204-4948-9632-492fb98e6a20","title":"送顾非熊秀才归丹阳","author":"王建","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["江城柳色海门烟，欲到茅山始下船。","知道君家当瀑布，菖蒲潭在草堂前。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["舟","江","山"],"cats":{"山水":["瀑布"]},"theme_conf":0.776},{"uid":"98ce6f68-fa8f-42b6-a5d6-5447079d3a04","title":"相和歌辞 公无渡河","author":"王建","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["渡头恶天两岸远，波涛塞川如叠坂。","幸无白刃驱向前，何用将身自弃捐。","蛟龙啮尸鱼食血，黄泥直下无青天。","男儿纵轻妇人语，惜君性命还须取。","妇人无力挽断衣，舟沈身死悔难追，公无渡河公自为。"],"theme":"咏史怀古","theme2":["边塞征战"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["塞外","舟"],"cats":{"抒情":["怀古"],"山水":["江河"],"生活":["边塞"]},"theme_conf":0.55},{"uid":"1130a58d-d738-46e6-8052-1252a540540d","title":"江边星月二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["江月辞风缆，江星别雾船。","鸡鸣还曙色，鹭浴自清川。","历历竟谁种，悠悠何处圆。","客愁殊未已，他夕始相鲜。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["月","江"],"cats":{"抒情":["思乡","伤感"],"山水":["江河"],"天气":["月亮","星星"]},"theme_conf":1.0},{"uid":"7109feaf-91db-4b77-a50e-3e71c6a4c66c","title":"送韦讽上阆州录事参军","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["国步犹艰难，兵革未衰息。","万方哀嗷嗷，十载供军食。","庶官务割剥，不暇忧反侧。","诛求何多门，贤者贵为德。","韦生富春秋，洞彻有清识。","操持纪纲地，喜见朱丝直。","当令豪夺吏，自此无颜色。","必若救疮痍，先应去蟊贼。","挥泪临大江，高天意凄恻。","行行树佳政，慰我深相忆。"],"theme":"边塞征战","theme2":["送别"],"style":"豪放","style2":[],"mood":"愁怨","mood2":[],"scene":["春","秋"],"cats":{"抒情":["伤感"],"四季":["春天","秋天"],"山水":["长江"]},"theme_conf":0.464},{"uid":"bbd2ad8c-e1cd-4b4e-afb2-8464e20188d2","title":"别崔法曹","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["欲作别离西入秦，芝田枣迳往来频。","东湖此夕更留醉，逢著庐山学道人。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["山"],"cats":{"抒情":["离别"],"山水":["庐山"]},"theme_conf":1.0},{"uid":"ef119060-f85f-444a-a103-4a07a56d1202","title":"自淇涉黄河途中作十三首 十三","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["皤皤河滨叟，相遇似有耻。","辍榜聊问之，荅言尽终结。","一生虽贫贱，九十年未死。","且喜对儿孙，弥慙远城市。","结庐黄河曲，垂钓长河里。","漫漫望云沙，萧条听风水。","所思强饭食，永愿在乡里。","万事吾不知，其心只如此。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"欢愉","mood2":["相思","悲怆"],"scene":["江"],"cats":{"抒情":["思乡"],"山水":["江河","黄河"]},"theme_conf":0.519},{"uid":"88d529e0-7481-45fa-8568-bf134ec06a59","title":"界围岩水帘","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["界围汇湘曲，青壁环澄流。","悬泉粲成帘，罗注无时休。","韵磬叩凝碧，锵锵彻岩幽。","丹霞冠其巅，想像凌虚游。","灵境不可状，鬼工谅难求。","忽如朝玉皇，天冕垂前旒。","楚臣昔南逐，有意仍丹丘。","今我始北旋，新诏释缧囚。","采真诚眷恋，许国无淹留。","再来寄幽梦，遗贮催行舟。"],"theme":"山水田园","theme2":["闺情宫怨"],"style":"婉约","style2":["清新","绮丽"],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"抒情":["闺怨"],"山水":["瀑布"]},"theme_conf":0.492},{"uid":"b96312f4-ef5f-41aa-86fa-488e23c8f5ce","title":"奉和展礼岱宗涂经濮济","author":"薛克构","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["龙图冠胥陆，凤驾指云亭。","非烟泛济浦，绿字启河汀。","画裳晨应月，文戟曙分星。","四田巡揖礼，三驱道契经。","行欣奉万岁，窃抃偶千龄。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["山","月","江"],"cats":{"山水":["泰山"]},"theme_conf":0.97},{"uid":"b3ac6bba-d692-4203-9bef-62c9decf88a4","title":"行路难","author":"冯著","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["男儿𫐘轲徒搔首，入市脱衣且沽酒。","行路难，权门慎勿干，平人争路相摧残。","春秋四气更回换，人事何须再三叹。","君不见雀为鸽，鹰为鸠，东海成田谷为岸。","负薪客，归去来，龟反顾，鹤裴回，黄河岸上起尘埃。","相逢未相识，何用强相猜。","行路难，故山应不改，茅舍汉中在。","白酒杯中聊一歌，苍蝇苍蝇奈尔何。"],"theme":"羁旅思乡","theme2":["闲适隐逸"],"style":"豪放","style2":[],"mood":"相思","mood2":[],"scene":["酒","江"],"cats":{"抒情":["思念","思乡"],"山水":["黄河"]},"theme_conf":0.521},{"uid":"765fdf4b-1622-4468-a1d7-809dff28a441","title":"姑熟杂咏 天门山","author":"李赤","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["迥出江水上，双峰自相对。","岸映松色寒，石分浪花碎。","参差远天际，缥缈晴霞外。","落日舟去遥，回首沈青霭。"],"theme":"咏物","theme2":["山水田园"],"style":"幽峭","style2":[],"mood":"孤寂","mood2":[],"scene":["山"],"cats":{"山水":["泰山"]},"theme_conf":0.509},{"uid":"dedab53e-3cb6-4689-a4e9-538a0aaeb005","title":"郊庙歌辞 封泰山乐章 豫和 三","author":"张说","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["相百辟，贡八荒。","九歌敍，万舞翔。","肃振振，铿皇皇。","帝欣欣，福穰穰。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"山水":["泰山"]},"theme_conf":1.0},{"uid":"d093922e-8afb-4b35-a3dd-be3fca63e29c","title":"入华山访隐者经仙人石坛","author":"李益","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["三考四岳下，官曹少休沐。","久负青山诺，今还获所欲。","尝闻玉清洞，金简受玄箓。","夙驾升天行，云游恣霞宿。","平明矫轻策，扪石入空曲。","仙人古石坛，苔遶青瑶局。","阳桂凌烟紫，阴萝冒水绿。","隔世闻丹经，悬泉注明玉。","前惊羽人会，白日天居肃。","问我将致辞，笑之自相目。","竦身云遂起，仰见双白鹄。","堕其一纸书，文字类鸟足。","视之了不识，三返又三复。","归来问方士，举世莫解读。","何必若蜉蝣，然后为跼促。","鄙哉宦游子，身志俱降辱。","再往不及期，劳歌叩山木。"],"theme":"游仙梦幻","theme2":["山水田园"],"style":"旷达","style2":["幽峭","绮丽"],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"山水":["瀑布"]},"theme_conf":0.493},{"uid":"cfefd449-c8d9-4b64-b391-480f64682615","title":"陪王使君晦日泛江就黄家亭子二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["有径金沙软，无人碧草芳。","野畦连蛱蝶，江槛俯鸳鸯。","日晚烟花乱，风生锦绣香。","不须吹急管，衰老易悲伤。"],"theme":"爱情相思","theme2":[],"style":"绮丽","style2":[],"mood":"悲怆","mood2":["孤寂"],"scene":["江","花"],"cats":{"抒情":["爱情","伤感","孤独"],"山水":["江河"],"天气":["太阳"]},"theme_conf":1.0},{"uid":"6497789f-342b-4c89-b330-b32ee23cb12f","title":"郊庙歌辞 封泰山乐章 肃和","author":"张说","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["奠祖配天，承天享帝。","百灵咸秩，四海来祭。","植我苍璧，布我玄制。","华日裴回，神烟容裔。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"山水":["泰山"]},"theme_conf":1.0},{"uid":"1798fcfb-db04-4e2e-8eb0-e191e869662e","title":"江行无题一百首 六","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["晚来渔父喜，罾重欲收迟。","恐有长江使，金钱愿赎龟。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["江"],"cats":{"山水":["江河","长江"]},"theme_conf":1.0},{"uid":"64d3f88f-ce69-4ea3-8646-5635a7ed9139","title":"江村即事","author":"司空曙","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["钓罢归来不系船，江村月落正堪眠。","纵然一夜风吹去，只在芦花浅水边。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["江"],"cats":{"山水":["江河"],"生活":["乡村"]},"theme_conf":1.0},{"uid":"4ed14233-782c-4837-9c21-d6b8de27518b","title":"水帘吟","author":"薛能","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["万滴相随万响兼，路尘天产尽旁沾。","源从颢气何因绝，派助前溪岂觉添。","豪客每来清夏葛，愁人才见认愁簷。","嘉名已极终难称，别是风流不是帘。"],"theme":"山水田园","theme2":["送别","闺情宫怨"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["夏"],"cats":{"抒情":["伤感","闺怨"],"四季":["夏天"],"山水":["瀑布"]},"theme_conf":0.451},{"uid":"89948763-087c-4404-b98d-eedc526849ec","title":"同李员外贺哥舒大夫破九曲之作","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["遥传副丞相，昨日破西蕃。","作气群山动，扬军大斾翻。","奇兵邀转战，连孥绝归奔。","泉喷诸戎血，风驱死虏魂。","头飞攒万戟，面缚聚辕门。","鬼哭黄埃暮，天愁白日昏。","石城与岩险，铁骑皆云屯。","长策一言决，高踪百代存。","威棱慑沙漠，忠义感乾坤。","老将黯无色，儒生安敢论。","解围凭庙算，止杀报君恩。","唯有关河渺，苍茫空树墩。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"悲怆","mood2":["愁怨"],"scene":["山","塞外"],"cats":{"抒情":["伤感"],"山水":["黄河"],"人生":["战争"]},"theme_conf":0.492},{"uid":"1913f5e2-b937-40ac-ba4b-ea09007d13e1","title":"黄河二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["黄河西岸是吾蜀，欲须供给家无粟。","愿驱众蔗戴君王，混一车书弃金玉。"],"theme":"民生疾苦","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["江"],"cats":{"山水":["江河","黄河"]},"theme_conf":0.72},{"uid":"84817a87-9ee4-4fc1-8207-68ba2ef51bc0","title":"杂曲歌辞 荆州泊","author":"李端","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["南楼西下时，月里闻来棹。","桂水舳舻回，荆州津济闹。","移帷望星汉，引带思容貌。","今夜一江人，惟应妾身觉。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["月","楼","舟","夜","江"],"cats":{"抒情":["闺怨"],"山水":["江河"]},"theme_conf":1.0},{"uid":"b2c9ad7d-19b9-4f75-8adf-ea9fcc4e1a84","title":"西湖留别","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["征途行色惨风烟，祖帐离声咽管弦。","翠黛不须留五马，皇恩只许住三年。","绿藤阴下铺歌席，红藕花中泊妓船。","处处回头尽堪恋，就中难别是湖边。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["江南","江"],"cats":{"抒情":["离别"],"山水":["西湖"]},"theme_conf":1.0},{"uid":"a6fc5b12-6130-47da-8aea-c3778a946943","title":"嵩山天门歌","author":"宋之问","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["登天门兮坐盘石之磷𥒘，前漎漎兮未半，下漠漠兮无垠。","纷窈窕兮岩倚披以鹏翅，洞胶葛兮峰棱层以龙鳞。","松移岫转，左变而右易。","风生云起，出鬼而入神。","吾亦不知其灵怪如此，愿游杳冥兮见羽人。","重曰：天门兮穹崇，回合兮攒藂。","松万接兮柱日，石千寻兮倚空。","晚阴兮足风，夕阳兮赩红。","试一望兮夺魄，况众妙之无穷。"],"theme":"山水田园","theme2":[],"style":"幽峭","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"山水":["泰山"]},"theme_conf":0.654},{"uid":"f3900a71-2d1e-4099-81d9-2f4e099b0940","title":"秋夜闻鴈寄南十五兼呈空和尚","author":"张南史","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["晚节闻君道趣深，结茅栽树近东林。","禅师几度曾摩顶，高士何年更发心。","北渚三更闻过鴈，西城万木动寒砧。","不见支公与玄度，相思拥膝坐长吟。"],"theme":"寄赠酬答","theme2":["送别"],"style":"冲淡","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["夜","秋"],"cats":{"抒情":["思念"],"四季":["秋天"],"山水":["庐山"]},"theme_conf":0.9},{"uid":"527eba4b-b35c-4d29-99e7-8f40c6f3d5b7","title":"杂曲歌辞 行路难三首 一","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["金尊清酒斗十千，玉盘珍羞直万钱。","停杯投筯不能食，拔劒四顾心茫然。","欲渡黄河冰塞川，将登太行雪暗天。","闲来垂钓坐溪上，忽复乘舟梦日边。","行路难，行路难，多岐路，今安在？长风破浪会有时，直挂云帆济沧海。"],"theme":"咏怀抒感","theme2":["山水田园","哲理悟道"],"style":"豪放","style2":["绮丽"],"mood":"恬淡","mood2":["慷慨","惆怅"],"scene":["酒","江","舟"],"cats":{"山水":["黄河"],"人生":["励志"]},"theme_conf":0.95},{"uid":"9c56b83a-34f3-4a30-a7fe-c0f7bb2fcac1","title":"送夏侯审参军游江东","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["袖中多丽句，未遣世人闻。","醉夜眠江月，闲时逐海云。","荻花寒漫漫，鸥鸟暮群群。","若到长沙苑，渔家更待君。"],"theme":"送别","theme2":["边塞征战","山水田园"],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":["江","夏","夜"],"cats":{"四季":["夏天"],"山水":["江河"]},"theme_conf":0.375},{"uid":"81d2c0f7-48ad-4b35-b142-9ed40165e8e2","title":"孟生诗","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["孟生江海士，古貌又古心。","尝读古人书，谓言古犹今。","作诗三百首，窅默咸池音。","骑驴到京国，欲和熏风琴。","岂识天子居，九重郁沈沈。","一门百夫守，无籍不可寻。","晶光荡相射，旗戟翩以森。","迁延乍却走，惊怪靡自任。","举头看白日，泣涕下沾襟。","朅来游公卿，莫肯低华簪。","谅非轩冕族，应对多差参。","萍蓬风波急，桑榆日月侵。","奈何从进士，此路转岖嵚。","异质忌处群，孤芳难寄林。","谁怜松桂性，竞爱桃李阴。","朝悲辞树叶，夕感归巢禽。","顾我多慷慨，穷檐时见临。","清宵静相对，发白聆苦吟。","采兰起幽念，眇然望东南。","秦吴修且阻，两地无数金。","我论徐方牧，好古天下钦。","竹实凤所食，德馨神所歆。","求观众丘小，必上泰山岑。","求观众流细，必泛沧溟深。","子其听我言，可以当所箴。","既获则思返，无为久滞淫。","卞和试三献，期子在秋砧。"],"theme":"山水田园","theme2":[],"style":"悲慨","style2":["旷达"],"mood":"悲怆","mood2":["相思"],"scene":["山","秋","月"],"cats":{"抒情":["伤感"],"四季":["秋天"],"山水":["泰山"]},"theme_conf":0.647},{"uid":"cf8aa5b6-2baa-45ef-af3c-7a1f04138f8a","title":"故武卫将军挽歌三首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["舞劒过人绝，鸣弓射兽能。","铦锋行惬顺，猛噬失𫏋腾。","赤羽千夫膳，黄河十月冰。","横行沙漠外，神速至今称。"],"theme":"边塞征战","theme2":["悼亡挽歌"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["江","塞外","月","冬"],"cats":{"抒情":["悼亡"],"山水":["黄河"]},"theme_conf":0.536},{"uid":"b5d52c7f-9cd4-4805-8b40-47771a17af7b","title":"赠别晋三处士","author":"高适","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["有人家住清河源，渡河问我游梁园。","手持道经注已毕，心知内篇口不言。","卢门十年见秋草，此心惆怅谁能道。","知己从来不易知，慕君为人与君好。","别时九月桑叶疎，出门千里无行车。","爱君且欲君先达，今上求贤早上书。"],"theme":"送别","theme2":[],"style":"旷达","style2":[],"mood":"惆怅","mood2":[],"scene":["秋","月"],"cats":{"抒情":["友情","离别"],"四季":["秋天"],"山水":["黄河"]},"theme_conf":1.0},{"uid":"9649f4dc-e18d-4b00-bb8c-018e0d725b03","title":"远寺钟","author":"司空曙","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["杳杳疎钟发，因风清复引。","中宵独听之，似与东林近。"],"theme":"哲理悟道","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["夜"],"cats":{"抒情":["孤独"],"山水":["庐山"]},"theme_conf":1.0},{"uid":"fb5a52a2-c14b-4302-b5b1-ab18d92348ab","title":"自淇涉黄河途中作十三首 九","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["朝从北岸来，泊船南河浒。","试共野人言，深觉农夫苦。","去秋虽薄熟，今夏犹未雨。","耕耘日勤劳，租税兼舃卤。","园蔬空寥落，产业不足数。","尚有献芹心，无因见明主。"],"theme":"民生疾苦","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["江","夏","秋","舟","雨","园林"],"cats":{"四季":["夏天","秋天"],"山水":["江河","黄河"]},"theme_conf":0.636},{"uid":"6b773a93-eddb-44b8-a00e-82cd2dfe4af5","title":"唐封泰山乐章 寿和","author":"张说","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["烝烝我后，享献惟寅。","躬酌郁鬯，跪奠明神。","孝莫孝乎，配上帝亲。","敬莫敬乎，教天下臣。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"山水":["泰山"]},"theme_conf":1.0},{"uid":"8e44e405-1497-4a50-8d60-2a6d66979a92","title":"放鱼","author":"窦巩","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["金钱赎得免刀痕，闻道禽鱼亦感恩。","好去长江千万里，不须辛苦上龙门。"],"theme":"边塞征战","theme2":[],"style":"旷达","style2":["豪放"],"mood":"慷慨","mood2":[],"scene":["江"],"cats":{"抒情":["感恩"],"山水":["长江"]},"theme_conf":0.65}];
